-- ============================================================

WITH new_rows (seq, topic_id, qtext, opts, correct, expl, subtheme, srccode, batch, exam, tracks) AS (
 VALUES
(1, 'FARM-09',
   'Którego z poniższych efektów nie wykazują benzodiazepiny:',
   '[{"id": "a", "text": "Przeciwlękowe"}, {"id": "b", "text": "Przeciwdepresyjne"}, {"id": "c", "text": "Nasenne"}, {"id": "d", "text": "Uspokajające"}, {"id": "e", "text": "Miorelaksacyjne"}]'::jsonb,
   'b',
   $E$**Benzodiazepiny** działają allosterycznie na receptor **GABA-A**, zwiększając **częstość otwarć** kanału chlorkowego. Stąd pięć klasycznych efektów: **przeciwlękowy**, **uspokajająco-nasenny**, **miorelaksacyjny** (ośrodkowy, przez neurony wstawkowe rdzenia), **przeciwdrgawkowy** oraz **niepamięć następcza**. Działania **przeciwdepresyjnego** nie mają — nie wpływają na przekaźnictwo monoaminergiczne; u chorego z depresją łagodzą jedynie doraźnie lęk i bezsenność, a przewlekle grożą tolerancją i uzależnieniem.$E$,
   'Benzodiazepiny', 'FARSTO-e2026-1-1873', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(2, 'FARM-08',
   'Hipertermia, skurcze mięśniowe, zaburzenia rytmu serca, zaburzenia krążenia i zaburzenia świadomości to objawy charakterystyczne dla:',
   '[{"id": "a", "text": "Zespołu serotoninowego, który może pojawić się przy łączeniu selektywnych inhibitorów wychwytu serotoniny z inhibitorami MAO"}, {"id": "b", "text": "Zespołu czerwonego człowieka, który może pojawić się po podaniu antybiotyków glikopeptydowych"}, {"id": "c", "text": "Przedawkowania kolchicyny"}, {"id": "d", "text": "Przedawkowania glikozydów nasercowych"}, {"id": "e", "text": "Niedodawkowania insuliny"}]'::jsonb,
   'a',
   $E$Triada **zespołu serotoninowego**: objawy **autonomiczne** (hipertermia, tachykardia, zaburzenia rytmu i krążenia), **nerwowo-mięśniowe** (mioklonie, wzmożone odruchy, sztywność) i **psychiczne** (pobudzenie, splątanie). Najgroźniejsza interakcja to **SSRI z inhibitorami MAO**; ryzyko dają też tramadol, tryptany, linezolid i MDMA. Przy zmianie SSRI na IMAO obowiązuje przerwa **14 dni** (fluoksetyna — **5 tygodni**). Leczenie: odstawienie leku, chłodzenie, **benzodiazepiny**, **cyproheptadyna**.$E$,
   'Zespół serotoninowy', 'FARSTO-e2026-1-1874', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(3, 'FARM-08',
   'Zaznacz zdanie fałszywe:',
   '[{"id": "a", "text": "Amitryptylina może być stosowana w terapii depresji, a także w profilaktyce migreny"}, {"id": "b", "text": "Propranolol może być stosowany w profilaktyce migreny"}, {"id": "c", "text": "Buspiron ma działanie przeciwlękowe"}, {"id": "d", "text": "Bupropion może być stosowany w leczeniu ciężkiej depresji"}, {"id": "e", "text": "Escitalopram może być stosowany do leczenia ciężkiej depresji"}]'::jsonb,
   'e',
   $E$**Amitryptylina** (TLPD) i **propranolol** mają udowodnioną skuteczność w **profilaktyce migreny**, a **buspiron** — częściowy agonista **5-HT1A** — jest anksjolitykiem niebenzodiazepinowym, więc pierwsze trzy stwierdzenia są prawdziwe. Wariant o escitalopramie w **ciężkiej depresji** uznano za fałszywy, ponieważ (zwłaszcza w postaci melancholicznej) przewagę skuteczności mają **TLPD** i **wenlafaksyna**, a **SSRI** pozostają lekami z wyboru w epizodach łagodnych i umiarkowanych. Rozgraniczenie względem **bupropionu** jest jednak dyskusyjne.$E$,
   'Leki przeciwdepresyjne', 'FARSTO-e2026-1-1875', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(4, 'FARM-08',
   'Lekiem zwiększającym popęd płciowy u kobiet jest:',
   '[{"id": "a", "text": "Sertralina"}, {"id": "b", "text": "Flibanseryna"}, {"id": "c", "text": "Felbamat"}, {"id": "d", "text": "Trazodon"}, {"id": "e", "text": "Amitryptylina"}]'::jsonb,
   'b',
   $E$**Flibanseryna** to agonista receptora **5-HT1A** i antagonista **5-HT2A**, który w korze przedczołowej zwiększa stężenie **dopaminy i noradrenaliny**, a obniża **serotoniny** — stąd wzrost popędu płciowego. Wskazanie: **hipoaktywne zaburzenie pożądania seksualnego (HSDD)** u kobiet przed menopauzą; przyjmowana codziennie wieczorem. Przeciwwskazany **alkohol** i **inhibitory CYP3A4** (ryzyko hipotonii i omdleń). Odwrotny efekt dają **SSRI** i **TLPD**, które libido obniżają.$E$,
   'Zaburzenia popędu płciowego', 'FARSTO-e2026-1-1876', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(5, 'FARM-03',
   'Wybierz zdanie fałszywe:',
   '[{"id": "a", "text": "NLPZ znacznie osłabiają działanie diuretyków pętlowych"}, {"id": "b", "text": "Duże dawki NLPZ mogą zmniejszać działanie hipoglikemizujące pochodnych sulfonylomocznika"}, {"id": "c", "text": "Użycie NLPZ zwiększa ryzyko krwawienia z górnego odcinka przewodu pokarmowego"}, {"id": "d", "text": "Użycie NLPZ zwiększa ryzyko drgawek w czasie terapii fluorochinolonami"}, {"id": "e", "text": "Użycie NLPZ w trakcie leczenia aminoglikozydami może spowodować zaburzenia czynności nerek"}]'::jsonb,
   'b',
   $E$Fałsz dotyczy **pochodnych sulfonylomocznika**: NLPZ wypierają je z połączeń z **albuminami** i hamują ich metabolizm, więc **nasilają** hipoglikemię, a nie ją osłabiają. Pozostałe zdania są prawdziwe — blokada **COX** zmniejsza nerkową syntezę **PGE2/PGI2**, osłabiając diuretyki pętlowe i nasilając nefrotoksyczność aminoglikozydów; z **fluorochinolonami** NLPZ wypierają **GABA** z receptora (drgawki), a hamowanie **COX-1** znosi cytoprotekcję błony śluzowej żołądka.$E$,
   'Interakcje NLPZ', 'FARSTO-e2026-1-1877', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(6, 'FARM-02',
   'Do przerywania napadu migreny można stosować:',
   '[{"id": "a", "text": "Sumatryptan, Lasmiditan, Propranolol"}, {"id": "b", "text": "Propranolol, Ergotamina, Kwas acetylosalicylowy"}, {"id": "c", "text": "Sumatryptan, Ubrogepant, Ibuprofen"}, {"id": "d", "text": "Naproksen, Metoprolol, Kwas walproinowy"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'c',
   $E$Napad przerywają: **NLPZ** (ibuprofen, ASA, naproksen), **tryptany** — agoniści **5-HT1B/1D** (sumatryptan), **gepanty** — antagoniści receptora **CGRP** (ubrogepant, rimegepant), **ditany** — agoniści **5-HT1F** (lasmiditan) oraz alkaloidy sporyszu. Warianty z propranololem, metoprololem i kwasem walproinowym dyskwalifikuje obecność leków **profilaktycznych**: **propranololu**, **metoprololu** i **kwasu walproinowego**, które przewlekle zmniejszają częstość napadów, ale nie przerywają już rozpoczętego bólu.$E$,
   'Migrena', 'FARSTO-e2026-1-1878', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(7, 'FARM-02',
   'W profilaktyce napadów migreny można stosować:',
   '[{"id": "a", "text": "Kwas acetylosalicylowy"}, {"id": "b", "text": "Ibuprofen"}, {"id": "c", "text": "Erenumab"}, {"id": "d", "text": "Lasmiditan"}, {"id": "e", "text": "Kodeina"}]'::jsonb,
   'c',
   $E$**Erenumab** to przeciwciało monoklonalne blokujące **receptor CGRP** (pozostałe — fremanezumab, galkanezumab — wiążą sam ligand), podawane **podskórnie raz w miesiącu** w profilaktyce migreny przewlekłej i epizodycznej. Klasyczne leki profilaktyczne to także **propranolol**, **topiramat**, **kwas walproinowy**, **amitryptylina** i **flunaryzyna**. ASA, ibuprofen i **lasmiditan** działają **doraźnie**, a **kodeina** grozi bólem głowy z nadużywania leków.$E$,
   'Migrena', 'FARSTO-e2026-1-1879', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(8, 'FARM-02',
   'Które z poniższych nie jest wskazaniem do podania antagonistów receptora H1:',
   '[{"id": "a", "text": "Pokrzywka"}, {"id": "b", "text": "Alergiczny nieżyt nosa"}, {"id": "c", "text": "Alergie polekowe"}, {"id": "d", "text": "Alergie po ukłuciach owadów"}, {"id": "e", "text": "Wybroczyny"}]'::jsonb,
   'e',
   $E$**Wybroczyny** są objawem **skazy krwotocznej** — małopłytkowej lub naczyniowej — i nie mają związku z uwalnianiem **histaminy**, więc **blokery H1** są tu bezużyteczne. Pozostałe wskazania wynikają wprost z blokady receptorów **H1** w skórze i błonach śluzowych: pokrzywka, **alergiczny nieżyt nosa**, odczyny polekowe i reakcje po ukłuciach owadów. Leki **I generacji**, przenikające do OUN, dodatkowo działają przeciwwymiotnie, przeciw chorobie lokomocyjnej i nasennie.$E$,
   'Leki przeciwhistaminowe', 'FARSTO-e2026-1-1880', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(9, 'FARM-02',
   'Które leki pełnią rolę blokera histaminowego H1 oraz stabilizatora błony komórkowej mastocytów:',
   '[{"id": "a", "text": "Ketotyfen, Azelastyna"}, {"id": "b", "text": "Hydroksyzyna, Prometazyna"}, {"id": "c", "text": "Antazolina, Loratadyna"}, {"id": "d", "text": "Cetyryzyna, Hydroksyzyna"}, {"id": "e", "text": "Nedokromil, Lewocetyryzyna"}]'::jsonb,
   'a',
   $E$**Ketotyfen** i **azelastyna** mają podwójny mechanizm: blokują receptor **H1** i **stabilizują błonę mastocytów**, hamując ich degranulację oraz uwalnianie histaminy i leukotrienów — stąd zastosowanie w alergicznym zapaleniu spojówek i nosa, z efektem zarówno doraźnym, jak i profilaktycznym. **Nedokromil** i kromoglikan są wyłącznie stabilizatorami mastocytów, bez powinowactwa do H1, natomiast **cetyryzyna**, **loratadyna**, **hydroksyzyna** i **prometazyna** to czyści antagoniści H1.$E$,
   'Leki przeciwhistaminowe', 'FARSTO-e2026-1-1881', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(10, 'FARM-02',
   'Antagonistą receptora 5-HT2 jest:',
   '[{"id": "a", "text": "Cyproheptadyna"}, {"id": "b", "text": "Metoklopramid"}, {"id": "c", "text": "Azelastyna"}, {"id": "d", "text": "Sumatryptan"}, {"id": "e", "text": "Ondansetron"}]'::jsonb,
   'a',
   $E$**Cyproheptadyna** łączy blokadę receptorów **H1** i **5-HT2**, dlatego jest antidotum w **zespole serotoninowym** i bywa stosowana jako lek pobudzający apetyt. Pozostałe leki działają na inne receptory: **ondansetron** blokuje **5-HT3** (przeciwwymiotny), **metoklopramid** jest antagonistą **D2** i agonistą **5-HT4**, **sumatryptan** agonistą **5-HT1B/1D**, a **azelastyna** antagonistą **H1**. Silnymi antagonistami **5-HT2A** są też ketanseryna i neuroleptyki atypowe.$E$,
   'Receptory serotoninowe', 'FARSTO-e2026-1-1882', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(11, 'FARM-06',
   'Wskaż lek będący diuretykiem osmotycznym:',
   '[{"id": "a", "text": "hydrochlorotiazyd"}, {"id": "b", "text": "torasemid"}, {"id": "c", "text": "bumetanid"}, {"id": "d", "text": "mannitol"}, {"id": "e", "text": "acetazolamid"}]'::jsonb,
   'd',
   $E$**Mannitol** to niemetabolizowany alkohol cukrowy, swobodnie filtrowany w kłębuszku i niewchłaniany zwrotnie — zwiększa **osmolalność moczu pierwotnego**, zatrzymując wodę głównie w **cewce proksymalnej** i **ramieniu zstępującym pętli Henlego**. Wskazania: **obrzęk mózgu**, ostry napad **jaskry**, wymuszona diureza w zatruciach. Pozostałe leki mają inne cele: **hydrochlorotiazyd** blokuje kotransporter **Na/Cl**, **torasemid** i **bumetanid** — **NKCC2**, a **acetazolamid** hamuje **anhydrazę węglanową**.$E$,
   'Leki moczopędne', 'FARSTO-e2026-1-1883', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(12, 'FARM-17',
   'Insuliną krótko i szybko działającą jest:',
   '[{"id": "a", "text": "glarginowa"}, {"id": "b", "text": "detemir"}, {"id": "c", "text": "degludec"}, {"id": "d", "text": "lispro"}, {"id": "e", "text": "brak prawidłowej odpowiedzi"}]'::jsonb,
   'd',
   $E$**Lispro** — obok **aspart** i **glulizynowej** — to **analog szybko działający**: zamiana kolejności aminokwasów w łańcuchu B utrudnia tworzenie heksamerów, więc działanie zaczyna się po **ok. 15 min**, szczyt przypada na **1 h**, a całość trwa **3-5 h**; podaje się je tuż przed posiłkiem. **Glargina**, **detemir** i **degludec** to analogi **długo działające**, praktycznie bezszczytowe, odtwarzające wydzielanie podstawowe insuliny.$E$,
   'Insulinoterapia', 'FARSTO-e2026-1-1884', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(13, 'FARM-12',
   'Do krótkodziałających beta2-mimetyków zaliczamy:',
   '[{"id": "a", "text": "salmeterol, formoterol"}, {"id": "b", "text": "salbutamol, fenoterol"}, {"id": "c", "text": "terbutalina, budezonid"}, {"id": "d", "text": "indakaterol, salmeterol"}, {"id": "e", "text": "wilanterol, salbutamol"}]'::jsonb,
   'b',
   $E$**Salbutamol** i **fenoterol** (a także **terbutalina**) to **krótko działające beta2-mimetyki (SABA)** — początek działania po kilku minutach, czas **4-6 h**, stosowane doraźnie w napadzie duszności. **Salmeterol** i **formoterol** to **LABA** (ok. **12 h**), a **indakaterol** i **wilanterol** — ultra-LABA działające **24 h**, wyłącznie przewlekle i w astmie zawsze łącznie z wziewnym glikokortykosteroidem. Wariant z terbutaliną dyskwalifikuje **budezonid**, który jest właśnie takim GKS.$E$,
   'Leki rozszerzające oskrzela', 'FARSTO-e2026-1-1885', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(14, 'FARM-07',
   'Lekiem inotropowo dodatnim stosowanym w leczeniu ostrej niewydolności serca, będącym inhibitorem fosfodiesterazy typu 3 jest:',
   '[{"id": "a", "text": "dobutamina"}, {"id": "b", "text": "milrynon"}, {"id": "c", "text": "lewozymendan"}, {"id": "d", "text": "digitoksyna"}, {"id": "e", "text": "wazopresyna"}]'::jsonb,
   'b',
   $E$**Milrynon** hamuje **fosfodiesterazę typu 3**, zwiększając stężenie **cAMP** w kardiomiocycie (napływ **Ca2+** i efekt inotropowy dodatni) oraz w miocytach naczyń (rozkurcz, spadek obciążenia następczego) — stąd nazwa **inodilator**. Działa niezależnie od receptorów beta, więc zachowuje skuteczność u chorych leczonych **beta-blokerami**. Ograniczenia: **hipotonia**, **arytmie komorowe** i wzrost śmiertelności przy dłuższym stosowaniu, dlatego tylko krótkotrwały wlew dożylny.$E$,
   'Leki inotropowo dodatnie', 'FARSTO-e2026-1-1886', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(15, 'FARM-07',
   'Lekiem inotropowo dodatnim stosowanym w leczeniu ostrej niewydolności serca, należącym do grupy tzw. uczulaczy wapniowych (calcium sensitizers) jest:',
   '[{"id": "a", "text": "dobutamina"}, {"id": "b", "text": "milrynon"}, {"id": "c", "text": "lewozymendan"}, {"id": "d", "text": "digitoksyna"}, {"id": "e", "text": "wazopresyna"}]'::jsonb,
   'c',
   $E$**Lewozymendan** wiąże się z **troponiną C** w sposób zależny od stężenia wapnia i zwiększa **wrażliwość miofilamentów na Ca2+**, poprawiając kurczliwość **bez wzrostu stężenia Ca2+** w kardiomiocycie — dlatego nie podnosi zużycia tlenu ani ryzyka arytmii tak jak katecholaminy. Dodatkowo otwiera kanały **K-ATP** w naczyniach, rozszerzając tętnice i żyły. Aktywny metabolit **OR-1896** przedłuża efekt hemodynamiczny do **7-9 dni** po zakończeniu wlewu.$E$,
   'Leki inotropowo dodatnie', 'FARSTO-e2026-1-1887', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(16, 'FARM-07',
   'Statyną, która nie zwiększa ryzyka wystąpienia cukrzycy typu 2 jest:',
   '[{"id": "a", "text": "simwastatyna"}, {"id": "b", "text": "atorwastatyna"}, {"id": "c", "text": "pitawastatyna"}, {"id": "d", "text": "rozuwastatyna"}, {"id": "e", "text": "prawastatyna"}]'::jsonb,
   'c',
   $E$**Pitawastatyna** jako jedyna statyna nie pogarsza gospodarki węglowodanowej — w badaniach nie zwiększała ryzyka **cukrzycy typu 2**, a nawet nieznacznie podnosiła stężenie **adiponektyny**. Ryzyko nowych zachorowań rośnie wraz z intensywnością terapii i dotyczy głównie **rozuwastatyny**, **atorwastatyny** i **simwastatyny** w dużych dawkach (upośledzenie wydzielania insuliny i nasilenie insulinooporności). Pitawastatyna jest też mało zależna od **CYP3A4**, więc rzadko wchodzi w interakcje.$E$,
   'Statyny', 'FARSTO-e2026-1-1888', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(17, 'FARM-16',
   'Inhibitorem steroidogenezy nadnerczowej w mechanizmie hamowania aktywności 17,20-liazy steroidowej jest:',
   '[{"id": "a", "text": "Aminoglutetymid"}, {"id": "b", "text": "Ketokonazol"}, {"id": "c", "text": "Metyrapon"}, {"id": "d", "text": "Trilostan"}, {"id": "e", "text": "Osilodrostat"}]'::jsonb,
   'b',
   $E$**Ketokonazol**, pochodna imidazolowa, hamuje nie tylko grzybiczą, ale i ludzką rodzinę **CYP450**, w tym **CYP17 (17-alfa-hydroksylaza / 17,20-liaza)**, blokując syntezę androgenów i kortyzolu — stąd użycie w **zespole Cushinga**. Ogranicza go **hepatotoksyczność** i liczne interakcje przez **CYP3A4**. Pozostałe leki działają na inne enzymy: **metyrapon** i **osilodrostat** hamują **11-beta-hydroksylazę**, **trilostan** — **3-beta-dehydrogenazę steroidową**, a **aminoglutetymid** — desmolazę.$E$,
   'Inhibitory steroidogenezy', 'FARSTO-e2026-1-1889', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(18, 'FARM-16',
   'Inhibitorem steroidogenezy nadnerczowej, który hamuje powstawanie pregnenolonu z cholesterolu jest:',
   '[{"id": "a", "text": "Aminoglutetymid"}, {"id": "b", "text": "Ketokonazol"}, {"id": "c", "text": "Metyrapon"}, {"id": "d", "text": "Trilostan"}, {"id": "e", "text": "Osilodrostat"}]'::jsonb,
   'a',
   $E$**Aminoglutetymid** blokuje **desmolazę cholesterolową (CYP11A1)**, czyli enzym pierwszego i ograniczającego etapu steroidogenezy — przekształcenia **cholesterolu w pregnenolon**. Hamuje więc syntezę wszystkich hormonów kory nadnerczy, wywołując **adrenalektomię farmakologiczną** z koniecznością substytucji hydrokortyzonem, a jako **inhibitor aromatazy I generacji** ogranicza też obwodową produkcję estrogenów. Enzymy blokowane przez pozostałe leki leżą niżej w szlaku steroidogenezy.$E$,
   'Inhibitory steroidogenezy', 'FARSTO-e2026-1-1890', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(19, 'FARM-16',
   'Glikokortykosteroidem o największej relatywnej sile działania jest:',
   '[{"id": "a", "text": "Hydrokortyzon"}, {"id": "b", "text": "Prednizon"}, {"id": "c", "text": "Prednizolon"}, {"id": "d", "text": "Metyloprednizolon"}, {"id": "e", "text": "Betametazon"}]'::jsonb,
   'e',
   $E$**Betametazon** i jego izomer **deksametazon** mają **25-30x** większą siłę glikokortykoidową niż **hydrokortyzon** (siła referencyjna = 1) i są praktycznie pozbawione komponenty **mineralokortykoidowej**. Należą do preparatów **długo działających** (biologiczny okres półtrwania **36-54 h**), stąd zastosowanie w obrzęku mózgu i stymulacji dojrzewania płuc płodu. **Prednizon** i **prednizolon** są ok. **4x**, a **metyloprednizolon** ok. **5x** silniejsze od hydrokortyzonu.$E$,
   'Glikokortykosteroidy', 'FARSTO-e2026-1-1891', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(20, 'FARM-16',
   'Działaniem niepożądanym przewlekłego stosowania glikokortykosteroidów nie jest:',
   '[{"id": "a", "text": "Osteoporoza"}, {"id": "b", "text": "Jaskra"}, {"id": "c", "text": "Zaćma"}, {"id": "d", "text": "Hiperkalemia"}, {"id": "e", "text": "Nadciśnienie tętnicze"}]'::jsonb,
   'd',
   $E$Przewlekła sterydoterapia wywołuje **hipokaliemię**, a nie hiperkaliemię: pobudzenie receptora **mineralokortykoidowego** w cewce zbiorczej zwiększa resorpcję **Na+** i wody (stąd nadciśnienie i obrzęki) kosztem utraty **K+** oraz **H+**, co grozi zasadowicą metaboliczną. Pozostałe powikłania są typowe — **osteoporoza** (hamowanie osteoblastów i wchłaniania wapnia), **zaćma** podtorebkowa tylna i **jaskra** ze wzrostu oporu odpływu cieczy wodnistej. Dochodzą hiperglikemia i miopatia.$E$,
   'Glikokortykosteroidy', 'FARSTO-e2026-1-1892', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(21, 'FARM-13',
   'Do działania niepożądanego trimetoprymu należy:',
   '[{"id": "a", "text": "Leukopenia"}, {"id": "b", "text": "Nudności i wymioty"}, {"id": "c", "text": "Wysypka"}, {"id": "d", "text": "Niedokrwistość megaloblastyczna"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'e',
   $E$**Trimetoprim** hamuje **reduktazę dihydrofolianową** — wybiórczo bakteryjną, ale przy dużych dawkach i długiej terapii również ludzką, co daje **niedokrwistość megaloblastyczną**, **leukopenię** i małopłytkowość (odtrutką jest **kwas folinowy**). Dochodzą typowe dla kotrimoksazolu **nudności i wymioty** oraz odczyny skórne, aż po zespół **Stevensa-Johnsona**. Warto pamiętać też o **hiperkaliemii** — trimetoprim blokuje kanał **ENaC** w cewce zbiorczej, działając jak amilorid.$E$,
   'Sulfonamidy i trimetoprim', 'FARSTO-e2026-1-1893', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(22, 'FARM-13',
   'Do cefalosporyn IV generacji należy:',
   '[{"id": "a", "text": "Cefadroksyl"}, {"id": "b", "text": "Cefaklor"}, {"id": "c", "text": "Ceftazydym"}, {"id": "d", "text": "Cefuroksym"}, {"id": "e", "text": "Cefepim"}]'::jsonb,
   'e',
   $E$**Cefepim** to jedyna w zestawie cefalosporyna **IV generacji** — łączy szerokie działanie na bakterie **Gram-ujemne** (w tym **Pseudomonas aeruginosa**) z zachowaną aktywnością wobec gronkowców i paciorkowców, jest oporny na beta-laktamazy typu **AmpC** i dobrze przenika do OUN. Pozostałe leki to: **cefadroksyl** — I generacja, **cefaklor** i **cefuroksym** — II, a **ceftazydym** — III generacja, antypseudomonasowa, ale słaba wobec ziarenkowców Gram-dodatnich.$E$,
   'Cefalosporyny', 'FARSTO-e2026-1-1894', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(23, 'FARM-14',
   'Do działań niepożądanych, które mogą wystąpić w czasie stosowania ogólnego acyklowiru należą:',
   '[{"id": "a", "text": "Nudności i wymioty"}, {"id": "b", "text": "Odwracalne uszkodzenie nerek"}, {"id": "c", "text": "Drgawki"}, {"id": "d", "text": "Drżenia mięśniowe"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'e',
   $E$**Acyklowir** jest prolekiem aktywowanym przez wirusową **kinazę tymidynową**, stąd duża wybiórczość, ale przy podaniu ogólnym możliwe są wszystkie wymienione objawy. Kluczowa jest **nefrotoksyczność** — wytrącanie kryształów leku w cewkach przy szybkim wlewie dożylnym i odwodnieniu, odwracalna po nawodnieniu i zwolnieniu infuzji. Wtórnie do kumulacji w niewydolności nerek pojawia się **neurotoksyczność**: drżenia mięśniowe, splątanie i **drgawki**.$E$,
   'Leki przeciwwirusowe', 'FARSTO-e2026-1-1895', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(24, 'FARM-14',
   'Do działań niepożądanych, które mogą wystąpić w czasie stosowania ogólnego gancyklowiru należą:',
   '[{"id": "a", "text": "Zaparcia"}, {"id": "b", "text": "Nadmierna senność"}, {"id": "c", "text": "Bladość skóry"}, {"id": "d", "text": "Obniżona temperatura ciała"}, {"id": "e", "text": "Neuropatia obwodowa"}]'::jsonb,
   'e',
   $E$**Gancyklowir**, analog nukleozydowy czynny wobec **CMV** i fosforylowany przez wirusową kinazę **UL97**, poza dominującą **mielosupresją** wywołuje objawy neurologiczne — **neuropatię obwodową**, splątanie, drgawki. Pozostałe opcje są odwrotnością rzeczywistego profilu: typowa jest **biegunka**, nie zaparcia, oraz **gorączka**, nie hipotermia; bladość powłok bywa jedynie wtórna do niedokrwistości. Lek działa **teratogennie** i hamuje spermatogenezę, więc wymaga antykoncepcji.$E$,
   'Leki przeciwwirusowe', 'FARSTO-e2026-1-1896', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(25, 'FARM-14',
   'Do nukleozydowych i nukleotydowych inhibitorów odwrotnej transkryptazy nie należy:',
   '[{"id": "a", "text": "Zydowudyna"}, {"id": "b", "text": "Abakawir"}, {"id": "c", "text": "Atazanawir"}, {"id": "d", "text": "Lamiwudyna"}, {"id": "e", "text": "Emtrycytabina"}]'::jsonb,
   'c',
   $E$Końcówka **-nawir** zdradza inhibitor **proteazy HIV**: **atazanawir** blokuje cięcie poliprotein Gag-Pol, a typowa jest dla niego **niesprzężona hiperbilirubinemia** oraz konieczność kwaśnego środowiska żołądka (interakcja z **IPP**). Pozostałe to **NRTI** hamujące **odwrotną transkryptazę** po wewnątrzkomórkowej fosforylacji: **zydowudyna** (mielosupresja), **lamiwudyna** i **emtrycytabina** (czynne też wobec HBV) oraz **abakawir**, groźny nadwrażliwością u nosicieli **HLA-B*5701**.$E$,
   'Leczenie zakażenia HIV', 'FARSTO-e2026-1-1897', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(26, 'FARM-14',
   'Do natychmiastowych działań niepożądanych amfoterycyny B należy:',
   '[{"id": "a", "text": "Nefrotoksyczność"}, {"id": "b", "text": "Hepatotoksyczność"}, {"id": "c", "text": "Obniżenie ciśnienia tętniczego"}, {"id": "d", "text": "Niedokrwistość"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'c',
   $E$Tylko **spadek ciśnienia tętniczego** należy do **reakcji infuzyjnej** — pojawiającej się w trakcie lub tuż po wlewie triady: **gorączka, dreszcze, hipotonia**, z nudnościami i dusznością; zapobiega jej powolny wlew i premedykacja paracetamolem, lekiem przeciwhistaminowym i hydrokortyzonem. **Nefrotoksyczność** (z hipokaliemią i hipomagnezemią), **niedokrwistość** ze spadku erytropoetyny oraz uszkodzenie wątroby to powikłania **późne**, zależne od dawki skumulowanej.$E$,
   'Leki przeciwgrzybicze', 'FARSTO-e2026-1-1898', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(27, 'FARM-14',
   'Wskaż zdanie prawdziwe na temat jodochinolu:',
   '[{"id": "a", "text": "Wykazuje aktywność jedynie w tkankach w przypadku zakażenia Entamoeba histolytica"}, {"id": "b", "text": "Stosowany jest wraz z metronidazolem w celu leczenia bezobjawowej amebiozy"}, {"id": "c", "text": "Nie ma wpływu na funkcje tarczycy"}, {"id": "d", "text": "Należy zachować ostrożność podczas stosowania leku u osób z zaburzeniami funkcji tarczycy i neuropatią wzrokową"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'd',
   $E$**Jodochinol** to amebicyd **kontaktowy**, działający wyłącznie w **świetle jelita**, bo prawie się nie wchłania — to obala twierdzenie o aktywności jedynie w tkankach. W **amebiozie bezobjawowej** wystarcza sam lek luminalny, bez **metronidazolu**, a zawarty w cząsteczce **jod** zaburza testy czynności tarczycy i może wywołać wole. Przy długim stosowaniu opisywano **zapalenie nerwu wzrokowego** i podostrą neuropatię rdzeniowo-wzrokową, stąd ostrożność przy zaburzeniach tarczycy i neuropatii wzrokowej.$E$,
   'Leki przeciwpierwotniakowe', 'FARSTO-e2026-1-1899', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(28, 'FARM-09',
   'Do leków znieczulających miejscowo o budowie amidowej należy:',
   '[{"id": "a", "text": "Prokaina"}, {"id": "b", "text": "Proksymetakaina"}, {"id": "c", "text": "Oksybuprokaina"}, {"id": "d", "text": "Bupiwakaina"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'd',
   $E$**Bupiwakaina** zawiera wiązanie **amidowe**, podobnie jak lidokaina, mepiwakaina, ropiwakaina i stosowana w stomatologii **artykaina**. Mnemonik: **amidy mają dwie litery „i” w nazwie** (bup-i-wakaina, l-i-doka-i-na), estry tylko jedną (prokaina, proksymetakaina, oksybuprokaina). Różnica jest praktyczna: amidy metabolizuje **wątroba (CYP)**, estry rozkłada **esteraza osoczowa** do **PABA** — częstej przyczyny alergii. Bupiwakaina jest najbardziej **kardiotoksyczna**.$E$,
   'Leki znieczulające miejscowo', 'FARSTO-e2026-1-1900', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(29, 'FARM-01',
   'Metabolizmu pierwszego przejścia można uniknąć przy podaniu:',
   '[{"id": "a", "text": "Doustnym"}, {"id": "b", "text": "Podjęzykowym"}, {"id": "c", "text": "Dożylnym"}, {"id": "d", "text": "Odpowiedzi A i C są prawidłowe"}, {"id": "e", "text": "Odpowiedzi B i C są prawidłowe"}]'::jsonb,
   'e',
   $E$**Efekt pierwszego przejścia** to metabolizm leku w ścianie jelita i **wątrobie** zaraz po wchłonięciu z przewodu pokarmowego, zanim trafi do krążenia dużego — dotyczy drogi **doustnej** i obniża **biodostępność** (klasycznie nitrogliceryna, propranolol, lidokaina). Omijają go podania **podjęzykowe** (spływ krwi do żyły głównej górnej), **dożylne**, domięśniowe, przezskórne i wziewne, a częściowo doodbytnicze — stąd omijają je podanie podjęzykowe i dożylne.$E$,
   'Drogi podania leków', 'FARSTO-e2026-1-1901', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(30, 'FARM-02',
   'Do antagonistów receptora histaminowego H1 pierwszej generacji nie należy:',
   '[{"id": "a", "text": "Antazolina"}, {"id": "b", "text": "Azelastyna"}, {"id": "c", "text": "Doksylamina"}, {"id": "d", "text": "Prometazyna"}, {"id": "e", "text": "Klemastyna"}]'::jsonb,
   'b',
   $E$**Azelastyna** należy do **II generacji** leków przeciwhistaminowych — słabo przenika przez barierę krew-mózg i stosowana miejscowo (donosowo, do worka spojówkowego) praktycznie nie powoduje senności. Pozostałe — **antazolina**, **doksylamina**, **prometazyna** i **klemastyna** — to klasyczne leki **I generacji**: lipofilne, silnie **sedatywne**, o dodatkowym działaniu **antymuskarynowym** (suchość w ustach, zatrzymanie moczu) oraz przeciwwymiotnym.$E$,
   'Leki przeciwhistaminowe', 'FARSTO-e2026-1-1902', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(31, 'FARM-05',
   'Do przeciwwskazań bezwzględnych do stosowania leków przeciwzakrzepowych należy:',
   '[{"id": "a", "text": "Guz mózgu"}, {"id": "b", "text": "Skaza krwotoczna"}, {"id": "c", "text": "Źle kontrolowane nadciśnienie tętnicze"}, {"id": "d", "text": "Retinopatia cukrzycowa"}, {"id": "e", "text": "Ostre zapalenie wsierdzia"}]'::jsonb,
   'b',
   $E$Bezwzględnym przeciwwskazaniem jest **skaza krwotoczna** — wrodzone lub nabyte zaburzenie hemostazy (hemofilia, głęboka małopłytkowość, ciężka niewydolność wątroby) — obok czynnego krwawienia i świeżego **udaru krwotocznego**, bo ryzyko krwotoku przewyższa tu każdą korzyść. Pozostałe stany: **guz mózgu**, źle kontrolowane **nadciśnienie**, **retinopatia cukrzycowa** i zapalenie wsierdzia to przeciwwskazania **względne**, wymagające indywidualnej oceny bilansu ryzyka.$E$,
   'Leki przeciwkrzepliwe', 'FARSTO-e2026-1-1903', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(32, 'FARM-06',
   'Pochodną niedihydropirydynową w grupie antagonistów kanałów wapniowych jest:',
   '[{"id": "a", "text": "Nifedypina"}, {"id": "b", "text": "Amlodypina"}, {"id": "c", "text": "Werapamil"}, {"id": "d", "text": "Nimodypina"}, {"id": "e", "text": "Lacydypina"}]'::jsonb,
   'c',
   $E$**Werapamil** jest **fenyloalkiloaminą**, a więc antagonistą wapnia **niedihydropirydynowym** — razem z benzotiazepinowym **diltiazemem**. Ta grupa działa głównie na **serce**: zwalnia rytm zatokowy i przewodzenie w węźle **przedsionkowo-komorowym** oraz obniża kurczliwość, stąd zastosowanie w częstoskurczach nadkomorowych i zakaz łączenia z **beta-blokerami** (bradykardia, blok AV). Wszystkie leki z końcówką **-dypina** to pochodne **dihydropirydyny** działające na naczynia.$E$,
   'Antagoniści kanałów wapniowych', 'FARSTO-e2026-1-1904', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(33, 'FARM-05',
   'Nasilenie działania przeciwkrzepliwego podczas stosowania doustnych antykoagulantów powoduje:',
   '[{"id": "a", "text": "Gryzeofulwina"}, {"id": "b", "text": "Ryfampicyna"}, {"id": "c", "text": "Karbamazepina"}, {"id": "d", "text": "Cyprofloksacyna"}, {"id": "e", "text": "Barbiturany"}]'::jsonb,
   'd',
   $E$**Cyprofloksacyna** hamuje **CYP1A2** i **CYP3A4**, zwalniając metabolizm **warfaryny** i **acenokumarolu**, a dodatkowo niszczy florę jelitową wytwarzającą **witaminę K** — INR rośnie, a z nim ryzyko krwawienia. Pozostałe leki to klasyczne **induktory CYP**, które działanie antykoagulantów **osłabiają**; pomaga mnemonik **CRAPGPS**: Carbamazepina, Ryfampicyna, Alkohol przewlekle, Phenytoina, Gryzeofulwina, Phenobarbital, Sulfonylomoczniki.$E$,
   'Interakcje doustnych antykoagulantów', 'FARSTO-e2026-1-1905', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(34, 'FARM-18',
   'Odtrutką stosowaną w zatruciu benzodiazepinami jest:',
   '[{"id": "a", "text": "Izoniazyd"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Błękit metylenowy"}, {"id": "d", "text": "Acetylocysteina"}, {"id": "e", "text": "Neostygmina"}]'::jsonb,
   'b',
   $E$**Flumazenil** jest kompetycyjnym antagonistą miejsca benzodiazepinowego receptora **GABA-A**; podany dożylnie znosi sedację w ciągu 1-2 minut, ale jego okres półtrwania (**ok. 1 h**) bywa krótszy niż benzodiazepiny, więc sedacja może **nawrócić**. Ostrożnie u osób uzależnionych i przy współzatruciu **TLPD** — grozi **drgawkami**. Pozostałe odtrutki: **acetylocysteina** — paracetamol, **błękit metylenowy** — methemoglobinemia, **neostygmina** — kurara niedepolaryzująca.$E$,
   'Odtrutki', 'FARSTO-e2026-1-1906', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(35, 'FARM-14',
   'Najpoważniejszym działaniem niepożądanym gancyklowiru jest:',
   '[{"id": "a", "text": "Wydłużenie odstępu QT"}, {"id": "b", "text": "Nefrotoksyczność"}, {"id": "c", "text": "Mielosupresja"}, {"id": "d", "text": "Występowanie przewlekłych biegunek"}, {"id": "e", "text": "Nawracające migreny"}]'::jsonb,
   'c',
   $E$Ograniczającym dawkę działaniem niepożądanym **gancyklowiru** jest **mielosupresja** — **neutropenia** dotyczy nawet 40% leczonych, częste są też małopłytkowość i niedokrwistość, dlatego konieczna jest regularna kontrola morfologii, a przy głębokiej neutropenii podaje się **G-CSF**. Ryzyko rośnie przy łączeniu z **zydowudyną** i innymi lekami mielotoksycznymi. Dla kontrastu **foskarnet**, alternatywa w zakażeniu **CMV**, jest przede wszystkim **nefrotoksyczny** i wywołuje hipokalcemię.$E$,
   'Leki przeciwwirusowe', 'FARSTO-e2026-1-1907', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(36, 'FARM-03',
   'Lek stosowany w terapii przewlekłej dny moczanowej, który działa poprzez rozkładanie kwasu moczowego do alantoiny to:',
   '[{"id": "a", "text": "febuksostat"}, {"id": "b", "text": "lesynurad"}, {"id": "c", "text": "peglotykaza"}, {"id": "d", "text": "benzbromaron"}, {"id": "e", "text": "allopurynol"}]'::jsonb,
   'c',
   $E$**Peglotykaza** to pegylowana rekombinowana **urykaza** — enzym, którego człowiek nie posiada — utleniająca **kwas moczowy** do znacznie lepiej rozpuszczalnej i łatwo wydalanej **alantoiny**; podawana dożylnie co 2 tygodnie w ciężkiej dnie guzkowatej opornej na leczenie. Grozi **anafilaksją**, a przy niedoborze **G6PD** hemolizą. Inne mechanizmy: **allopurynol** i **febuksostat** hamują **oksydazę ksantynową**, a **lesynurad** i **benzbromaron** to urykozuryki blokujące **URAT1**.$E$,
   'Dna moczanowa', 'FARSTO-e2026-1-1908', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(37, 'FARM-15',
   'Wskaż lek będący antagonistą receptora 5-HT3 stosowany w wymiotach po chemioterapii:',
   '[{"id": "a", "text": "ondansetron"}, {"id": "b", "text": "metoklopramid"}, {"id": "c", "text": "aprepitant"}, {"id": "d", "text": "prochlorperazyna"}, {"id": "e", "text": "dimenhydrynat"}]'::jsonb,
   'a',
   $E$**Ondansetron** blokuje receptory **5-HT3** na zakończeniach nerwu błędnego w jelicie i w **strefie chemoreceptorowej (CTZ)**. Cytostatyki, zwłaszcza **cisplatyna**, uwalniają serotoninę z komórek enterochromatofilnych błony śluzowej, uruchamiając odruch wymiotny — stąd wysoka skuteczność setronów. Typowe działania niepożądane to ból głowy, zaparcia i **wydłużenie QT**. Inne mechanizmy: **aprepitant** blokuje receptor **NK1**, **metoklopramid** i **prochlorperazyna** — **D2**, a **dimenhydrynat** — **H1**.$E$,
   'Leki przeciwwymiotne', 'FARSTO-e2026-1-1909', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(38, 'FARM-06',
   'Który z poniższych leków jest inhibitorem fosfodiesterazy typu 5 stosowanym w leczeniu nadciśnienia płucnego?',
   '[{"id": "a", "text": "bosentan"}, {"id": "b", "text": "riociguat"}, {"id": "c", "text": "sildenafil"}, {"id": "d", "text": "iloprost"}, {"id": "e", "text": "ambrisentan"}]'::jsonb,
   'c',
   $E$**Sildenafil** hamuje **fosfodiesterazę typu 5** rozkładającą **cGMP**, przedłużając naczyniorozszerzające działanie **tlenku azotu** w krążeniu płucnym i obniżając opór płucny. Bezwzględnym przeciwwskazaniem jest jednoczesne stosowanie **azotanów** (groźna hipotonia) oraz **riocyguatu**. Pozostałe leki działają inaczej: **bosentan** i **ambrisentan** blokują receptory **endoteliny**, **iloprost** jest analogiem **prostacykliny**, a **riocyguat** stymulatorem cyklazy guanylanowej.$E$,
   'Nadciśnienie płucne', 'FARSTO-e2026-1-1910', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(39, 'FARM-16',
   'Działaniem niepożądanym glikokortykosteroidów przy długotrwałym ich stosowaniu nie jest:',
   '[{"id": "a", "text": "zespół Cushinga jatrogenny"}, {"id": "b", "text": "osteoporoza"}, {"id": "c", "text": "hiperglikemia"}, {"id": "d", "text": "nadczynność tarczycy"}, {"id": "e", "text": "zwiększona podatność na infekcje"}]'::jsonb,
   'd',
   $E$Glikokortykosteroidy nie wywołują **nadczynności tarczycy** — przeciwnie, hamują wydzielanie **TSH** i obwodową konwersję **T4 do T3**, dlatego w przełomie tarczycowym stosuje się je leczniczo. Pozostałe powikłania są klasyczne: **jatrogenny zespół Cushinga** z otyłością centralną i twarzą księżycowatą, **osteoporoza** posteroidowa, **hiperglikemia** z nasilonej glukoneogenezy i insulinooporności oraz **immunosupresja** sprzyjająca zakażeniom, w tym reaktywacji gruźlicy.$E$,
   'Glikokortykosteroidy', 'FARSTO-e2026-1-1911', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(40, 'FARM-06',
   'Wskaż lek stosowany w nadciśnieniu, który działa poprzez agonizm receptorów imidazolinowych typu pierwszego (I1) w rdzeniu przedłużonym:',
   '[{"id": "a", "text": "klonidyna"}, {"id": "b", "text": "moksonidyna"}, {"id": "c", "text": "metyldopa"}, {"id": "d", "text": "urapidyl"}, {"id": "e", "text": "guanfacyna"}]'::jsonb,
   'b',
   $E$**Moksonidyna** jest wybiórczym agonistą receptorów **imidazolinowych I1** w brzuszno-bocznej części rdzenia przedłużonego, co zmniejsza napięcie **współczulne** i obniża ciśnienie bez typowej dla klonidyny senności i suchości w ustach (klonidyna pobudza dodatkowo receptory **alfa2**). **Metyldopa** to prolek przekształcany w **alfa-metylonoradrenalinę**, lek z wyboru w ciąży, **guanfacyna** działa na **alfa2A**, a **urapidyl** blokuje **alfa1** i pobudza **5-HT1A**.$E$,
   'Leki hipotensyjne działające ośrodkowo', 'FARSTO-e2026-1-1912', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(41, 'FARM-09',
   'Wskaż lek stosowany w znieczuleniu miejscowym o najkrótszym czasie działania:',
   '[{"id": "a", "text": "bupiwakaina"}, {"id": "b", "text": "ropiwakaina"}, {"id": "c", "text": "lidokaina"}, {"id": "d", "text": "prokaina"}, {"id": "e", "text": "tetrakaina"}]'::jsonb,
   'd',
   $E$**Prokaina** jest estrem szybko hydrolizowanym przez **esterazę osoczową**, o małej sile i najkrótszym czasie działania (**ok. 30-60 min**), dziś praktycznie wypartym z lecznictwa. **Lidokaina** działa pośrednio długo (**1-2 h**), a **bupiwakaina**, **ropiwakaina** i **tetrakaina** nawet **4-8 h** dzięki dużej lipofilności i silnemu wiązaniu z białkami. Powstający z prokainy **PABA** odpowiada za reakcje alergiczne i osłabia działanie **sulfonamidów**.$E$,
   'Leki znieczulające miejscowo', 'FARSTO-e2026-1-1913', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(42, 'FARM-12',
   'Wskaż lek stosowany w terapii mukowiscydozy poprawiający funkcję białka CFTR:',
   '[{"id": "a", "text": "erlotynib"}, {"id": "b", "text": "iwakaftor"}, {"id": "c", "text": "bosentan"}, {"id": "d", "text": "sirolimus"}, {"id": "e", "text": "natalizumab"}]'::jsonb,
   'b',
   $E$**Iwakaftor** jest **potencjatorem CFTR** — zwiększa prawdopodobieństwo otwarcia kanału chlorkowego już obecnego w błonie komórkowej, dlatego działa w mutacjach **bramkowania**, klasycznie **G551D**. W najczęstszej mutacji **F508del** łączy się go z **korektorami** (lumakaftor, tezakaftor, eleksakaftor), poprawiającymi fałdowanie i transport białka do błony. To jedyne leczenie **przyczynowe** mukowiscydozy, uzupełniane dornazą alfa i hipertonicznym NaCl.$E$,
   'Mukowiscydoza', 'FARSTO-e2026-1-1914', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(43, 'FARM-01',
   'Wskaż zdanie fałszywe na temat transportu czynnego substancji:',
   '[{"id": "a", "text": "Zachodzi wbrew gradientowi stężeń"}, {"id": "b", "text": "Wymaga udziału nośnika energii"}, {"id": "c", "text": "Może być blokowany przez inhibitory ATP-azy"}, {"id": "d", "text": "Może być hamowany niekompetytywnie przez substancje o podobnej budowie chemicznej"}, {"id": "e", "text": "Wszystkie zdania są prawdziwe"}]'::jsonb,
   'd',
   $E$Transport czynny zachodzi **wbrew gradientowi stężeń**, kosztem energii z **ATP** i przy udziale swoistego nośnika — jest więc **wysycalny** i wybiórczy. Substancje o **podobnej budowie chemicznej** konkurują o to samo miejsce wiążące nośnika, hamując go **kompetycyjnie**, a nie niekompetycyjnie — dlatego zdanie D jest fałszywe. Hamowanie **niekompetycyjne** wywołują trucizny metaboliczne i **inhibitory ATP-azy**, jak ouabaina blokująca pompę sodowo-potasową.$E$,
   'Transport leków przez błony', 'FARSTO-e2026-1-1915', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(44, 'FARM-02',
   'Do leków przeciwhistaminowych I generacji nie zaliczymy:',
   '[{"id": "a", "text": "Hydroksyzyny"}, {"id": "b", "text": "Klemastyny"}, {"id": "c", "text": "Doksylaminy"}, {"id": "d", "text": "Cetyryzyny"}, {"id": "e", "text": "Prometazyny"}]'::jsonb,
   'd',
   $E$**Cetyryzyna** to lek **II generacji**, powstały jako aktywny metabolit **hydroksyzyny** — dzięki polarnej grupie karboksylowej praktycznie nie przenika bariery krew-mózg, więc nie działa nasennie ani **antymuskarynowo**. Pozostałe: **hydroksyzyna**, **klemastyna**, **doksylamina** i **prometazyna** to leki **I generacji**, silnie sedatywne; doksylaminę wykorzystuje się wręcz jako lek nasenny i przeciwwymiotny u ciężarnych, a prometazynę w chorobie lokomocyjnej.$E$,
   'Leki przeciwhistaminowe', 'FARSTO-e2026-1-1916', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(45, 'FARM-02',
   'Do antagonistów receptora 5-HT3 zaliczymy:',
   '[{"id": "a", "text": "Ondansetron"}, {"id": "b", "text": "Doksylaminę"}, {"id": "c", "text": "Flibanserynę"}, {"id": "d", "text": "Almotryptan"}, {"id": "e", "text": "Cyzapryd"}]'::jsonb,
   'a',
   $E$**Ondansetron** — jak wszystkie **setrony** (granisetron, palonosetron, tropisetron) — blokuje jonotropowy receptor **5-HT3** w jelicie i strefie chemoreceptorowej, znosząc wymioty po chemioterapii i pooperacyjne. Pozostałe leki obsługują inne receptory: **almotryptan** pobudza **5-HT1B/1D** (migrena), **cyzapryd** — **5-HT4** (prokinetyk wycofany z powodu **wydłużenia QT**), **flibanseryna** — **5-HT1A**, a **doksylamina** blokuje **H1**.$E$,
   'Receptory serotoninowe', 'FARSTO-e2026-1-1917', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(46, 'FARM-02',
   'Erenumab stosowany w terapii migreny działa poprzez:',
   '[{"id": "a", "text": "Pobudzanie 5-HT1B oraz 5-HT1D"}, {"id": "b", "text": "Blokowanie receptorów histaminowych typu 1"}, {"id": "c", "text": "Blokowanie receptorów beta-adrenergicznych"}, {"id": "d", "text": "Blokowanie receptorów CGRP"}, {"id": "e", "text": "Blokowanie cyklooksygenazy typu 2"}]'::jsonb,
   'd',
   $E$**Erenumab** to ludzkie przeciwciało monoklonalne skierowane przeciwko **receptorowi CGRP** — peptydu uwalnianego z zakończeń nerwu **trójdzielnego**, który rozszerza naczynia oponowe i podtrzymuje zapalenie neurogenne w napadzie migreny. Podaje się go **podskórnie raz w miesiącu** w profilaktyce. Pozostałe mechanizmy należą do innych leków: pobudzanie **5-HT1B/1D** — tryptany, blokada receptorów **beta** — propranolol, hamowanie **COX-2** — koksyby.$E$,
   'Migrena', 'FARSTO-e2026-1-1918', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(47, 'FARM-15',
   'Który z poniższych leków może być stosowany jako lek przeciwwymiotny poprzez hamowanie receptorów 5-HT3?',
   '[{"id": "a", "text": "Cyproheptadyna"}, {"id": "b", "text": "Granisetron"}, {"id": "c", "text": "Buspiron"}, {"id": "d", "text": "Karbamazepina"}, {"id": "e", "text": "Sumatryptan"}]'::jsonb,
   'b',
   $E$**Granisetron** należy do **setronów** — antagonistów receptora **5-HT3** — obok ondansetronu, palonosetronu i tropisetronu. Blokuje receptory na włóknach aferentnych **nerwu błędnego** w jelicie i w **strefie chemoreceptorowej**, znosząc wymioty po chemioterapii, radioterapii i zabiegach. Pozostałe leki działają na inne receptory serotoninowe: **cyproheptadyna** blokuje **5-HT2**, **buspiron** pobudza **5-HT1A**, a **sumatryptan** — **5-HT1B/1D**.$E$,
   'Leki przeciwwymiotne', 'FARSTO-e2026-1-1919', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(48, 'FARM-13',
   'Do działań niepożądanych pochodnych nitroimidazolu należą:',
   '[{"id": "a", "text": "Encefalopatia"}, {"id": "b", "text": "Wymioty i biegunka"}, {"id": "c", "text": "Zapalenie trzustki"}, {"id": "d", "text": "Metaliczny smak w ustach"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'e',
   $E$**Metronidazol** i **tynidazol** to proleki aktywowane przez redukcję grupy nitrowej w beztlenowcach i pierwotniakach; powstające rodniki uszkadzają jednak także komórki gospodarza. Najbardziej charakterystyczny jest **metaliczny smak w ustach**, obok nudności, wymiotów i biegunki. Rzadziej pojawiają się **zapalenie trzustki**, **encefalopatia** i neuropatia obwodowa przy długiej terapii. Kluczowa interakcja to **reakcja disulfiramowa** po alkoholu — wymagana abstynencja.$E$,
   'Pochodne nitroimidazolu', 'FARSTO-e2026-1-1920', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(49, 'FARM-13',
   'Sulfonamidem doustnym, który działa wolno jest:',
   '[{"id": "a", "text": "Rywastygmina"}, {"id": "b", "text": "Sulfametoksazol"}, {"id": "c", "text": "Sulfizoksazol"}, {"id": "d", "text": "Tropikamid"}, {"id": "e", "text": "Sulfanilamid"}]'::jsonb,
   'b',
   $E$**Sulfametoksazol** wchłania się i jest wydalany wolniej niż krótko działające **sulfizoksazol** i **sulfanilamid**, a jego okres półtrwania (**ok. 10 h**) niemal pokrywa się z półtrwaniem **trimetoprymu** — dlatego oba leki połączono w **kotrimoksazol** w proporcji **5:1**, uzyskując synergiczną, dwustopniową blokadę syntezy **folianów**. Pozostałe opcje to leki spoza grupy: **rywastygmina** hamuje cholinesterazę, a **tropikamid** jest lekiem antymuskarynowym.$E$,
   'Sulfonamidy', 'FARSTO-e2026-1-1921', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(50, 'FARM-04',
   'Do objawów zatrucia atropiną nie należy:',
   '[{"id": "a", "text": "Pobudzenie ośrodka termoregulacyjnego"}, {"id": "b", "text": "Pobudzenie psychomotoryczne"}, {"id": "c", "text": "Zwiększenie wydzielania gruczołowego"}, {"id": "d", "text": "Rozszerzenie naczyń skórnych"}, {"id": "e", "text": "Rozszerzenie źrenic"}]'::jsonb,
   'c',
   $E$Atropina blokuje receptory **muskarynowe**, więc wydzielanie gruczołowe **maleje** — pojawia się suchość skóry i błon śluzowych, a nie jej wzrost. Pozostałe objawy tworzą klasyczny zespół antycholinergiczny opisany mnemonikiem: **gorący jak zając** (hipertermia z braku potu), **suchy jak pieprz**, **czerwony jak burak** (rozszerzenie naczyń skórnych), **ślepy jak nietoperz** (mydriaza, porażenie akomodacji), **szalony jak kapelusznik** (pobudzenie, majaczenie). Odtrutką jest **fizostygmina**.$E$,
   'Leki antymuskarynowe', 'FARSTO-e2026-1-1922', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(51, 'FARM-09',
   'Długo działającą benzodiazepiną jest:',
   '[{"id": "a", "text": "Midazolam"}, {"id": "b", "text": "Diazepam"}, {"id": "c", "text": "Oksazepam"}, {"id": "d", "text": "Remimazolam"}, {"id": "e", "text": "Tiopental"}]'::jsonb,
   'b',
   $E$**Diazepam** ma okres półtrwania **20-50 h**, a jego aktywne metabolity — **nordazepam** (nawet **100 h**), oksazepam i temazepam — dodatkowo przedłużają efekt, dlatego kumuluje się u osób starszych i sprzyja upadkom. **Midazolam** działa krótko (**1,5-3 h**), **oksazepam** średnio długo i bez aktywnych metabolitów (bezpieczny w chorobach wątroby), **remimazolam** ultrakrótko dzięki rozkładowi przez esterazy, a **tiopental** jest barbituranem.$E$,
   'Benzodiazepiny', 'FARSTO-e2026-1-1923', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(52, 'FARM-08',
   'Do działań niepożądanych leków przeciwdepresyjnych nie należy:',
   '[{"id": "a", "text": "Neurotoksyczność"}, {"id": "b", "text": "Arytmie"}, {"id": "c", "text": "Spadek masy ciała"}, {"id": "d", "text": "Uczucie splątania"}, {"id": "e", "text": "Wielomocz"}]'::jsonb,
   'c',
   $E$Leki przeciwdepresyjne, zwłaszcza **TLPD** i **mirtazapina**, powodują raczej **przyrost** masy ciała — blokada receptorów **H1** i **5-HT2C** pobudza apetyt; chudnięcie dotyczy głównie **bupropionu** i wczesnej fazy leczenia SSRI. Pozostałe działania są typowe: **arytmie** i wydłużenie **QT** po TLPD oraz citalopramie, **splątanie** i **neurotoksyczność** (drżenia, drgawki, zespół serotoninowy), a także zaburzenia gospodarki wodnej z **hiponatremią**.$E$,
   'Działania niepożądane leków przeciwdepresyjnych', 'FARSTO-e2026-1-1924', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(53, 'FARM-17',
   'Grupa leków przeciwcukrzycowych, której należy unikać u osób starszych z niepełną zdolnością oceny przyjmowanej dawki (szczególnie u pacjentów z demencją, splątaniem) to:',
   '[{"id": "a", "text": "Pochodne biguanidu"}, {"id": "b", "text": "Inhibitory alfa-glukozydazy"}, {"id": "c", "text": "Glitazony"}, {"id": "d", "text": "Pochodne sulfonylomocznika"}, {"id": "e", "text": "Flozyny"}]'::jsonb,
   'd',
   $E$**Pochodne sulfonylomocznika** zamykają kanał **K-ATP** komórki beta i wyzwalają wyrzut insuliny **niezależnie od glikemii**, dlatego jako jedyne z wymienionych grup wywołują ciężkie, przedłużone **hipoglikemie** — szczególnie groźne u osób starszych, z otępieniem i upośledzoną czynnością nerek (klasycznie **glibenklamid**). **Metformina**, **flozyny**, glitazony i **akarboza** nie stymulują bezpośrednio wydzielania insuliny, więc same nie powodują hipoglikemii.$E$,
   'Doustne leki przeciwcukrzycowe', 'FARSTO-e2026-1-1925', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(54, 'FARM-17',
   'Wskaż zdanie fałszywe dotyczące flozyn (inhibitorów SGLT-2, kotransportera sodowo-glukozowego typu 2):',
   '[{"id": "a", "text": "Są inhibitorami kotransportera sodowo-glukozowego typu 2"}, {"id": "b", "text": "Ich zastosowanie wywołuje glikozurię i zmniejszenie obciążenia organizmu wchłoniętą po posiłku glukozą"}, {"id": "c", "text": "Wykazują działanie zmniejszające ryzyko wystąpienia zawału serca, udaru i śmierci z powodów sercowo-naczyniowych"}, {"id": "d", "text": "Działania niepożądane tej grupy leków ograniczają się głównie do zakażeń układu moczowego"}, {"id": "e", "text": "Nie wpływają na wartości hemoglobiny glikowanej"}]'::jsonb,
   'e',
   $E$Zdanie E jest fałszywe — **flozyny** obniżają **HbA1c** o około **0,5-1%**. Hamując kotransporter **SGLT-2** w cewce proksymalnej, wywołują **glikozurię** z utratą kilkuset kcal na dobę oraz łagodny efekt natriuretyczny. W badaniach EMPA-REG i DAPA-HF zmniejszyły śmiertelność sercowo-naczyniową, liczbę hospitalizacji z powodu **niewydolności serca** i progresję choroby nerek. Groźnym powikłaniem jest **euglikemiczna kwasica ketonowa**.$E$,
   'Flozyny', 'FARSTO-e2026-1-1926', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(55, 'FARM-12',
   'Lekiem mukokinetycznym jest:',
   '[{"id": "a", "text": "Bromheksyna"}, {"id": "b", "text": "Gwajafenezyna"}, {"id": "c", "text": "Butamirat"}, {"id": "d", "text": "Kodeina"}, {"id": "e", "text": "Dornaza alfa"}]'::jsonb,
   'a',
   $E$**Bromheksyna** działa **mukokinetycznie** — depolimeryzuje kwaśne mukopolisacharydy wydzieliny, pobudza komórki surowicze i przyspiesza ruch **rzęsek**, usprawniając transport śluzowo-rzęskowy; jej aktywnym metabolitem jest **ambroksol**. Pozostałe leki mają inne mechanizmy: **gwajafenezyna** działa wykrztuśnie odruchowo, **dornaza alfa** rozkłada **DNA** gęstej plwociny w mukowiscydozie, a **butamirat** i **kodeina** hamują odruch kaszlowy.$E$,
   'Leki wykrztuśne i mukolityczne', 'FARSTO-e2026-1-1927', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(56, 'FARM-15',
   'Do grupy antagonistów receptorów serotoninowych typu 3 należy:',
   '[{"id": "a", "text": "Tietylperazyna"}, {"id": "b", "text": "Ondansetron"}, {"id": "c", "text": "Somatostatyna"}, {"id": "d", "text": "Terlipresyna"}, {"id": "e", "text": "Soraprazan"}]'::jsonb,
   'b',
   $E$**Ondansetron** blokuje jonotropowy receptor **5-HT3** na zakończeniach nerwu błędnego i w strefie chemoreceptorowej — to lek pierwszego wyboru w wymiotach po **chemioterapii** i pooperacyjnych. Pozostałe pozycje należą do innych grup: **tietylperazyna** jest pochodną fenotiazyny blokującą **D2**, **somatostatyna** i **terlipresyna** zmniejszają przepływ trzewny w krwawieniu z żylaków przełyku, a **soraprazan** to odwracalny bloker pompy protonowej.$E$,
   'Leki przeciwwymiotne', 'FARSTO-e2026-1-1928', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(57, 'FARM-08',
   'Do działań niepożądanych wywoływanych przez antagonistów receptorów dopaminowych typu 2 nie należy:',
   '[{"id": "a", "text": "Nasilenie wydzielania prolaktyny"}, {"id": "b", "text": "Zaburzenia pozapiramidowe"}, {"id": "c", "text": "Senność"}, {"id": "d", "text": "Zaburzenia miesiączkowania"}, {"id": "e", "text": "Impotencja"}]'::jsonb,
   'c',
   $E$**Senność** nie wynika z blokady receptorów **D2**, lecz z równoczesnego hamowania receptorów **H1** i **alfa1**, dlatego przypisuje się ją lekom o szerokim profilu powinowactwa (fenotiazyny, klozapina), a nie samej antagonizacji dopaminy. Wprost z blokady **D2** wynikają natomiast **hiperprolaktynemia** — zniesienie tonicznego hamowania w szlaku **guzkowo-lejkowym**, z zaburzeniami miesiączkowania, mlekotokiem i **impotencją** — oraz objawy **pozapiramidowe** ze szlaku nigrostriatalnego.$E$,
   'Antagoniści receptorów dopaminowych', 'FARSTO-e2026-1-1929', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(58, 'FARM-06',
   'Lekiem z grupy tiazydów stosowanym w nadciśnieniu i niewydolności serca, którego działanie polega na rozszerzaniu naczyń oraz jest zwykle podawany raz dziennie jest:',
   '[{"id": "a", "text": "Hydrochlorotiazyd"}, {"id": "b", "text": "Metolazon"}, {"id": "c", "text": "Chlortalidon"}, {"id": "d", "text": "Indapamid"}, {"id": "e", "text": "Klopamid"}]'::jsonb,
   'd',
   $E$**Indapamid** to lek **tiazydopodobny** z dodatkową komponentą **rozszerzającą naczynia** (wpływ na napływ wapnia do miocytów gładkich i syntezę prostaglandyn), dzięki czemu obniża ciśnienie już w dawkach o słabym działaniu moczopędnym. Podawany **raz na dobę**, ma korzystniejszy profil metaboliczny niż hydrochlorotiazyd i powoduje regresję **przerostu lewej komory**. **Chlortalidon** i **klopamid** też są tiazydopodobne, ale bez efektu naczyniowego.$E$,
   'Diuretyki tiazydowe', 'FARSTO-e2026-1-1930', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(59, 'FARM-16',
   'Lekiem stosowanym w leczeniu łagodnego przerostu gruczołu krokowego jest:',
   '[{"id": "a", "text": "Wazopresyna"}, {"id": "b", "text": "Desmopresyna"}, {"id": "c", "text": "Koniwaptan"}, {"id": "d", "text": "Urodylatyna"}, {"id": "e", "text": "Finasteryd"}]'::jsonb,
   'e',
   $E$**Finasteryd** hamuje **5-alfa-reduktazę typu 2**, blokując przemianę **testosteronu w dihydrotestosteron** — androgen odpowiedzialny za rozrost gruczołu krokowego. Zmniejsza objętość prostaty po **3-6 miesiącach** i obniża stężenie **PSA o około 50%**, co trzeba uwzględnić w diagnostyce raka; działa też w łysieniu androgenowym. Pozostałe opcje dotyczą gospodarki wodnej: **desmopresyna** pobudza receptor **V2**, **koniwaptan** go blokuje, a **urodylatyna** jest peptydem natriuretycznym.$E$,
   'Łagodny rozrost gruczołu krokowego', 'FARSTO-e2026-1-1931', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(60, 'FARM-05',
   'Do leków hamujących czynność płytek krwi nie należy:',
   '[{"id": "a", "text": "Rywaroksaban"}, {"id": "b", "text": "Kwas acetylosalicylowy"}, {"id": "c", "text": "Klopidogrel"}, {"id": "d", "text": "Prasugrel"}, {"id": "e", "text": "Iloprost"}]'::jsonb,
   'a',
   $E$**Rywaroksaban** jest bezpośrednim inhibitorem **czynnika Xa** — należy do **DOAC (bezpośrednich doustnych antykoagulantów)** i hamuje osoczową kaskadę krzepnięcia, a nie czynność płytek. Pozostałe leki to antyagreganty: **kwas acetylosalicylowy** nieodwracalnie acetyluje **COX-1**, znosząc syntezę **tromboksanu A2**, **klopidogrel** i **prasugrel** blokują płytkowy receptor **P2Y12** dla ADP, a **iloprost** jako analog **prostacykliny** zwiększa stężenie cAMP w płytkach.$E$,
   'Leki przeciwpłytkowe', 'FARSTO-e2026-1-1932', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(61, 'FARM-15',
   'Najsilniejsze działanie przeciwwymiotne w leczeniu choroby lokomocyjnej wykazuje:',
   '[{"id": "a", "text": "prometazyna"}, {"id": "b", "text": "skopolamina"}, {"id": "c", "text": "ondansetron"}, {"id": "d", "text": "metoklopramid"}, {"id": "e", "text": "ranitydyna"}]'::jsonb,
   'b',
   $E$**Skopolamina**, alkaloid tropanowy blokujący receptory **muskarynowe**, najsilniej hamuje przekaźnictwo z jąder **przedsionkowych** do ośrodka wymiotnego, dlatego w profilaktyce choroby lokomocyjnej stosuje się ją w plastrze **przezskórnym** za uchem, działającym do **72 h**. **Prometazyna** i dimenhydrynat są skuteczne, lecz słabsze. **Ondansetron** i **metoklopramid** zawodzą, bo bodziec jest przedsionkowy, a nie serotoninowy czy dopaminowy; ranitydyna nie działa przeciwwymiotnie.$E$,
   'Leki przeciwwymiotne', 'FARSTO-e2026-1-1933', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(62, 'FARM-08',
   'Lek przeciwpsychotyczny częściowo agonistyczny w stosunku do receptorów D2 to:',
   '[{"id": "a", "text": "olanzapina"}, {"id": "b", "text": "arypiprazol"}, {"id": "c", "text": "kwetiapina"}, {"id": "d", "text": "risperidon"}, {"id": "e", "text": "perazyna"}]'::jsonb,
   'b',
   $E$**Arypiprazol** jest **częściowym agonistą D2** — przy nadmiarze dopaminy w szlaku mezolimbicznym zachowuje się jak antagonista, a przy jej niedoborze w szlaku mezokortykalnym i guzkowo-lejkowym jak słaby agonista, stąd nazwa **stabilizator dopaminowy**. Dodatkowo pobudza **5-HT1A** i blokuje **5-HT2A**. Rzadko wywołuje **hiperprolaktynemię** oraz przyrost masy ciała, ale często **akatyzję**. Pozostałe leki to klasyczni antagoniści receptora D2.$E$,
   'Neuroleptyki', 'FARSTO-e2026-1-1934', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(63, 'FARM-14',
   'Wskaż lek przeciwgrzybiczy o mechanizmie polegającym na hamowaniu syntezy beta-(1,3)-glukanu w ścianie komórkowej grzybów:',
   '[{"id": "a", "text": "amfoterycyna B"}, {"id": "b", "text": "flukonazol"}, {"id": "c", "text": "kaspofungina"}, {"id": "d", "text": "terbinafina"}, {"id": "e", "text": "gryzeofulwina"}]'::jsonb,
   'c',
   $E$**Kaspofungina**, jak pozostałe **echinokandyny** (anidulafungina, mikafungina), hamuje **syntazę beta-(1,3)-glukanu**, uniemożliwiając budowę **ściany komórkowej** grzyba — struktury, której człowiek nie posiada, stąd bardzo dobra tolerancja. Podawana wyłącznie **dożylnie**, jest lekiem z wyboru w inwazyjnej kandydozie. Inne mechanizmy: **amfoterycyna B** wiąże **ergosterol** i tworzy pory, **flukonazol** hamuje **14-alfa-demetylazę**, a **terbinafina** — epoksydazę skwalenową.$E$,
   'Leki przeciwgrzybicze', 'FARSTO-e2026-1-1935', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(64, 'FARM-13',
   'Zespół „czerwonego człowieka” jest charakterystycznym działaniem niepożądanym:',
   '[{"id": "a", "text": "gentamycyny"}, {"id": "b", "text": "wankomycyny"}, {"id": "c", "text": "linezolidu"}, {"id": "d", "text": "daptomycyny"}, {"id": "e", "text": "streptomycyny"}]'::jsonb,
   'b',
   $E$Zespół **czerwonego człowieka** to nieimmunologiczne, bezpośrednie uwolnienie **histaminy** z mastocytów przy zbyt szybkim wlewie **wankomycyny** — pojawia się rumień i świąd twarzy, szyi oraz górnej połowy tułowia, czasem z hipotonią. Nie jest to alergia **IgE-zależna**, więc wystarczy wydłużyć infuzję do co najmniej **60 minut** i podać lek przeciwhistaminowy. Inne typowe działania wankomycyny to **nefrotoksyczność** i **ototoksyczność**, nasilane przez aminoglikozydy.$E$,
   'Glikopeptydy', 'FARSTO-e2026-1-1936', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(65, 'FARM-08',
   'Wskaż lek przeciwdepresyjny będący inhibitorem wychwytu zwrotnego serotoniny i noradrenaliny (SNRI):',
   '[{"id": "a", "text": "sertralina"}, {"id": "b", "text": "duloksetyna"}, {"id": "c", "text": "moklobemid"}, {"id": "d", "text": "mirtazapina"}, {"id": "e", "text": "fluwoksamina"}]'::jsonb,
   'b',
   $E$**Duloksetyna** hamuje wychwyt zwrotny **serotoniny i noradrenaliny**, podobnie jak wenlafaksyna i milnacypran. Poza depresją i zaburzeniem lękowym uogólnionym stosuje się ją w **bólu neuropatycznym** w cukrzycy, fibromialgii i wysiłkowym nietrzymaniu moczu — efekt przeciwbólowy wynika ze wzmocnienia zstępujących szlaków hamujących. **Sertralina** i **fluwoksamina** to SSRI, **moklobemid** — odwracalny inhibitor **MAO-A**, a **mirtazapina** blokuje receptory **alfa2**.$E$,
   'Leki przeciwdepresyjne', 'FARSTO-e2026-1-1937', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(66, 'FARM-12',
   'Lek, który hamuje syntezę leukotrienów przez blokadę 5-lipooksygenazy:',
   '[{"id": "a", "text": "montelukast"}, {"id": "b", "text": "zafirlukast"}, {"id": "c", "text": "zileuton"}, {"id": "d", "text": "pitrakinra"}, {"id": "e", "text": "mepolizumab"}]'::jsonb,
   'c',
   $E$**Zileuton** blokuje **5-lipooksygenazę**, enzym przekształcający **kwas arachidonowy** w leukotrieny, więc hamuje powstawanie zarówno **LTB4**, jak i cysteinylowych **LTC4, LTD4 i LTE4**. Wymaga dawkowania cztery razy na dobę i kontroli **aminotransferaz** ze względu na hepatotoksyczność, dlatego jest rzadko stosowany. **Montelukast** i **zafirlukast** działają niżej w szlaku, blokując receptor **CysLT1**, a **mepolizumab** jest przeciwciałem przeciw **IL-5**.$E$,
   'Leki przeciwleukotrienowe', 'FARSTO-e2026-1-1938', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(67, 'FARM-15',
   'Wskaż lek działający poprzez nieodwracalne hamowanie pompy protonowej w komórkach okładzinowych żołądka:',
   '[{"id": "a", "text": "ranitydyna"}, {"id": "b", "text": "famotydyna"}, {"id": "c", "text": "mizoprostol"}, {"id": "d", "text": "omeprazol"}, {"id": "e", "text": "sukralfat"}]'::jsonb,
   'd',
   $E$**Omeprazol** jest prolekiem gromadzącym się w kanalikach wydzielniczych komórki okładzinowej, gdzie w **kwaśnym pH** przekształca się w sulfenamid i **nieodwracalnie** wiąże z **H+/K+-ATP-azą**, czyli pompą protonową. Efekt utrzymuje się aż do syntezy nowych pomp, przez **24-48 h**, a lek przyjmuje się **30-60 min przed posiłkiem**. Inaczej działają: **ranitydyna** i **famotydyna** blokują receptory **H2**, **mizoprostol** jest analogiem **PGE1**, a **sukralfat** tworzy warstwę ochronną.$E$,
   'Leki hamujące wydzielanie żołądkowe', 'FARSTO-e2026-1-1939', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(68, 'FARM-17',
   'Który z wymienionych leków jest inhibitorem SGLT-2 (kotransportera sodowo-glukozowego typu 2) i stosowany w cukrzycy typu 2?',
   '[{"id": "a", "text": "sitagliptyna"}, {"id": "b", "text": "eksenatyd"}, {"id": "c", "text": "kanagliflozyna"}, {"id": "d", "text": "akarboza"}, {"id": "e", "text": "repaglinid"}]'::jsonb,
   'c',
   $E$**Kanagliflozyna**, podobnie jak dapagliflozyna i empagliflozyna, hamuje **SGLT-2** w cewce proksymalnej — kotransporter odpowiadający za około **90% zwrotnego wchłaniania glukozy**. Efektem są **glikozuria**, spadek masy ciała i ciśnienia tętniczego oraz ochrona serca i nerek. Inne mechanizmy: **sitagliptyna** hamuje **DPP-4 (dipeptydylopeptydazę 4)**, **eksenatyd** pobudza receptor **GLP-1 (peptydu glukagonopodobnego 1)**, **akarboza** blokuje alfa-glukozydazę, a **repaglinid** zamyka kanał **K-ATP**.$E$,
   'Doustne leki przeciwcukrzycowe', 'FARSTO-e2026-1-1940', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(69, 'FARM-14',
   'Wskaż lek przeciwwirusowy stosowany w leczeniu COVID-19 w postaci doustnej:',
   '[{"id": "a", "text": "oseltamiwir"}, {"id": "b", "text": "remdesiwir"}, {"id": "c", "text": "nirmatrelwir/rytonawir"}, {"id": "d", "text": "acyklowir"}, {"id": "e", "text": "gancyklowir"}]'::jsonb,
   'c',
   $E$**Nirmatrelwir** hamuje główną proteazę **3CL (Mpro)** wirusa SARS-CoV-2, blokując cięcie poliprotein niezbędne do replikacji, natomiast **rytonawir** dodano wyłącznie jako **booster farmakokinetyczny** — silny inhibitor **CYP3A4** podtrzymujący stężenie leku, ale i źródło licznych interakcji (statyny, amiodaron, takrolimus). Terapię doustną trzeba zacząć w ciągu **5 dni** od objawów. **Remdesiwir** podaje się dożylnie, a **oseltamiwir** hamuje neuraminidazę wirusa grypy.$E$,
   'Leczenie COVID-19', 'FARSTO-e2026-1-1941', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(70, 'FARM-15',
   'Lek stosowany w terapii krwawień z przewodu pokarmowego, działający poprzez aktywację receptorów wazopresynowych w mięśniach gładkich naczyń trzewnych:',
   '[{"id": "a", "text": "wazopresyna"}, {"id": "b", "text": "desmopresyna"}, {"id": "c", "text": "terlipresyna"}, {"id": "d", "text": "oksytocyna"}, {"id": "e", "text": "bromokryptyna"}]'::jsonb,
   'c',
   $E$**Terlipresyna** to prolek stopniowo uwalniający **lizyno-wazopresynę**, która pobudza receptory **V1** w mięśniówce naczyń **trzewnych**; ich skurcz zmniejsza napływ krwi do krążenia wrotnego i obniża ciśnienie w **żylakach przełyku**, hamując krwawienie. Stosuje się ją także w **zespole wątrobowo-nerkowym**. Długi czas działania pozwala podawać ją w bolusach co 4-6 h, w odróżnieniu od wazopresyny wymagającej wlewu. **Desmopresyna** pobudza wybiórczo receptory **V2**.$E$,
   'Krwawienie z żylaków przełyku', 'FARSTO-e2026-1-1942', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(71, 'FARM-04',
   'Z białkiem Gs są związane receptory:',
   '[{"id": "a", "text": "alfa2"}, {"id": "b", "text": "beta1"}, {"id": "c", "text": "M2"}, {"id": "d", "text": "5-HT3"}, {"id": "e", "text": "B1"}]'::jsonb,
   'b',
   $E$Receptory **beta-adrenergiczne** (beta1, beta2, beta3) sprzęgają się z białkiem **Gs**, które pobudza **cyklazę adenylanową** i zwiększa stężenie **cAMP** — w sercu daje to efekt inotropowy i chronotropowy dodatni. Z białkiem **Gi**, hamującym cyklazę, związane są **alfa2** i **M2**, z **Gq** (fosfolipaza C, IP3, wzrost Ca2+) — alfa1, M1/M3 i bradykininowy **B1**, a **5-HT3** jest receptorem **jonotropowym**, czyli kanałem jonowym niezwiązanym z białkiem G.$E$,
   'Receptory i białka G', 'FARSTO-e2026-1-1943', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(72, 'FARM-04',
   'Za wydzielanie reniny przez aparat przykłębuszkowy w nerce odpowiada receptor:',
   '[{"id": "a", "text": "alfa1"}, {"id": "b", "text": "M3"}, {"id": "c", "text": "beta1"}, {"id": "d", "text": "beta2"}, {"id": "e", "text": "beta3"}]'::jsonb,
   'c',
   $E$Wydzielanie **reniny** przez komórki ziarniste aparatu przykłębuszkowego pobudzają włókna współczulne działające przez receptory **beta1** — obok spadku ciśnienia w tętniczce doprowadzającej i mniejszej podaży **NaCl** w plamce gęstej. Tłumaczy to jeden z mechanizmów hipotensyjnego działania **beta-blokerów**, które hamują aktywność układu **RAA**. Receptory **beta2** rozszerzają oskrzela i naczynia mięśni szkieletowych, a **beta3** znajdują się w tkance tłuszczowej i pęcherzu moczowym.$E$,
   'Receptory adrenergiczne', 'FARSTO-e2026-1-1944', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(73, 'FARM-04',
   'Jednym ze wskazań do stosowania leków cholinomimetycznych jest:',
   '[{"id": "a", "text": "Niedrożność dróg moczowych i żółciowych"}, {"id": "b", "text": "Astma oskrzelowa"}, {"id": "c", "text": "Zawał mięśnia sercowego"}, {"id": "d", "text": "Atonia przewodu pokarmowego"}, {"id": "e", "text": "Nadczynność tarczycy"}]'::jsonb,
   'd',
   $E$**Cholinomimetyki** (betanechol, neostygmina) pobudzają receptory **M3** mięśniówki gładkiej jelit i pęcherza, dlatego stosuje się je w pooperacyjnej **atonii przewodu pokarmowego** i zatrzymaniu moczu z atonii wypieracza. Pozostałe stany to **przeciwwskazania**: niedrożność mechaniczna grozi perforacją, w **astmie** dochodzi do skurczu oskrzeli i wzrostu wydzieliny, a w świeżym zawale i **nadczynności tarczycy** ryzykowna jest bradykardia i pobudzenie arytmii.$E$,
   'Leki cholinomimetyczne', 'FARSTO-e2026-1-1945', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(74, 'FARM-04',
   'Lekiem sympatykomimetycznym pobudzającym receptory alfa1, stosowanym pozajelitowo w celu utrzymania prawidłowych wartości ciśnienia tętniczego podczas znieczulenia przewodowego czy ogólnego oraz jako środek wspomagający w leczeniu wstrząsu i niedociśnienia tętniczego, jest:',
   '[{"id": "a", "text": "Nafazolina"}, {"id": "b", "text": "Tetryzolina"}, {"id": "c", "text": "Midodryna"}, {"id": "d", "text": "Etylefryna"}, {"id": "e", "text": "Fenylefryna"}]'::jsonb,
   'e',
   $E$**Fenylefryna** jest wybiórczym agonistą receptorów **alfa1** — obkurcza naczynia oporowe i podnosi ciśnienie bez bezpośredniego pobudzania serca, dlatego podaje się ją **dożylnie** w hipotonii po znieczuleniu podpajęczynówkowym lub ogólnym; typowa jest przy tym odruchowa **bradykardia** z baroreceptorów. **Nafazolina** i **tetryzolina** służą wyłącznie do stosowania miejscowego w nosie i oku, **midodryna** działa doustnie w hipotonii ortostatycznej, a **etylefryna** pobudza też receptory beta.$E$,
   'Leki sympatykomimetyczne', 'FARSTO-e2026-1-1946', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(75, 'FARM-06',
   'Działaniem niepożądanym inhibitorów ACE nie jest:',
   '[{"id": "a", "text": "Duży wzrost ciśnienia tętniczego krwi po pierwszej dawce"}, {"id": "b", "text": "Suchy kaszel"}, {"id": "c", "text": "Zaburzenia smaku"}, {"id": "d", "text": "Hiperkaliemia"}, {"id": "e", "text": "Pokrzywka alergiczna"}]'::jsonb,
   'a',
   $E$Po pierwszej dawce inhibitora ACE ciśnienie gwałtownie **spada**, a nie rośnie — hipotonia pierwszej dawki jest szczególnie groźna u chorych odwodnionych i leczonych diuretykami. Pozostałe działania są typowe: **suchy kaszel** i **obrzęk naczynioruchowy** wynikają z nagromadzenia **bradykininy**, **hiperkaliemia** ze spadku stężenia **aldosteronu**, a **zaburzenia smaku**, wysypki i pokrzywka wiążą się z grupą **sulfhydrylową** kaptoprylu.$E$,
   'Inhibitory konwertazy angiotensyny', 'FARSTO-e2026-1-1947', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(76, 'FARM-02',
   'Niedobór tlenku azotu stwierdza się w:',
   '[{"id": "a", "text": "Wstrząsie endotoksycznym"}, {"id": "b", "text": "Rzucawce okołoporodowej"}, {"id": "c", "text": "Reumatoidalnym zapaleniu stawów"}, {"id": "d", "text": "Padaczce"}, {"id": "e", "text": "Pourazowym uszkodzeniu OUN"}]'::jsonb,
   'b',
   $E$W stanie przedrzucawkowym i **rzucawce** dochodzi do dysfunkcji śródbłonka z **niedoborem tlenku azotu** i prostacykliny, czego skutkiem są uogólniony **skurcz naczyń**, nadciśnienie, białkomocz i niedokrwienie łożyska. W pozostałych stanach obserwuje się **nadmiar NO** wytwarzanego przez indukowalną syntazę **iNOS**: we **wstrząsie endotoksycznym** odpowiada on za oporną na aminy katecholowe wazodylatację, a w RZS, padaczce i urazie OUN — za odczyn zapalny i **ekscytotoksyczność**.$E$,
   'Tlenek azotu', 'FARSTO-e2026-1-1948', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(77, 'FARM-13',
   'Przedstawicielem oksazolidynonów jest:',
   '[{"id": "a", "text": "bacytracyna"}, {"id": "b", "text": "linkomycyna"}, {"id": "c", "text": "linezolid"}, {"id": "d", "text": "lamiwudyna"}, {"id": "e", "text": "lewofloksacyna"}]'::jsonb,
   'c',
   $E$**Linezolid** to główny przedstawiciel **oksazolidynonów** — wiąże się z podjednostką **50S** rybosomu i blokuje tworzenie kompleksu inicjującego **70S**, czyli najwcześniejszy etap syntezy białka, co czyni oporność krzyżową mało prawdopodobną. Działa na oporne ziarenkowce Gram-dodatnie: **MRSA**, **VRE** i pneumokoki, a jego biodostępność doustna sięga **100%**. Ograniczenia: **mielosupresja** po ponad 2 tygodniach terapii, neuropatia i ryzyko **zespołu serotoninowego** z SSRI.$E$,
   'Oksazolidynony', 'FARSTO-e2026-1-1949', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(78, 'FARM-03',
   'Do II stopnia drabiny analgetycznej nie należy:',
   '[{"id": "a", "text": "Tramadol"}, {"id": "b", "text": "Kodeina"}, {"id": "c", "text": "Dihydrokodeina"}, {"id": "d", "text": "Morfina"}, {"id": "e", "text": "Analgetyki nieopioidowe"}]'::jsonb,
   'd',
   $E$**Morfina** to **silny opioid**, czyli **III stopień** drabiny analgetycznej WHO, razem z oksykodonem, fentanylem, buprenorfiną i metadonem. **II stopień** tworzą opioidy słabe — **tramadol**, **kodeina** i **dihydrokodeina** — zawsze kojarzone z analgetykami nieopioidowymi ze stopnia I (**paracetamol**, **NLPZ**). Na każdym szczeblu można dołączyć **koanalgetyki**: leki przeciwdepresyjne, przeciwpadaczkowe, glikokortykosteroidy czy bisfosfoniany w bólu kostnym.$E$,
   'Drabina analgetyczna', 'FARSTO-e2026-1-1950', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(79, 'FARM-13',
   'Do farmakoterapii atypowego zapalenia płuc wywołanego przez Legionella sp., Mycoplasma sp. lub Chlamydia sp. powinno się włączyć:',
   '[{"id": "a", "text": "Cefotaksym"}, {"id": "b", "text": "Metronidazol"}, {"id": "c", "text": "Wankomycynę"}, {"id": "d", "text": "Ryfampicynę"}, {"id": "e", "text": "Azytromycynę"}]'::jsonb,
   'e',
   $E$Patogeny atypowe są **wewnątrzkomórkowe** (Legionella, Chlamydia) lub pozbawione **ściany komórkowej** (Mycoplasma), dlatego beta-laktamy jak **cefotaksym** oraz glikopeptydy są wobec nich bezsilne — brakuje im punktu uchwytu lub dostępu do wnętrza komórki. Skuteczne są leki dobrze penetrujące do cytoplazmy: **makrolidy**, **tetracykliny** i fluorochinolony oddechowe. **Azytromycyna** kumuluje się w makrofagach i ma długi okres półtrwania, co pozwala skrócić terapię do 3-5 dni.$E$,
   'Zapalenie płuc', 'FARSTO-e2026-1-1951', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(80, 'FARM-13',
   'Dobrą penetracją do OUN charakteryzuje się:',
   '[{"id": "a", "text": "Metronidazol"}, {"id": "b", "text": "Aminoglikozydy"}, {"id": "c", "text": "Cefalosporyny I generacji"}, {"id": "d", "text": "Neomycyna"}, {"id": "e", "text": "Kwas klawulanowy"}]'::jsonb,
   'a',
   $E$**Metronidazol** jest małą, silnie **lipofilną** cząsteczką słabo wiążącą się z białkami, dlatego swobodnie przenika **barierę krew-mózg** i osiąga w płynie mózgowo-rdzeniowym stężenia zbliżone do surowiczych — to lek z wyboru w **ropniach mózgu** o etiologii beztlenowej. **Aminoglikozydy**, w tym **neomycyna**, są polarnymi kationami i praktycznie nie wnikają do OUN, podobnie **cefalosporyny I generacji**; skuteczne w zapaleniu opon są dopiero cefalosporyny III generacji.$E$,
   'Penetracja antybiotyków do tkanek', 'FARSTO-e2026-1-1952', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(81, 'FARM-08',
   'Wskaż lek stosowany u dzieci z ADHD:',
   '[{"id": "a", "text": "Metadon"}, {"id": "b", "text": "Metylfenidat"}, {"id": "c", "text": "Metotreksat"}, {"id": "d", "text": "Kwetiapina"}, {"id": "e", "text": "Lofeksydyna"}]'::jsonb,
   'b',
   $E$**Metylfenidat** blokuje transportery **dopaminy (DAT)** i **noradrenaliny (NET)**, zwiększając stężenie tych amin w korze przedczołowej i poprawiając kontrolę uwagi oraz hamowanie impulsów w **ADHD**. Typowe działania niepożądane to brak łaknienia, zahamowanie wzrastania, bezsenność i wzrost ciśnienia; lek ma potencjał uzależniający. Alternatywą jest **atomoksetyna**, wybiórczy inhibitor NET. **Lofeksydyna**, agonista **alfa2**, łagodzi objawy odstawienia opioidów.$E$,
   'Leczenie ADHD', 'FARSTO-e2026-1-1953', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(82, 'FARM-15',
   'Natalizumab to przeciwciało stosowane w leczeniu: I. Choroby Leśniowskiego-Crohna II. Stwardnienia rozsianego III. Rdzeniowego zaniku mięśni IV. Choroby Kennedy''ego V. Choroby Huntingtona VI. Ataksji Friedreicha',
   '[{"id": "a", "text": "I, III"}, {"id": "b", "text": "I, II"}, {"id": "c", "text": "I, IV"}, {"id": "d", "text": "II, V"}, {"id": "e", "text": "VI"}]'::jsonb,
   'b',
   $E$**Natalizumab** to przeciwciało monoklonalne przeciw **integrynie alfa4** limfocytów — blokuje ich adhezję do śródbłonka i przechodzenie do tkanek, w tym przez **barierę krew-mózg**. Stąd dwa wskazania: postać **rzutowo-remisyjna stwardnienia rozsianego** oraz oporna **choroba Leśniowskiego-Crohna**. Głównym zagrożeniem jest **postępująca wieloogniskowa leukoencefalopatia (PML)** wywołana wirusem **JC**, dlatego przed leczeniem oznacza się przeciwciała anty-JCV.$E$,
   'Leki biologiczne w chorobach zapalnych jelit', 'FARSTO-e2026-1-1954', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(83, 'FARM-10',
   'Wskaż wyłącznie agonistów receptorów dopaminowych:',
   '[{"id": "a", "text": "Haloperydol, Olanzapina, Rezerpina, Pirybedyl"}, {"id": "b", "text": "Bromokryptyna, Pergolid, Ropinirol, Apomorfina"}, {"id": "c", "text": "Karbidopa, Selegilina, Tiapryd, Lewodopa"}, {"id": "d", "text": "Rotygotyna, Pramipeksol, Nusinersen, Olanzapina"}, {"id": "e", "text": "Onasemnogen, Abeparwowek, Baklofen, Kwetiapina, Diazepam"}]'::jsonb,
   'b',
   $E$Tylko zestaw B zawiera wyłącznie **agonistów receptorów dopaminowych**: **bromokryptynę** i **pergolid** (pochodne sporyszu, grożące włóknieniem zastawek i opłucnej), **ropinirol** oraz **apomorfinę** podawaną podskórnie w nagłych stanach **off**. Pozostałe zestawy psuje obecność leków o innym działaniu: **haloperydol**, **olanzapina** i **tiapryd** blokują **D2**, **rezerpina** opróżnia pęcherzyki z amin, **karbidopa** hamuje obwodową **dekarboksylazę**, a **selegilina** — **MAO-B**.$E$,
   'Choroba Parkinsona', 'FARSTO-e2026-1-1955', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(84, 'FARM-06',
   'Wskaż zdanie prawdziwe:',
   '[{"id": "a", "text": "Mirabegron i wibegron służą do leczenia łagodnego przerostu prostaty"}, {"id": "b", "text": "Tamsulosyna i Alfuzosyna służą do leczenia nadreaktywnego pęcherza"}, {"id": "c", "text": "Prazosyna może być stosowana w leczeniu nadciśnienia tętniczego oraz chorobie Raynauda"}, {"id": "d", "text": "Betaksolol jest kardioselektywnym beta-blokerem o działaniu wazodylatacyjnym"}, {"id": "e", "text": "Fenoldopam służy do podwyższania ciśnienia tętniczego"}]'::jsonb,
   'c',
   $E$**Prazosyna** blokuje receptory **alfa1**, rozszerzając tętniczki i żyły — stąd zastosowanie w nadciśnieniu i objawie **Raynauda**, a także w koszmarach sennych w PTSD; typowa jest **hipotonia pierwszej dawki**. Pozostałe zdania mylą wskazania: **mirabegron** i wibegron to agoniści **beta3** w pęcherzu nadreaktywnym, **tamsulosyna** i alfuzosyna leczą **rozrost prostaty**, **betaksolol** nie rozszerza naczyń (w odróżnieniu od nebiwololu), a **fenoldopam**, agonista **D1**, ciśnienie obniża.$E$,
   'Leki alfa-adrenolityczne', 'FARSTO-e2026-1-1956', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(85, 'FARM-04',
   'Wraz ze wzrostem dawki dopamina wykazuje następujący ciąg efektów:',
   '[{"id": "a", "text": "Wzrost diurezy - stymulacja receptorów beta1 - aktywacja receptorów alfa1"}, {"id": "b", "text": "Skurcz naczyń krwionośnych - stymulacja receptorów alfa1 - wzrost diurezy"}, {"id": "c", "text": "Wzrost ciśnienia - tachykardia - wzrost diurezy"}, {"id": "d", "text": "Rozkurcz naczyń krwionośnych - bradykardia - omamy"}, {"id": "e", "text": "Dopamina jest neurotransmiterem wyłącznie w OUN, więc nie wywołuje efektów poza nim"}]'::jsonb,
   'a',
   $E$Dopamina działa **zależnie od dawki**: w małej (**1-3 mcg/kg/min**) pobudza receptory **D1** naczyń nerkowych i trzewnych, zwiększając przepływ nerkowy i **diurezę**; w średniej (**3-10**) dołącza pobudzenie **beta1** z efektem inotropowym i chronotropowym dodatnim; w dużej (**powyżej 10**) dominuje aktywacja **alfa1** ze skurczem naczyń i wzrostem oporu obwodowego. Jako amina katecholowa nie przenika bariery krew-mózg, więc podana dożylnie działa wyłącznie obwodowo.$E$,
   'Aminy katecholowe', 'FARSTO-e2026-1-1957', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(86, 'FARM-03',
   'Zaznacz zdanie fałszywe:',
   '[{"id": "a", "text": "Nalokson to antagonista receptora opioidowego"}, {"id": "b", "text": "Nalokson ma krótki czas działania, dlatego aby zapobiec niewydolności oddechowej należy kilkukrotnie powtórzyć dawkę"}, {"id": "c", "text": "Naltrekson jest agonistą receptora opioidowego i można go podawać doustnie"}, {"id": "d", "text": "Naltrekson ma długi czas działania i można go podawać raz w miesiącu w zastrzykach"}, {"id": "e", "text": "Alwimopan jest antagonistą receptora opioidowego i działa wyłącznie obwodowo"}]'::jsonb,
   'c',
   $E$Fałszywe jest zdanie C: **naltrekson** to **antagonista**, a nie agonista receptorów opioidowych — podawany doustnie lub w postaci iniekcji o przedłużonym uwalnianiu **raz w miesiącu** wspomaga leczenie uzależnienia od opioidów i alkoholu. Pozostałe zdania są prawdziwe: **nalokson** działa krótko (**30-60 min**), więc po ustąpieniu efektu depresja oddechowa może wrócić i dawkę trzeba powtarzać, a **alwimopan** nie przenika do OUN, znosząc jedynie obwodowe skutki opioidów.$E$,
   'Antagoniści receptorów opioidowych', 'FARSTO-e2026-1-1958', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(87, 'FARM-03',
   'Wskaż przeciwwskazania do stosowania kwasu acetylosalicylowego: I. Krwawienie miesiączkowe II. Ciąża III. Laktacja IV. Wtórna prewencja zawału V. Pierwotna prewencja zawału VI. Gorączka u dzieci do 12 roku życia VII. Astma oskrzelowa VIII. Zawał mięśnia sercowego',
   '[{"id": "a", "text": "I, II, III, VI, VII"}, {"id": "b", "text": "II, III, VI, VII"}, {"id": "c", "text": "IV, V, VII"}, {"id": "d", "text": "II, III, VII, VIII"}, {"id": "e", "text": "IV, V, VI, VII"}]'::jsonb,
   'a',
   $E$Kwas acetylosalicylowy nieodwracalnie hamuje **COX-1** płytek, więc nasila każde krwawienie, w tym **miesiączkowe**. W **ciąży** grozi przedwczesnym zamknięciem **przewodu tętniczego** i krwawieniem okołoporodowym, przenika też do mleka. U dzieci poniżej 12 lat może wywołać **zespół Reye'a** — encefalopatię ze stłuszczeniem wątroby — a u chorych na **astmę** napad duszności wskutek przesunięcia metabolizmu kwasu arachidonowego w stronę **leukotrienów**. Prewencja zawału jest wskazaniem, nie przeciwwskazaniem.$E$,
   'Kwas acetylosalicylowy', 'FARSTO-e2026-1-1959', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(88, 'FARM-08',
   'Który z leków nie uzależnia psychicznie:',
   '[{"id": "a", "text": "Escitalopram"}, {"id": "b", "text": "Morfina"}, {"id": "c", "text": "Diazepam"}, {"id": "d", "text": "Midazolam"}, {"id": "e", "text": "Nikotyna"}]'::jsonb,
   'a',
   $E$**Escitalopram** (SSRI) nie uzależnia psychicznie — nie pobudza bezpośrednio układu nagrody, nie wywołuje euforii ani głodu leku. Po nagłym odstawieniu bywa **zespół odstawienny** (zawroty głowy, parestezje, drażliwość), dlatego dawkę zmniejsza się stopniowo, ale to nie jest uzależnienie. Pozostałe substancje uzależniają silnie: **morfina** przez receptory **mi**, **diazepam** i **midazolam** przez receptor **GABA-A**, a **nikotyna** przez receptory nikotynowe — wszystkie zwiększają uwalnianie **dopaminy** w jądrze półleżącym.$E$,
   'Potencjał uzależniający leków', 'FARSTO-e2026-1-1960', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(89, 'FARM-09',
   'Które leki można stosować w zaburzeniach snu:',
   '[{"id": "a", "text": "Lorazepam, Flumazenil, Difenhydramina"}, {"id": "b", "text": "Suworeksant, Zolpidem, Propranolol"}, {"id": "c", "text": "Zolpidem, Zaleplon, Buspiron"}, {"id": "d", "text": "Zolpidem, Difenhydramina, Melatonina"}, {"id": "e", "text": "Sertralina, Fentanyl, Morfina"}]'::jsonb,
   'd',
   $E$Zestaw D zawiera trzy leki realnie stosowane w bezsenności: **zolpidem** — lek „Z”, agonista miejsca benzodiazepinowego wybiórczy wobec podjednostki **alfa1** receptora **GABA-A**, **difenhydraminę** — lek przeciwhistaminowy **I generacji** dostępny bez recepty, oraz **melatoninę** działającą przez receptory **MT1/MT2** i regulującą rytm dobowy. Pozostałe zestawy dyskwalifikują **flumazenil** (antagonista benzodiazepin), **propranolol**, **buspiron** oraz opioidy.$E$,
   'Leki nasenne', 'FARSTO-e2026-1-1961', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(90, 'FARM-10',
   'Wskaż leki stosowane w chorobie Huntingtona:',
   '[{"id": "a", "text": "Tetrabenazyna, Haloperydol"}, {"id": "b", "text": "Lewodopa, Sertralina"}, {"id": "c", "text": "Apomorfina, Pergolid"}, {"id": "d", "text": "Escitalopram, Diazepam"}, {"id": "e", "text": "Olanzapina, Selegilina"}]'::jsonb,
   'a',
   $E$Pląsawicę w chorobie **Huntingtona** wywołuje względny **nadmiar dopaminy** w prążkowiu po utracie neuronów **GABA-ergicznych**, dlatego leczenie objawowe polega na osłabieniu przekaźnictwa dopaminergicznego: **tetrabenazyna** hamuje transporter pęcherzykowy **VMAT2**, opróżniając zakończenia z amin, a **haloperydol** blokuje receptory **D2**. Ryzykiem tetrabenazyny jest depresja z myślami samobójczymi. Leki dopaminergiczne, jak **lewodopa**, apomorfina czy pergolid, nasilałyby ruchy mimowolne.$E$,
   'Choroba Huntingtona', 'FARSTO-e2026-1-1962', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(91, 'FARM-02',
   'Do antagonistów receptora histaminowego H1 drugiej generacji nie należy:',
   '[{"id": "a", "text": "Astemizol"}, {"id": "b", "text": "Ebastyna"}, {"id": "c", "text": "Antazolina"}, {"id": "d", "text": "Mizolastyna"}, {"id": "e", "text": "Loratadyna"}]'::jsonb,
   'c',
   $E$**Antazolina** to lek **I generacji**, stosowany głównie miejscowo do oka i nosa (często w połączeniu z ksylometazoliną) oraz dożylnie w ostrych reakcjach alergicznych; przenika do OUN i działa sedatywnie. **Astemizol**, **ebastyna**, **mizolastyna** i **loratadyna** należą do **II generacji** i nie wywołują senności. Astemizol oraz terfenadynę wycofano, bo blokując kanały **hERG**, wydłużały **QT** i groziły **torsade de pointes**, zwłaszcza z inhibitorami CYP3A4.$E$,
   'Leki przeciwhistaminowe', 'FARSTO-e2026-1-1963', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(92, 'FARM-03',
   'Do leków urykozurycznych należy:',
   '[{"id": "a", "text": "Febuksostat"}, {"id": "b", "text": "Sulfasalazyna"}, {"id": "c", "text": "Peglotykaza"}, {"id": "d", "text": "Benzbromaron"}, {"id": "e", "text": "Prawidłowa jest odpowiedź B i D"}]'::jsonb,
   'd',
   $E$**Benzbromaron** hamuje transporter **URAT1** w cewce proksymalnej, blokując zwrotne wchłanianie **kwasu moczowego** i zwiększając jego wydalanie z moczem — to typowy **urykozuryk**, obok probenecydu, sulfinpirazonu i lesynuradu. Wymaga dobrego nawodnienia i alkalizacji moczu (ryzyko **kamicy moczanowej**), a jego stosowanie ograniczyła hepatotoksyczność. **Febuksostat** hamuje **oksydazę ksantynową**, a **peglotykaza** rozkłada kwas moczowy — działają na powstawanie, nie na wydalanie.$E$,
   'Dna moczanowa', 'FARSTO-e2026-1-1964', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(93, 'FARM-07',
   'Miopatie mogą być działaniem niepożądanym:',
   '[{"id": "a", "text": "Statyn"}, {"id": "b", "text": "Fibratów"}, {"id": "c", "text": "Ezetymibu"}, {"id": "d", "text": "Inhibitorów PCSK-9 (konwertazy proproteinowej subtylizyny/keksyny typu 9)"}, {"id": "e", "text": "A i B"}]'::jsonb,
   'e',
   $E$Zarówno **statyny**, jak i **fibraty** uszkadzają mięśnie — od bólów mięśniowych, przez zapalenie z podwyższoną **kinazą kreatynową**, po **rabdomiolizę** z mioglobinurią i ostrym uszkodzeniem nerek. Ryzyko rośnie wielokrotnie przy łączeniu obu grup, zwłaszcza z **gemfibrozylem**, który hamuje glukuronidację statyn, a także przy zablokowaniu **CYP3A4** (sok grejpfrutowy, makrolidy, azole). **Ezetymib** i **inhibitory PCSK9** są pod tym względem bezpieczne.$E$,
   'Leki hipolipemizujące', 'FARSTO-e2026-1-1965', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(94, 'FARM-07',
   'Do efektów działania statyn należy:',
   '[{"id": "a", "text": "Obniżenie frakcji LDL cholesterolu"}, {"id": "b", "text": "Zapobieganie dysfunkcji śródbłonka"}, {"id": "c", "text": "Osłabienie agregacji płytek krwi"}, {"id": "d", "text": "Stabilizacja blaszki miażdżycowej"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'e',
   $E$**Statyny** hamują **reduktazę HMG-CoA**, zmniejszając syntezę cholesterolu w hepatocycie i zwiększając ekspresję receptorów dla **LDL**, co obniża tę frakcję nawet o **50%**. Poza tym wykazują efekty **plejotropowe**: poprawiają czynność śródbłonka przez wzrost dostępności **tlenku azotu**, działają przeciwzapalnie (spadek **CRP**), osłabiają agregację płytek i **stabilizują blaszkę miażdżycową** — zmniejszają jej rdzeń lipidowy i wzmacniają czapeczkę włóknistą, ograniczając ryzyko zawału.$E$,
   'Statyny', 'FARSTO-e2026-1-1966', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(95, 'FARM-06',
   'Do beta-blokerów kardioselektywnych należy:',
   '[{"id": "a", "text": "Metoprolol"}, {"id": "b", "text": "Bisoprolol"}, {"id": "c", "text": "Nebiwolol"}, {"id": "d", "text": "Betaksolol"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'e',
   $E$Wszystkie wymienione leki działają wybiórczo na receptory **beta1** mięśnia sercowego: **metoprolol**, **bisoprolol** i **betaksolol** obok atenololu i esmololu, a **nebiwolol** jest najbardziej kardioselektywnym beta-blokerem i dodatkowo uwalnia **tlenek azotu**, rozszerzając naczynia. Wybiórczość pozwala ostrożnie stosować tę grupę w **POChP**, cukrzycy i miażdżycy tętnic obwodowych, ale **zanika przy dużych dawkach**. Nieselektywne pozostają propranolol, sotalol i tymolol.$E$,
   'Beta-blokery', 'FARSTO-e2026-1-1967', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(96, 'FARM-07',
   'Beta-blokery wykazują działanie:',
   '[{"id": "a", "text": "Chronotropowe ujemne"}, {"id": "b", "text": "Inotropowo ujemne"}, {"id": "c", "text": "Batmotropowe dodatnie"}, {"id": "d", "text": "A i B"}, {"id": "e", "text": "A, B i C"}]'::jsonb,
   'd',
   $E$Blokada receptorów **beta1** obniża stężenie **cAMP** w kardiomiocycie, dając cztery efekty ujemne: **chronotropowy** (zwolnienie rytmu zatokowego), **inotropowy** (spadek kurczliwości), **dromotropowy** (zwolnienie przewodzenia w węźle **AV**) oraz **batmotropowy** (spadek pobudliwości) — dlatego zdanie o dodatnim działaniu batmotropowym jest błędne. Skutkiem jest mniejsze zapotrzebowanie serca na tlen, wykorzystywane w dławicy, i działanie antyarytmiczne **klasy II**.$E$,
   'Beta-blokery', 'FARSTO-e2026-1-1968', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(97, 'FARM-09',
   'Do leków znieczulenia miejscowego, będących pochodnymi amidowymi, NIE należy:',
   '[{"id": "a", "text": "lidokaina"}, {"id": "b", "text": "ropiwakaina"}, {"id": "c", "text": "bupiwakaina"}, {"id": "d", "text": "prokaina"}, {"id": "e", "text": "mepiwakaina"}]'::jsonb,
   'd',
   $E$Spośród wymienionych leków **prokaina** jako jedyna nie jest pochodną amidową, lecz **estrem** kwasu para-aminobenzoesowego — dlatego treść pytania ujęto w formie przeczącej. **Lidokaina**, **ropiwakaina**, **bupiwakaina** i **mepiwakaina** mają wiązanie **amidowe** i są metabolizowane w **wątrobie** przez układ **CYP450**, natomiast estry rozkłada **esteraza osoczowa** do **PABA** — najczęstszej przyczyny reakcji alergicznych na leki znieczulające miejscowo.$E$,
   'Leki znieczulające miejscowo', 'FARSTO-e2026-1-1969', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(98, 'FARM-08',
   'Lekiem przeciwdepresyjnym, będącym inhibitorem wychwytu zwrotnego noradrenaliny i dopaminy jest:',
   '[{"id": "a", "text": "wortioksetyna"}, {"id": "b", "text": "bupropion"}, {"id": "c", "text": "amitryptylina"}, {"id": "d", "text": "sertralina"}, {"id": "e", "text": "mianseryna"}]'::jsonb,
   'b',
   $E$**Bupropion** hamuje wychwyt zwrotny **noradrenaliny i dopaminy**, nie wpływając na przekaźnictwo serotoninowe — dlatego nie powoduje zaburzeń seksualnych ani przyrostu masy ciała, a nawet sprzyja chudnięciu. Poza depresją stosuje się go w **rzucaniu palenia**, bo osłabia głód nikotynowy. Główne ryzyko to **obniżenie progu drgawkowego**, więc przeciwwskazaniem są padaczka i bulimia. **Wortioksetyna** działa wielomodalnie serotoninowo, **mianseryna** blokuje **alfa2**, a **amitryptylina** to TLPD.$E$,
   'Leki przeciwdepresyjne', 'FARSTO-e2026-1-1970', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(99, 'FARM-10',
   'Wskaż lek znajdujący zastosowanie w leczeniu choroby Alzheimera, będący antagonistą receptora NMDA:',
   '[{"id": "a", "text": "ketamina"}, {"id": "b", "text": "donepezil"}, {"id": "c", "text": "memantyna"}, {"id": "d", "text": "galantamina"}, {"id": "e", "text": "rywastygmina"}]'::jsonb,
   'c',
   $E$**Memantyna** jest **antagonistą** receptora **NMDA** o umiarkowanym powinowactwie (w oryginale pytania omyłkowo napisano „agonista”). Blokuje kanał w sposób zależny od napięcia, tłumiąc toniczny napływ **wapnia** wywołany nadmiarem **glutaminianu**, czyli **ekscytotoksyczność**, ale nie znosi fizjologicznych sygnałów fazowych potrzebnych do uczenia się. Stosuje się ją w umiarkowanej i ciężkiej postaci choroby Alzheimera, także z inhibitorami cholinesterazy jak **donepezil**.$E$,
   'Choroba Alzheimera', 'FARSTO-e2026-1-1971', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(100, 'FARM-10',
   'Do działań niepożądanych inhibitorów cholinesterazy zaliczamy:',
   '[{"id": "a", "text": "zaburzenia żołądkowo-jelitowe"}, {"id": "b", "text": "tachykardię"}, {"id": "c", "text": "bradykardię"}, {"id": "d", "text": "A i B prawidłowe"}, {"id": "e", "text": "A i C prawidłowe"}]'::jsonb,
   'e',
   $E$Inhibitory cholinesterazy — **donepezil**, **rywastygmina** i **galantamina** — zwiększają stężenie **acetylocholiny** także obwodowo, dając objawy pobudzenia receptorów **muskarynowych**: nudności, wymioty, biegunkę i kurcze brzucha, będące najczęstszą przyczyną odstawienia leku, oraz **bradykardię** z blokiem przedsionkowo-komorowym i omdleniami — nigdy tachykardię. Uwagi wymaga też skurcz oskrzeli w **astmie** i nasilenie choroby wrzodowej; dawkę zwiększa się stopniowo.$E$,
   'Inhibitory cholinesterazy', 'FARSTO-e2026-1-1972', 'e_farm_stoma_2026/1',
   'Egzamin farmakologia STOMA SUM 2026 (FARSTO e2026-1)', ARRAY['stomatologia']::TEXT[]),
(101, 'FARM-03',
   'Do leków urykozurycznych należy:',
   '[{"id": "a", "text": "Febuksostat"}, {"id": "b", "text": "Sulfasalazyna"}, {"id": "c", "text": "Peglotykaza"}, {"id": "d", "text": "Benzbromaron"}, {"id": "e", "text": "Prawidłowa odpowiedź B i D"}]'::jsonb,
   'd',
   $E$**Benzbromaron** hamuje transporter **URAT1** w cewce bliższej, blokując zwrotne wchłanianie kwasu moczowego i zwiększając jego wydalanie z moczem — to definicja leku **urykozurycznego**. **Febuksostat** hamuje **oksydazę ksantynową**, czyli zmniejsza syntezę kwasu moczowego, a **peglotykaza** to rekombinowana **urykaza** rozkładająca go do alantoiny. **Sulfasalazyna** jest lekiem modyfikującym przebieg RZS. Benzbromaron wymaga kontroli prób wątrobowych.$E$,
   'Dna moczanowa', 'FARLEK-e2026-1-1773', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(102, 'FARM-01',
   'Allopurynol wchodzi w istotną klinicznie interakcję z azatiopryną, dlatego jednoczesne stosowanie obu leków wymaga zmniejszenia dawki azatiopryny.',
   '[{"id": "a", "text": "Pierwsze zdanie jest prawdziwe, drugie zdanie jest fałszywe"}, {"id": "b", "text": "Pierwsze zdanie jest fałszywe, drugie zdanie jest prawdziwe"}, {"id": "c", "text": "Oba zdania są fałszywe"}, {"id": "d", "text": "Oba zdania są prawdziwe, lecz nie ma między nimi związku przyczynowo-skutkowego"}, {"id": "e", "text": "Oba zdania są prawdziwe i zachodzi pomiędzy nimi związek przyczynowo-skutkowy"}]'::jsonb,
   'e',
   $E$**Allopurynol** hamuje **oksydazę ksantynową**, która rozkłada **6-merkaptopurynę** — czynny metabolit **azatiopryny**. Zablokowanie tej drogi wielokrotnie zwiększa stężenie 6-MP, grożąc ciężką **mielosupresją** i pancytopenią. Dlatego przy skojarzeniu dawkę azatiopryny redukuje się do ok. **25-33%** wyjściowej albo unika się połączenia. Oba zdania są prawdziwe i drugie wynika z pierwszego — klasyczna **interakcja farmakokinetyczna** na etapie metabolizmu.$E$,
   'Interakcje metaboliczne', 'FARLEK-e2026-1-1774', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(103, 'FARM-03',
   'Lekiem, który zmniejsza stężenie kwasu moczowego w surowicy poprzez nasilenie jego wydalania jest:',
   '[{"id": "a", "text": "Allopurynol"}, {"id": "b", "text": "Febuksostat"}, {"id": "c", "text": "Lesinurad"}, {"id": "d", "text": "Prawidłowe są odpowiedzi A i B"}, {"id": "e", "text": "Prawidłowe są odpowiedzi A, B i C"}]'::jsonb,
   'c',
   $E$**Lesinurad** blokuje transportery **URAT1** i **OAT4** w cewce bliższej, hamując reabsorpcję kwasu moczowego — działa więc **urykozurycznie**. **Allopurynol** i **febuksostat** obniżają urykemię zupełnie inaczej: hamują **oksydazę ksantynową**, czyli zmniejszają produkcję kwasu moczowego, nie zwiększając jego wydalania. Lesinurad wolno stosować wyłącznie **w skojarzeniu** z inhibitorem oksydazy ksantynowej — w monoterapii grozi ostrym uszkodzeniem nerek.$E$,
   'Dna moczanowa', 'FARLEK-e2026-1-1775', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(104, 'FARM-03',
   'Alkaloidem zimowita jesiennego stosowanym w leczeniu ostrego napadu dny moczanowej jest:',
   '[{"id": "a", "text": "Winblastyna"}, {"id": "b", "text": "Winkrystyna"}, {"id": "c", "text": "Kapecytabina"}, {"id": "d", "text": "Kolchicyna"}, {"id": "e", "text": "Winpocetyna"}]'::jsonb,
   'd',
   $E$**Kolchicyna** to alkaloid **zimowita jesiennego** (Colchicum autumnale). Wiąże **tubulinę** i hamuje polimeryzację mikrotubul, przez co blokuje chemotaksję oraz degranulację **neutrofilów** w stawie — stąd skuteczność w ostrym napadzie **dny**. Winblastyna i winkrystyna również działają na mikrotubule, ale pochodzą z barwinka różyczkowego i są cytostatykami. Objawem przedawkowania kolchicyny jest **biegunka** i wymioty poprzedzające uszkodzenie szpiku.$E$,
   'Dna moczanowa', 'FARLEK-e2026-1-1776', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(105, 'FARM-01',
   'Receptorem metabotropowym sprzężonym z białkiem Gq jest receptor:',
   '[{"id": "a", "text": "Histaminowy H1, adrenergiczny alfa1"}, {"id": "b", "text": "Histaminowy H2, adrenergiczny alfa2"}, {"id": "c", "text": "Histaminowy H3, adrenergiczny beta1"}, {"id": "d", "text": "Serotoninowy 5-HT3, adrenergiczny beta2"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'a',
   $E$Receptory **H1** i **alfa1** to klasyczne receptory sprzężone z białkiem **Gq**: aktywują **fosfolipazę C**, dając **IP3 i DAG** oraz wzrost wewnątrzkomórkowego **Ca2+**, czego efektem jest skurcz mięśni gładkich. **H2** oraz **beta1/beta2** sygnalizują przez **Gs** (wzrost cAMP), **alfa2** i **H3** przez **Gi** (spadek cAMP), natomiast **5-HT3** jest jedynym serotoninowym receptorem **jonotropowym** — kanałem kationowym. Mnemonik: **alfa1 i H1 — Gq**, **H2 i beta — Gs**, **alfa2 i H3 — Gi**.$E$,
   'Receptory metabotropowe', 'FARLEK-e2026-1-1777', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(106, 'FARM-01',
   'Aktywacja fosfolipazy C oraz związany z tym wzrost stężenia w cytozolu trifosforanu inozytolu i jonów wapnia jest typowym efektem pobudzenia receptorów:',
   '[{"id": "a", "text": "Jonotropowych"}, {"id": "b", "text": "Metabotropowych sprzężonych z białkiem Gs"}, {"id": "c", "text": "Metabotropowych sprzężonych z białkiem Gi"}, {"id": "d", "text": "Metabotropowych sprzężonych z białkiem Gq"}, {"id": "e", "text": "Jądrowych"}]'::jsonb,
   'd',
   $E$Szlak **Gq — fosfolipaza C beta — PIP2 — IP3 i DAG** kończy się uwolnieniem **Ca2+** z siateczki śródplazmatycznej oraz aktywacją **kinazy białkowej C**. Tak sygnalizują m.in. receptory **alfa1**, **H1**, **M1/M3**, **5-HT2**, **AT1** i **V1**. Receptory **Gs** i **Gi** modulują **cyklazę adenylanową** i stężenie **cAMP**, jonotropowe są kanałami bramkowanymi ligandem, a jądrowe zmieniają transkrypcję genów — działają wolno, ale długotrwale.$E$,
   'Przekaźnictwo wewnątrzkomórkowe', 'FARLEK-e2026-1-1778', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(107, 'FARM-09',
   'Działanie stymulujące na pozasynaptyczne receptory GABA-A posiadają:',
   '[{"id": "a", "text": "Gaboksadol"}, {"id": "b", "text": "Izoguwacyna"}, {"id": "c", "text": "Etomidat"}, {"id": "d", "text": "Prawidłowe są odpowiedzi A i B"}, {"id": "e", "text": "Prawidłowe są odpowiedzi A, B i C"}]'::jsonb,
   'e',
   $E$Pozasynaptyczne receptory **GABA-A** zawierają podjednostkę **delta** i odpowiadają za hamowanie **toniczne**, a nie fazowe. **Gaboksadol (THIP)** i **izoguwacyna** to bezpośredni agoniści preferujący receptory delta-zawierające, natomiast **etomidat** działa poprzez podjednostki **beta2/beta3** i również nasila prąd toniczny — prawidłowe są zatem wszystkie trzy. Warto pamiętać, że etomidat hamuje **11-beta-hydroksylazę** i steroidogenezę nadnerczową.$E$,
   'Receptory GABA-A', 'FARLEK-e2026-1-1779', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(108, 'FARM-14',
   'Do działań niepożądanych, które mogą wystąpić w czasie stosowania ogólnego gancyklowiru należą:',
   '[{"id": "a", "text": "Zaparcia"}, {"id": "b", "text": "Nadmierna senność"}, {"id": "c", "text": "Bladość skóry"}, {"id": "d", "text": "Obniżona temperatura ciała"}, {"id": "e", "text": "Neuropatia obwodowa"}]'::jsonb,
   'e',
   $E$**Gancyklowir** hamuje polimerazę DNA **CMV** po fosforylacji przez wirusową kinazę **UL97**. Jego toksyczność dotyczy tkanek szybko dzielących się i układu nerwowego: dominuje **mielosupresja** (neutropenia, małopłytkowość, niedokrwistość), a ponadto występują objawy ośrodkowe — splątanie, drgawki — oraz **neuropatia obwodowa**. Zaparcia, senność czy hipotermia nie są typowe. Kojarzenie z **zydowudyną** znacząco nasila uszkodzenie szpiku.$E$,
   'Leki przeciwwirusowe', 'FARLEK-e2026-1-1780', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(109, 'FARM-14',
   'Do nukleozydowych i nukleotydowych inhibitorów odwrotnej transkryptazy nie należy:',
   '[{"id": "a", "text": "Zydowudyna"}, {"id": "b", "text": "Abakawir"}, {"id": "c", "text": "Atazanawir"}, {"id": "d", "text": "Lamiwudyna"}, {"id": "e", "text": "Emtrycytabina"}]'::jsonb,
   'c',
   $E$**Atazanawir** jest **inhibitorem proteazy** HIV — rozpoznajemy go po końcówce **-nawir**; typowym działaniem niepożądanym jest **hiperbilirubinemia** niesprzężona wskutek hamowania UGT1A1. Pozostałe leki to **NRTI**: po fosforylacji wbudowują się jako fałszywe nukleotydy i przerywają łańcuch DNA. Przed podaniem **abakawiru** trzeba oznaczyć **HLA-B*5701** (ryzyko ciężkiej reakcji nadwrażliwości), a **zydowudyna** wywołuje niedokrwistość i miopatię.$E$,
   'Leki przeciwretrowirusowe', 'FARLEK-e2026-1-1781', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(110, 'FARM-14',
   'Do natychmiastowych działań niepożądanych amfoterycyny B należy:',
   '[{"id": "a", "text": "Nefrotoksyczność"}, {"id": "b", "text": "Hepatotoksyczność"}, {"id": "c", "text": "Obniżenie ciśnienia tętniczego"}, {"id": "d", "text": "Niedokrwistość"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'c',
   $E$Amfoterycyna B ma dwa rozłączne profile toksyczności. **Natychmiastowy**, związany z wlewem, to gorączka, dreszcze, bóle mięśni, nudności i **spadek ciśnienia tętniczego** — reakcja typu shake-and-bake, łagodzona premedykacją i wolnym podawaniem. **Późna, kumulacyjna** toksyczność obejmuje **nefrotoksyczność** z hipokaliemią i hipomagnezemią oraz niedokrwistość. Mechanizm działania: wiązanie **ergosterolu** i tworzenie porów w błonie grzyba.$E$,
   'Leki przeciwgrzybicze', 'FARLEK-e2026-1-1782', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(111, 'FARM-02',
   'Receptory 5-HT4 są receptorami:',
   '[{"id": "a", "text": "Metabotropowymi sprzężonymi z białkiem Gs"}, {"id": "b", "text": "Metabotropowymi sprzężonymi z białkiem Gi"}, {"id": "c", "text": "Metabotropowymi sprzężonymi z białkiem Gq"}, {"id": "d", "text": "Jonotropowymi"}, {"id": "e", "text": "Metabotropowymi o aktywności kinazy tyrozynowej"}]'::jsonb,
   'a',
   $E$**5-HT4** to receptor **metabotropowy sprzężony z Gs**: pobudza **cyklazę adenylanową** i podnosi stężenie **cAMP**. W splocie mięśniowym jelita zwiększa uwalnianie **acetylocholiny**, nasilając perystaltykę — na tym opiera się działanie **prukaloprydu** i wycofanego cyzaprydu (wydłużanie QT). Spośród receptorów serotoninowych wyłącznie **5-HT3** jest **jonotropowy**; 5-HT1 sprzęga się z **Gi**, a 5-HT2 z **Gq**. **Prukalopryd** jest wysoce selektywny wobec 5-HT4, dzięki czemu nie blokuje kanału hERG.$E$,
   'Serotonina i receptory 5-HT', 'FARLEK-e2026-1-1783', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(112, 'FARM-02',
   'Przeciwciałem monoklonalnym, stosowanym w profilaktyce migreny, które jest ukierunkowane przeciwko receptorowi dla CGRP (peptyd związany z genem kalcytoniny), jest:',
   '[{"id": "a", "text": "Eptinezumab"}, {"id": "b", "text": "Erenumab"}, {"id": "c", "text": "Galkanezumab"}, {"id": "d", "text": "Fremanezumab"}, {"id": "e", "text": "Prawidłowe są A i C"}]'::jsonb,
   'b',
   $E$**Erenumab** jako jedyny z przeciwciał przeciwmigrenowych blokuje **receptor CGRP**; eptinezumab, galkanezumab i fremanezumab wiążą samą **cząsteczkę CGRP**, czyli ligand. Wszystkie służą do **profilaktyki** migreny epizodycznej i przewlekłej — podskórnie co miesiąc lub kwartał, eptinezumab dożylnie. Do przerywania napadu stosuje się tryptany i gepanty.
Mnemonik: **-NEZumab** wiąże ligand, natomiast **erEnumab** — receptor (E jak receptor).$E$,
   'Migrena', 'FARLEK-e2026-1-1784', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(113, 'FARM-02',
   'Lasmiditan jest:',
   '[{"id": "a", "text": "Agonistą receptorów 5-HT1B/D stosowanym w leczeniu napadów migreny"}, {"id": "b", "text": "Agonistą receptorów 5-HT1B/D stosowanym w profilaktyce napadów migreny"}, {"id": "c", "text": "Agonistą receptorów 5-HT1F stosowanym w leczeniu napadów migreny"}, {"id": "d", "text": "Agonistą receptorów 5-HT1F stosowanym w profilaktyce napadów migreny"}, {"id": "e", "text": "Antagonistą receptorów 5-HT2 stosowanym w profilaktyce napadów migreny"}]'::jsonb,
   'c',
   $E$**Lasmiditan** to selektywny agonista receptorów **5-HT1F**, pierwszy przedstawiciel **ditanów**, stosowany **doraźnie** w napadzie migreny. W odróżnieniu od **tryptanów** (agoniści 5-HT1B/1D) nie kurczy naczyń, więc można go podać choremu z chorobą wieńcową, po zawale czy udarze — to jego kluczowa przewaga. Ceną jest silne działanie ośrodkowe: **zawroty głowy**, senność i parestezje, z zakazem prowadzenia pojazdów przez 8 godzin.$E$,
   'Migrena', 'FARLEK-e2026-1-1785', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(114, 'FARM-10',
   'Lekiem o największej skuteczności w leczeniu stwardnienia zanikowego bocznego jest:',
   '[{"id": "a", "text": "Mitoksantron"}, {"id": "b", "text": "Natalizumab"}, {"id": "c", "text": "Octan glatirameru"}, {"id": "d", "text": "Ryluzol"}, {"id": "e", "text": "Siponimod"}]'::jsonb,
   'd',
   $E$**Ryluzol** to jedyny lek o udokumentowanym wpływie na przeżycie w **stwardnieniu zanikowym bocznym** — wydłuża je o około **3 miesiące** lub odsuwa moment tracheostomii. Hamuje presynaptyczne uwalnianie **glutaminianu** i blokuje kanały sodowe, ograniczając **ekscytotoksyczne** uszkodzenie motoneuronów. Wymaga kontroli **aminotransferaz** oraz morfologii. Pozostałe wymienione leki są lekami modyfikującymi przebieg stwardnienia rozsianego, nie SLA.$E$,
   'Stwardnienie zanikowe boczne', 'FARLEK-e2026-1-1786', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(115, 'FARM-14',
   'W leczeniu rzęsistkowicy znajdują zastosowanie przede wszystkim:',
   '[{"id": "a", "text": "Pochodne nitroimidazolu"}, {"id": "b", "text": "Tetracykliny"}, {"id": "c", "text": "Makrolidy"}, {"id": "d", "text": "Fusydany"}, {"id": "e", "text": "Streptograminy"}]'::jsonb,
   'a',
   $E$Rzęsistkowicę wywołaną przez **Trichomonas vaginalis** leczy się **pochodnymi nitroimidazolu** — **metronidazolem** lub tynidazolem, doustnie i zawsze **równocześnie u partnera seksualnego**. Grupa nitrowa ulega redukcji w beztlenowych warunkach pierwotniaka do rodników uszkadzających jego DNA. Leczenie wyłącznie miejscowe jest nieskuteczne. Klasyczna pułapka to **reakcja disulfiramowa** po alkoholu. Antybiotyki wymienione w pozostałych opcjach nie działają na pierwotniaki.$E$,
   'Leki przeciwpierwotniakowe', 'FARLEK-e2026-1-1787', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(116, 'FARM-09',
   'Anestetykiem wziewnym, który uchodzi za środek najbliższy idealnemu, jest:',
   '[{"id": "a", "text": "Enfluran"}, {"id": "b", "text": "Sewofluran"}, {"id": "c", "text": "Desfluran"}, {"id": "d", "text": "Izofluran"}, {"id": "e", "text": "Halotan"}]'::jsonb,
   'b',
   $E$**Sewofluran** najbardziej zbliża się do anestetyku idealnego: niski współczynnik rozdziału **krew/gaz (ok. 0,65)** zapewnia szybką indukcję i wybudzenie, a brak drażniącego zapachu pozwala na **indukcję wziewną u dzieci**. Dodatkowo rozszerza oskrzela i jest stabilny hemodynamicznie. **Desfluran** silnie drażni drogi oddechowe, **halotan** grozi hepatotoksycznością i arytmiami, **enfluran** działa drgawkorodnie. Wadą sewofluranu jest powstawanie **związku A**.$E$,
   'Anestetyki wziewne', 'FARLEK-e2026-1-1788', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(117, 'FARM-09',
   'Krótko działający anestetyk, wywołujący szybką indukcję znieczulenia, podawany samodzielnie przy krótkich zabiegach, szczególnie korzystny dlatego, że nie wywołuje depresyjnego wpływu na czynność serca i układ oddechowy. Opis dotyczy:',
   '[{"id": "a", "text": "Tiopental"}, {"id": "b", "text": "Halotan"}, {"id": "c", "text": "Etomidat"}, {"id": "d", "text": "Droperydol"}, {"id": "e", "text": "Desfluran"}]'::jsonb,
   'c',
   $E$**Etomidat** to pochodna imidazolowa o bardzo szybkim początku działania i krótkiej hipnozie, wyróżniająca się **stabilnością hemodynamiczną** oraz minimalną depresją oddechową — dlatego jest anestetykiem z wyboru u chorych niestabilnych krążeniowo i we wstrząsie. Nie działa przeciwbólowo. Wady: mioklonie, ból przy wstrzyknięciu, nudności oraz zahamowanie **11-beta-hydroksylazy**, co wyklucza wlewy ciągłe. **Tiopental** silnie obniża ciśnienie.$E$,
   'Anestetyki dożylne', 'FARLEK-e2026-1-1789', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(118, 'FARM-06',
   'Lekiem, który jest jednocześnie antagonistą receptorów endotelinowych oraz receptora dla angiotensyny, zarejestrowanym do leczenia nefropatii IgA, jest:',
   '[{"id": "a", "text": "Bozentan"}, {"id": "b", "text": "Ambryzentan"}, {"id": "c", "text": "Macytentan"}, {"id": "d", "text": "Sparsentan"}, {"id": "e", "text": "Sytaksentan"}]'::jsonb,
   'd',
   $E$**Sparsentan** to podwójny antagonista receptora endotelinowego **ETA** oraz receptora **AT1** dla angiotensyny II. Zarejestrowano go do leczenia pierwotnej **nefropatii IgA** z białkomoczem, gdzie istotnie zmniejsza proteinurię i spowalnia spadek **eGFR**. Bozentan, macytentan, ambryzentan i sytaksentan blokują wyłącznie receptory endotelinowe i służą w **tętniczym nadciśnieniu płucnym**. Cała grupa jest **hepatotoksyczna i silnie teratogenna**.$E$,
   'Antagoniści receptora endotelinowego', 'FARLEK-e2026-1-1790', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(119, 'FARM-02',
   'Do antagonistów receptora histaminowego H1 pierwszej generacji nie należy:',
   '[{"id": "a", "text": "Antazolina"}, {"id": "b", "text": "Azelastyna"}, {"id": "c", "text": "Doksylamina"}, {"id": "d", "text": "Prometazyna"}, {"id": "e", "text": "Klemastyna"}]'::jsonb,
   'b',
   $E$**Azelastyna** należy do **II generacji** leków przeciwhistaminowych i stosowana jest donosowo oraz do worka spojówkowego; nie przenika istotnie do OUN. Antazolina, doksylamina, prometazyna i klemastyna to **I generacja** — związki lipofilne, blokujące dodatkowo receptory **muskarynowe** i alfa-adrenergiczne, przez co dają **sedację**, suchość w ustach i zatrzymanie moczu. Sedację I generacji wykorzystuje się czasem celowo, np. doksylaminę jako lek nasenny.$E$,
   'Leki przeciwhistaminowe', 'FARLEK-e2026-1-1791', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(120, 'FARM-02',
   'Do antagonistów receptora histaminowego H1 drugiej generacji nie należy:',
   '[{"id": "a", "text": "Astemizol"}, {"id": "b", "text": "Ebastyna"}, {"id": "c", "text": "Antazolina"}, {"id": "d", "text": "Mizolastyna"}, {"id": "e", "text": "Loratadyna"}]'::jsonb,
   'c',
   $E$**Antazolina** to klasyczny lek **I generacji** — pochodna etylenodiaminy, dostępna również dożylnie w reakcjach alergicznych, o wyraźnym działaniu **antycholinergicznym** i sedatywnym. Astemizol, ebastyna, mizolastyna i loratadyna należą do **II generacji**: słabo przenikają barierę krew-mózg, więc nie powodują senności. **Astemizol** i terfenadynę wycofano z powodu blokowania kanału **hERG** i ryzyka **torsade de pointes**, zwłaszcza z inhibitorami CYP3A4.$E$,
   'Leki przeciwhistaminowe', 'FARLEK-e2026-1-1792', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(121, 'FARM-15',
   'Który z leków stosowany jest w leczeniu jadłowstrętu:',
   '[{"id": "a", "text": "Metoklopramid"}, {"id": "b", "text": "Diazepam"}, {"id": "c", "text": "Nabilon"}, {"id": "d", "text": "Prometazyna"}, {"id": "e", "text": "Difenhydramina"}]'::jsonb,
   'c',
   $E$**Nabilon** jest syntetycznym analogiem **THC** i agonistą receptorów kannabinoidowych **CB1**, przez co pobudza ośrodek głodu w podwzgórzu. Stosuje się go w **jadłowstręcie i wyniszczeniu** w przebiegu choroby nowotworowej oraz AIDS, a także w opornych wymiotach po chemioterapii. Metoklopramid, prometazyna i difenhydramina działają wyłącznie przeciwwymiotnie, nie zwiększając apetytu. Typowe działania niepożądane nabilonu to euforia, dysforia, senność i **hipotonia ortostatyczna**.$E$,
   'Leki przeciwwymiotne i pobudzające apetyt', 'FARLEK-e2026-1-1793', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(122, 'FARM-14',
   'Lekiem pierwszego rzutu stosowanym w zwalczaniu tasiemczycy jest:',
   '[{"id": "a", "text": "Pyrantel"}, {"id": "b", "text": "Prazykwantel"}, {"id": "c", "text": "Oksamnichina"}, {"id": "d", "text": "Iwermektyna"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'b',
   $E$**Prazykwantel** zwiększa przepuszczalność oskórka pasożyta dla **jonów wapnia**, wywołując skurcz spastyczny i wakuolizację tegumentu — pasożyt zostaje wydalony. Jest lekiem z wyboru w **tasiemczycach** (Taenia, bruzdogłowiec) oraz w schistosomatozie; alternatywą pozostaje niklozamid. **Pyrantel** i **iwermektyna** działają na **nicienie**, a **oksamnichina** wyłącznie na Schistosoma mansoni. W wągrzycy prazykwantel wymaga osłony glikokortykosteroidem.$E$,
   'Leki przeciwrobacze', 'FARLEK-e2026-1-1794', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(123, 'FARM-14',
   'Do zwalczania robaków obłych stosuje się:',
   '[{"id": "a", "text": "Niklozamid"}, {"id": "b", "text": "Albendazol"}, {"id": "c", "text": "Pyrantel"}, {"id": "d", "text": "Odpowiedzi A i C"}, {"id": "e", "text": "Odpowiedzi B i C"}]'::jsonb,
   'e',
   $E$Robaki obłe, czyli **nicienie** (owsik, glista, włosogłówka, tęgoryjec), zwalcza się **albendazolem** i **pyrantelem**. Albendazol wiąże **beta-tubulinę** pasożyta, blokując polimeryzację mikrotubul i wychwyt glukozy. Pyrantel jest **agonistą receptorów nikotynowych** robaka: wywołuje depolaryzację i **porażenie spastyczne** mięśni, dlatego nie wolno go łączyć z piperazyną, która działa przeciwstawnie. **Niklozamid** służy natomiast wyłącznie do zwalczania tasiemców.$E$,
   'Leki przeciwrobacze', 'FARLEK-e2026-1-1795', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(124, 'FARM-08',
   'Do substancji, które mogą przyczynić się do wystąpienia objawów zespołu serotoninowego, należy:',
   '[{"id": "a", "text": "Tramadol"}, {"id": "b", "text": "Fluoksetyna"}, {"id": "c", "text": "Sertralina"}, {"id": "d", "text": "Prawidłowe A, B i C"}, {"id": "e", "text": "Prawidłowe B i C"}]'::jsonb,
   'd',
   $E$Wszystkie trzy leki zwiększają przekaźnictwo serotoninergiczne: **fluoksetyna** i **sertralina** jako **SSRI**, a **tramadol** dodatkowo hamuje wychwyt zwrotny serotoniny obok działania na receptor mi. Zespół serotoninowy to triada: pobudzenie **autonomiczne** (gorączka, tachykardia, poty), zaburzenia świadomości oraz nadmierna aktywność nerwowo-mięśniowa (**klonus**, hiperrefleksja, mioklonie, nasilone w kończynach dolnych). Leczenie: odstawienie leków i **cyproheptadyna**.$E$,
   'Zespół serotoninowy', 'FARLEK-e2026-1-1796', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(125, 'FARM-18',
   'Do substancji wywołujących drgawki w przebiegu zatrucia należy:',
   '[{"id": "a", "text": "Paracetamol"}, {"id": "b", "text": "Izoniazyd"}, {"id": "c", "text": "Aceton"}, {"id": "d", "text": "Propoksyfen"}, {"id": "e", "text": "Glutaminian sodu"}]'::jsonb,
   'b',
   $E$**Izoniazyd** wiąże i inaktywuje **fosforan pirydoksalu**, blokując **dekarboksylazę kwasu glutaminowego** — spada synteza **GABA** i pojawiają się drgawki oporne na benzodiazepiny, kwasica mleczanowa oraz śpiączka. Odtrutką jest **pirydoksyna (witamina B6)** dożylnie, w dawce gramowo odpowiadającej przyjętej dawce izoniazydu. Zatrucie **paracetamolem** prowadzi do martwicy wątroby, nie do drgawek. Inne klasyczne drgawkorodne trucizny to teofilina, TLPD i bupropion.$E$,
   'Zatrucia lekami', 'FARLEK-e2026-1-1797', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(126, 'FARM-15',
   'Do agonistów silnie pobudzających receptory motyliny należy:',
   '[{"id": "a", "text": "Trimebutyna"}, {"id": "b", "text": "Maraliksybat"}, {"id": "c", "text": "Alwimopan"}, {"id": "d", "text": "Erytromycyna"}, {"id": "e", "text": "Sorbitol"}]'::jsonb,
   'd',
   $E$**Erytromycyna** poza działaniem przeciwbakteryjnym jest silnym **agonistą receptorów motylinowych** i pobudza wędrujący kompleks mioelektryczny żołądka. Wykorzystuje się to w **gastroparezie** cukrzycowej oraz przed gastroskopią w krwawieniu z górnego odcinka przewodu pokarmowego. Wadą jest szybka **tachyfilaksja** wskutek down-regulacji receptorów. Trimebutyna moduluje receptory opioidowe jelita, **alwimopan** to obwodowy antagonista mi, a sorbitol działa osmotycznie.$E$,
   'Leki prokinetyczne', 'FARLEK-e2026-1-1798', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(127, 'FARM-11',
   'Wspomagająco w leczeniu cukrzycy typu 2, zespołu metabolicznego oraz hiperlipidemii działa:',
   '[{"id": "a", "text": "Cynk"}, {"id": "b", "text": "Fluor"}, {"id": "c", "text": "Miedź"}, {"id": "d", "text": "Molibden"}, {"id": "e", "text": "Chrom"}]'::jsonb,
   'e',
   $E$**Chrom** na III stopniu utlenienia wchodzi w skład **czynnika tolerancji glukozy**, który zwiększa wrażliwość tkanek na **insulinę** przez nasilenie autofosforylacji jej receptora. Suplementacja bywa więc stosowana wspomagająco w **cukrzycy typu 2**, zespole metabolicznym i hiperlipidemii, gdzie może nieznacznie obniżać stężenie LDL. **Cynk** jest kofaktorem wielu enzymów i warunkuje gojenie, **fluor** chroni szkliwo, a **molibden** to kofaktor oksydazy ksantynowej.$E$,
   'Biopierwiastki', 'FARLEK-e2026-1-1799', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(128, 'FARM-04',
   'Receptory alfa1-adrenergiczne:',
   '[{"id": "a", "text": "Działają za pośrednictwem białka Gi"}, {"id": "b", "text": "Drugim przekaźnikiem są IP3 i DAG, a następnie jony wapnia"}, {"id": "c", "text": "Powodują rozkurcz mięśni gładkich (z wyjątkiem przewodu pokarmowego)"}, {"id": "d", "text": "Selektywnym antagonistą jest fenylefryna"}, {"id": "e", "text": "Selektywnym agonistą jest doksazosyna"}]'::jsonb,
   'b',
   $E$Receptor **alfa1** sprzęga się z białkiem **Gq**, aktywuje **fosfolipazę C** i generuje **IP3 oraz DAG**, co uwalnia **Ca2+** i wywołuje **skurcz** mięśni gładkich naczyń, zwieracza pęcherza i mięśnia rozwieracza źrenicy. Wyjątkiem jest przewód pokarmowy, gdzie następuje rozkurcz. Dwa ostatnie warianty zamieniają role: **fenylefryna** to selektywny **agonista**, a **doksazosyna** — selektywny **antagonista** alfa1, stosowany w przeroście prostaty.$E$,
   'Receptory adrenergiczne', 'FARLEK-e2026-1-1800', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(129, 'FARM-16',
   'Wskaż prawdziwe stwierdzenie dotyczące środków stosowanych w celu czasowego zahamowania płodności:',
   '[{"id": "a", "text": "Mechanizmy działania preparatów dwuskładnikowych i jednoskładnikowych są takie same"}, {"id": "b", "text": "Skuteczność preparatów jednoskładnikowych jest wyższa niż dwuskładnikowych"}, {"id": "c", "text": "Preparaty dwuskładnikowe najczęściej stosuje się codziennie, bez przerwy"}, {"id": "d", "text": "Preparaty jednoskładnikowe wywierają działanie zarówno antykoncepcyjne jak i antyimplantacyjne"}, {"id": "e", "text": "Preparaty jednoskładnikowe są przeciwwskazane u palących kobiet po 35 roku życia ze względu na ryzyko powikłań zakrzepowo-zatorowych"}]'::jsonb,
   'd',
   $E$Preparaty **jednoskładnikowe** (minipigułka gestagenna) tylko częściowo hamują owulację, a działają głównie przez **zagęszczenie śluzu szyjkowego** oraz **atrofię endometrium**, co daje dodatkowy efekt **antyimplantacyjny**. Preparaty **dwuskładnikowe** blokują wyrzut **LH i FSH**, więc mechanizmy nie są tożsame, a ich skuteczność jest wyższa; stosuje się je cyklicznie z przerwą. To właśnie estrogen odpowiada za ryzyko **zakrzepowo-zatorowe** u palaczek po 35 roku życia.$E$,
   'Antykoncepcja hormonalna', 'FARLEK-e2026-1-1801', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(130, 'FARM-05',
   'Przeciwwskazaniem bezwzględnym do stosowania doustnych leków przeciwzakrzepowych jest:',
   '[{"id": "a", "text": "Ciężka niewydolność wątroby lub nerek"}, {"id": "b", "text": "Retinopatia cukrzycowa"}, {"id": "c", "text": "Objawowe nadciśnienie wrotne"}, {"id": "d", "text": "Źle kontrolowane nadciśnienie tętnicze"}, {"id": "e", "text": "Małopłytkowość immunologiczna zależna od heparyny (HIT)"}]'::jsonb,
   'c',
   $E$**Objawowe nadciśnienie wrotne** oznacza obecność **żylaków przełyku** i realne ryzyko masywnego, śmiertelnego krwotoku, dlatego stanowi przeciwwskazanie **bezwzględne**. Ciężka niewydolność wątroby i źle kontrolowane nadciśnienie tętnicze wymagają ostrożności, ale traktowane są jako przeciwwskazania **względne** — a sama niewydolność nerek nie wyklucza stosowania **antagonistów witaminy K**. W **HIT** doustne antykoagulanty włącza się po normalizacji liczby płytek.$E$,
   'Doustne leki przeciwzakrzepowe', 'FARLEK-e2026-1-1802', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(131, 'FARM-01',
   'Zjawisko, w którym lek po dłuższym stosowaniu wywołuje coraz słabszy efekt, wymagając zwiększenia dawki do uzyskania tego samego działania, to:',
   '[{"id": "a", "text": "Tachyfilaksja"}, {"id": "b", "text": "Tolerancja farmakodynamiczna"}, {"id": "c", "text": "Regulacja „w górę” (up-regulation)"}, {"id": "d", "text": "Desensytyzacja receptorowa"}, {"id": "e", "text": "Efekt pierwszego przejścia"}]'::jsonb,
   'b',
   $E$**Tolerancja farmakodynamiczna** rozwija się **powoli**, w ciągu dni lub tygodni, i polega na adaptacji receptorów — najczęściej ich **down-regulacji** — co wymusza zwiększanie dawki, jak przy opioidach czy azotanach. **Tachyfilaksja** to zjawisko **nagłe**, po kilku kolejnych dawkach, klasycznie przy efedrynie wskutek wyczerpania zapasów noradrenaliny. Up-regulacja zwiększałaby odpowiedź, a **efekt pierwszego przejścia** jest zjawiskiem czysto farmakokinetycznym.$E$,
   'Tolerancja i tachyfilaksja', 'FARLEK-e2026-1-1803', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(132, 'FARM-03',
   'Wskaż lek będący selektywnym inhibitorem COX-2:',
   '[{"id": "a", "text": "Celekoksyb"}, {"id": "b", "text": "Indometacyna"}, {"id": "c", "text": "Naproksen"}, {"id": "d", "text": "Ibuprofen"}, {"id": "e", "text": "Diklofenak"}]'::jsonb,
   'a',
   $E$**Celekoksyb** wybiórczo hamuje **COX-2**, indukowaną w ognisku zapalnym, oszczędzając **COX-1** odpowiedzialną za cytoprotekcyjne prostaglandyny błony śluzowej — stąd mniejsze ryzyko wrzodów i krwawień. Ceną jest zaburzenie równowagi między naczyniorozszerzającą **prostacykliną** a płytkowym **tromboksanem A2**, co zwiększa ryzyko incydentów zakrzepowych. Celekoksyb jest **sulfonamidem**, więc jest przeciwwskazany przy uczuleniu na tę grupę. Diklofenak wykazuje jedynie preferencyjność.$E$,
   'NLPZ', 'FARLEK-e2026-1-1804', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(133, 'FARM-03',
   'Lek stosowany w terapii przewlekłej dny moczanowej, który działa poprzez rozkładanie kwasu moczowego do alantoiny to:',
   '[{"id": "a", "text": "Febuksostat"}, {"id": "b", "text": "Lesynurad"}, {"id": "c", "text": "Peglotykaza"}, {"id": "d", "text": "Benzbromaron"}, {"id": "e", "text": "Allopurynol"}]'::jsonb,
   'c',
   $E$**Peglotykaza** to pegylowana rekombinowana **urykaza** (oksydaza moczanowa) — enzym, którego człowiek nie posiada. Utlenia ona kwas moczowy do dobrze rozpuszczalnej **alantoiny**, gwałtownie obniżając urykemię. Podaje się ją dożylnie co 2 tygodnie w **ciężkiej dnie guzkowej opornej** na inne leczenie. Ograniczeniem są reakcje anafilaktyczne i przeciwciała neutralizujące, a u chorych z niedoborem **G6PD** grozi hemoliza i methemoglobinemia — stąd konieczność wcześniejszych oznaczeń.$E$,
   'Dna moczanowa', 'FARLEK-e2026-1-1805', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(134, 'FARM-15',
   'Wskaż lek będący antagonistą receptora 5-HT3 stosowany w wymiotach po chemioterapii:',
   '[{"id": "a", "text": "Ondansetron"}, {"id": "b", "text": "Metoklopramid"}, {"id": "c", "text": "Aprepitant"}, {"id": "d", "text": "Prochlorperazyna"}, {"id": "e", "text": "Dimenhydrynat"}]'::jsonb,
   'a',
   $E$**Ondansetron** blokuje receptory **5-HT3** na zakończeniach nerwu błędnego w jelicie oraz w **strefie chemoreceptorowej** dna komory IV. Chemioterapia, zwłaszcza **cisplatyną**, uwalnia serotoninę z komórek enterochromatofilnych jelita — dlatego setrony są podstawą profilaktyki wymiotów **ostrych**. **Aprepitant** działa inaczej: blokuje receptor **NK1** dla substancji P i chroni głównie przed wymiotami opóźnionymi. Uwaga na zaparcia, bóle głowy i **wydłużenie odstępu QT**.$E$,
   'Leki przeciwwymiotne', 'FARLEK-e2026-1-1806', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(135, 'FARM-06',
   'Który z poniższych leków jest inhibitorem fosfodiesterazy typu 5 i stosowany w leczeniu nadciśnienia płucnego?',
   '[{"id": "a", "text": "Bosentan"}, {"id": "b", "text": "Riociguat"}, {"id": "c", "text": "Sildenafil"}, {"id": "d", "text": "Iloprost"}, {"id": "e", "text": "Ambrisentan"}]'::jsonb,
   'c',
   $E$**Sildenafil** hamuje **fosfodiesterazę typu 5**, która rozkłada **cGMP** w mięśniówce naczyń płucnych — utrzymanie wysokiego cGMP powoduje wybiórcze rozszerzenie krążenia płucnego. Bezwzględnie przeciwwskazane jest łączenie z **azotanami** (groźna hipotensja) oraz z **riociguatem**, który stymuluje rozpuszczalną **cyklazę guanylanową** powyżej tego samego szlaku. Bozentan i ambrisentan blokują receptory **endotelinowe**, a **iloprost** jest analogiem prostacykliny.$E$,
   'Nadciśnienie płucne', 'FARLEK-e2026-1-1807', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(136, 'FARM-16',
   'Działaniem niepożądanym glikokortykosteroidów przy długotrwałym stosowaniu NIE jest:',
   '[{"id": "a", "text": "Zespół Cushinga jatrogenny"}, {"id": "b", "text": "Osteoporoza"}, {"id": "c", "text": "Hiperglikemia"}, {"id": "d", "text": "Nadczynność tarczycy"}, {"id": "e", "text": "Zwiększona podatność na infekcje"}]'::jsonb,
   'd',
   $E$Przewlekła steroidoterapia daje obraz **jatrogennego zespołu Cushinga**: otyłość centralną, twarz księżycowatą, rozstępy, **osteoporozę** z nasiloną resorpcją kości, **hiperglikemię** przez glukoneogenezę i insulinooporność oraz **immunosupresję** ze skłonnością do zakażeń. Glikokortykosteroidy nie pobudzają tarczycy — przeciwnie, hamują wydzielanie **TSH** i konwersję **T4 do T3**, obniżając stężenie T3. Nagłe odstawienie grozi **przełomem nadnerczowym**.$E$,
   'Glikokortykosteroidy', 'FARLEK-e2026-1-1808', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(137, 'FARM-06',
   'Wskaż lek stosowany w nadciśnieniu, który działa poprzez agonizm receptorów imidazolowych I1 w rdzeniu przedłużonym:',
   '[{"id": "a", "text": "Klonidyna"}, {"id": "b", "text": "Moksonidyna"}, {"id": "c", "text": "Metyldopa"}, {"id": "d", "text": "Urapidyl"}, {"id": "e", "text": "Guanfacyna"}]'::jsonb,
   'b',
   $E$**Moksonidyna** wybiórczo pobudza receptory **imidazolowe I1** w brzuszno-bocznej części rdzenia przedłużonego, zmniejszając napływ impulsacji **współczulnej** do naczyń i serca. Dzięki znikomemu powinowactwu do receptorów **alfa2** powoduje mniejszą sedację i suchość w ustach niż **klonidyna**, która działa głównie alfa2-adrenergicznie i grozi **nadciśnieniem z odbicia**. Metyldopa to fałszywy neuroprzekaźnik stosowany w ciąży, a **urapidyl** blokuje receptory alfa1.$E$,
   'Leki hipotensyjne o działaniu ośrodkowym', 'FARLEK-e2026-1-1809', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(138, 'FARM-15',
   'Najsilniejsze działanie przeciwwymiotne w leczeniu choroby lokomocyjnej wykazuje:',
   '[{"id": "a", "text": "Prometazyna"}, {"id": "b", "text": "Skopolamina"}, {"id": "c", "text": "Ondansetron"}, {"id": "d", "text": "Metoklopramid"}, {"id": "e", "text": "Ranitydyna"}]'::jsonb,
   'b',
   $E$**Skopolamina** blokuje receptory **muskarynowe M1** w jądrach przedsionkowych i w drodze przedsionkowo-móżdżkowej, przerywając przekazywanie bodźców wywołujących **kinetozę** — jest najskuteczniejszym lekiem w tym wskazaniu, podawanym w **plastrze zausznym** na kilka godzin przed podróżą. Prometazyna działa słabiej i mocno sedatywnie. **Ondansetron** i metoklopramid są bezużyteczne w chorobie lokomocyjnej, bo nie hamują pobudzenia przedsionkowego.$E$,
   'Leki przeciwwymiotne', 'FARLEK-e2026-1-1810', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(139, 'FARM-08',
   'Lek przeciwpsychotyczny częściowo agonistyczny w stosunku do receptorów D2 to:',
   '[{"id": "a", "text": "Olanzapina"}, {"id": "b", "text": "Arypiprazol"}, {"id": "c", "text": "Kwetiapina"}, {"id": "d", "text": "Risperidon"}, {"id": "e", "text": "Perazyna"}]'::jsonb,
   'b',
   $E$**Arypiprazol** jest **częściowym agonistą D2** oraz 5-HT1A i antagonistą 5-HT2A, dlatego nazywa się go **stabilizatorem układu dopaminergicznego**: tłumi nadmierną transmisję w szlaku mezolimbicznym, a podtrzymuje ją tam, gdzie dopaminy brakuje. Skutkuje to małym ryzykiem **hiperprolaktynemii** i niewielkim przyrostem masy ciała, ale częstą **akatyzją**. Pozostałe wymienione leki to czyści **antagoniści D2**. Podobnie działają kariprazyna i brekspiprazol.$E$,
   'Leki przeciwpsychotyczne', 'FARLEK-e2026-1-1811', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(140, 'FARM-14',
   'Wskaż lek przeciwgrzybiczy o mechanizmie polegającym na hamowaniu syntezy beta-(1,3)-glukanu w ścianie komórkowej grzybów:',
   '[{"id": "a", "text": "Amfoterycyna B"}, {"id": "b", "text": "Flukonazol"}, {"id": "c", "text": "Kaspofungina"}, {"id": "d", "text": "Terbinafina"}, {"id": "e", "text": "Gryzeofulwina"}]'::jsonb,
   'c',
   $E$**Kaspofungina** należy do **echinokandyn** i hamuje **syntazę beta-(1,3)-glukanu**, niszcząc ścianę komórkową grzyba — struktury nieobecnej u człowieka, stąd bardzo dobra tolerancja. Działa na **Candida** (także szczepy azolooporne) i **Aspergillus**, jest natomiast nieskuteczna wobec **Cryptococcus**; podaje się ją wyłącznie dożylnie. Amfoterycyna wiąże **ergosterol**, azole hamują **14-alfa-demetylazę**, terbinafina **skwalenoepoksydazę**, a gryzeofulwina blokuje mikrotubule.$E$,
   'Leki przeciwgrzybicze', 'FARLEK-e2026-1-1812', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(141, 'FARM-14',
   'Wskaż zdanie prawdziwe na temat jodochinololu:',
   '[{"id": "a", "text": "Wykazuje aktywność jedynie w tkankach w przypadku zakażenia Entamoeba histolytica"}, {"id": "b", "text": "Stosowany jest wraz z metronidazolem w celu leczenia bezobjawowej amebiozy"}, {"id": "c", "text": "Nie ma wpływu na funkcje tarczycy"}, {"id": "d", "text": "Należy zachować ostrożność podczas stosowania leku u osób z zaburzeniami funkcji tarczycy i neuropatią wzrokową"}, {"id": "e", "text": "Wszystkie odpowiedzi są prawidłowe"}]'::jsonb,
   'd',
   $E$Jodochinol to **halogenowana hydroksychinolina** zawierająca jod, dlatego zaburza wyniki badań czynności **tarczycy** i może nasilać jej dysfunkcję, a przy długotrwałym stosowaniu wiąże się z **neuropatią nerwu wzrokowego** oraz podostrą mielopatią. Jest amebicydem **kontaktowym** — działa wyłącznie w **świetle jelita**, nie w tkankach, i w postaci bezobjawowej stosuje się go w monoterapii. Z **metronidazolem** kojarzy się go dopiero w pełzakowicy inwazyjnej.$E$,
   'Leki przeciwpierwotniakowe', 'FARLEK-e2026-1-1813', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(142, 'FARM-09',
   'Do leków znieczulających miejscowo o budowie amidowej należy:',
   '[{"id": "a", "text": "Prokaina"}, {"id": "b", "text": "Proksymetakaina"}, {"id": "c", "text": "Oksybuprokaina"}, {"id": "d", "text": "Bupiwakaina"}, {"id": "e", "text": "Wszystkie odpowiedzi prawidłowe"}]'::jsonb,
   'd',
   $E$**Bupiwakaina** to **amid**, podobnie jak lidokaina, ropiwakaina, mepiwakaina i artykaina — grupa ta jest metabolizowana w **wątrobie** przez cytochrom P450, działa długo i rzadko uczula. Prokaina, proksymetakaina i oksybuprokaina to **estry**, rozkładane przez **esterazy osoczowe** do **PABA**, co odpowiada za reakcje alergiczne. Bupiwakaina jest najbardziej **kardiotoksyczna** z całej grupy.
Mnemonik: nazwy amidów zawierają dwie litery **i** przed końcówką -kaina.$E$,
   'Leki znieczulające miejscowo', 'FARLEK-e2026-1-1814', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(143, 'FARM-03',
   'Lekiem opioidowym o działaniu agonistyczno-antagonistycznym nie jest:',
   '[{"id": "a", "text": "Naltrekson"}, {"id": "b", "text": "Metadon"}, {"id": "c", "text": "Pentazocyna"}, {"id": "d", "text": "Buprenorfina"}, {"id": "e", "text": "Prawidłowo odpowiedź A i B"}]'::jsonb,
   'e',
   $E$**Naltrekson** to **czysty antagonista** receptorów opioidowych, stosowany doustnie w uzależnieniu od alkoholu i opioidów, a **metadon** — **czysty agonista mi** o długim półtrwaniu, wykorzystywany w leczeniu substytucyjnym (uwaga: wydłuża **QT**). Działanie mieszane mają natomiast **pentazocyna** (agonista **kappa**, antagonista mi) i **buprenorfina** (**częściowy agonista mi** o bardzo silnym powinowactwie), która wykazuje efekt pułapowy i może wywołać zespół abstynencyjny.$E$,
   'Opioidy', 'FARLEK-e2026-1-1815', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(144, 'FARM-09',
   'Antagonistą receptorów glutaminowych typu NMDA jest:',
   '[{"id": "a", "text": "Morfina"}, {"id": "b", "text": "Metadon"}, {"id": "c", "text": "Etomidat"}, {"id": "d", "text": "Tiopental"}, {"id": "e", "text": "Ketamina"}]'::jsonb,
   'e',
   $E$**Ketamina** jest **niekompetycyjnym antagonistą** receptora **NMDA** — blokuje kanał jonowy od wewnątrz, wywołując **znieczulenie dysocjacyjne** z zachowanymi odruchami obronnymi i własnym oddechem oraz silną **analgezją**. Pobudzenie współczulne podnosi ciśnienie i tętno, co czyni ją cenną we wstrząsie, ale niekorzystną w chorobie wieńcowej. Powoduje objawy **wybudzeniowe** (halucynacje), którym zapobiega się benzodiazepinami. Metadon dodatkowo słabo blokuje NMDA.$E$,
   'Anestetyki dożylne', 'FARLEK-e2026-1-1816', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(145, 'FARM-08',
   'Pochodną amfetaminy, która może być stosowana u dzieci w terapii zespołu nadpobudliwości psychoruchowej z deficytem uwagi jest:',
   '[{"id": "a", "text": "Metylenodioksymetamfetamina"}, {"id": "b", "text": "Pegwisomant"}, {"id": "c", "text": "Metylfenidat"}, {"id": "d", "text": "Oktreotyd"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'c',
   $E$**Metylfenidat** hamuje transportery **DAT** i **NET**, zwiększając stężenie **dopaminy** i **noradrenaliny** w korze przedczołowej, co poprawia koncentrację i kontrolę impulsów — jest lekiem pierwszego rzutu w **ADHD** u dzieci powyżej 6 roku życia oraz w narkolepsji. Działania niepożądane: brak łaknienia, bezsenność, tiki, wzrost ciśnienia, spowolnienie wzrastania. **MDMA** to substancja odurzająca, **pegwisomant** i **oktreotyd** służą w akromegalii.$E$,
   'Psychostymulanty i ADHD', 'FARLEK-e2026-1-1817', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(146, 'FARM-18',
   'Błękit metylenowy może być stosowany w zatruciach:',
   '[{"id": "a", "text": "Cyjankami"}, {"id": "b", "text": "Metadonem"}, {"id": "c", "text": "Benzodiazepinami"}, {"id": "d", "text": "Niedepolaryzującymi środkami zwiotczającymi"}, {"id": "e", "text": "Prowadzących do methemoglobinemii"}]'::jsonb,
   'e',
   $E$**Błękit metylenowy** jest kofaktorem **reduktazy methemoglobinowej zależnej od NADPH**: przyspiesza redukcję żelaza **Fe3+ do Fe2+** w hemoglobinie, przywracając jej zdolność wiązania tlenu. Podaje się go dożylnie w dawce **1-2 mg/kg** przy methemoglobinemii po azotanach, sulfonamidach czy prylokainie. Jest nieskuteczny i groźny (hemoliza) przy niedoborze **G6PD**. W zatruciu cyjankami stosuje się hydroksykobalaminę, a przy benzodiazepinach — **flumazenil**.$E$,
   'Odtrutki', 'FARLEK-e2026-1-1818', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(147, 'FARM-11',
   'Amid kwasu nikotynowego może być stosowany w leczeniu:',
   '[{"id": "a", "text": "Pelagry"}, {"id": "b", "text": "Liszaja skóry"}, {"id": "c", "text": "Chorób naczyń obwodowych"}, {"id": "d", "text": "Neuralgii nerwu trójdzielnego"}, {"id": "e", "text": "Wszystkie prawidłowe"}]'::jsonb,
   'e',
   $E$Amid kwasu nikotynowego (**witamina PP**) jest prekursorem koenzymów **NAD i NADP**, niezbędnych w reakcjach oksydoredukcyjnych. Podstawowym wskazaniem jest **pelagra** z klasyczną triadą **3xD**: zapalenie skóry, biegunka i otępienie. Podręcznikowe zestawienia wymieniają ponadto zmiany skórne typu liszaja, choroby naczyń obwodowych oraz neuralgię nerwu trójdzielnego. W odróżnieniu od **kwasu nikotynowego** amid nie wywołuje **flushu** ani nie obniża lipidów.$E$,
   'Witaminy z grupy B', 'FARLEK-e2026-1-1819', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(148, 'FARM-05',
   'Inhibitorem receptora trombinowego PAR-1, który przeciwwskazany jest u osób z dodatnim wywiadem w kierunku udaru mózgu jest:',
   '[{"id": "a", "text": "Epoprostenol"}, {"id": "b", "text": "Pegwisomant"}, {"id": "c", "text": "Worapaksar"}, {"id": "d", "text": "Dipirydamol"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'c',
   $E$**Worapaksar** blokuje płytkowy receptor **PAR-1** aktywowany przez **trombinę**, hamując najsilniejszą fizjologiczną drogę agregacji. Dodaje się go do kwasu acetylosalicylowego lub klopidogrelu w prewencji wtórnej po zawale i w miażdżycy tętnic obwodowych. Jest bezwzględnie przeciwwskazany po **udarze, TIA lub krwawieniu wewnątrzczaszkowym** — w badaniu TRACER wyraźnie zwiększał ryzyko krwotoku śródczaszkowego. Działa bardzo długo i nieodwracalnie.$E$,
   'Leki przeciwpłytkowe', 'FARLEK-e2026-1-1820', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(149, 'FARM-10',
   'Entakapon jest inhibitorem:',
   '[{"id": "a", "text": "Monoaminooksydazy A"}, {"id": "b", "text": "Monoaminooksydazy B"}, {"id": "c", "text": "Dekarboksylazy DOPA"}, {"id": "d", "text": "Katecholotlenometylotransferazy"}, {"id": "e", "text": "Hydroksylazy tyrozynowej"}]'::jsonb,
   'd',
   $E$**Entakapon** hamuje **COMT** (katecholo-O-metylotransferazę) wyłącznie **na obwodzie**, blokując przemianę lewodopy w nieczynną **3-O-metylodopę**. Dzięki temu wydłuża okres półtrwania lewodopy i zmniejsza fluktuacje typu **wearing-off**; podaje się go zawsze razem z lewodopą i inhibitorem dekarboksylazy. **Tolkapon** działa też ośrodkowo, ale jest **hepatotoksyczny**. Karbidopa i benserazyd hamują dekarboksylazę, a selegilina i rasagilina — **MAO-B**. Mocz barwi się pomarańczowo.$E$,
   'Choroba Parkinsona', 'FARLEK-e2026-1-1821', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(150, 'FARM-05',
   'Antagonistą receptora CXCR4, który jest stosowany do mobilizacji macierzystych komórek układu krwiotwórczego jest:',
   '[{"id": "a", "text": "Oprelwekina"}, {"id": "b", "text": "Romiplostym"}, {"id": "c", "text": "Pleryksafor"}, {"id": "d", "text": "Filgrastym"}, {"id": "e", "text": "Roksadustat"}]'::jsonb,
   'c',
   $E$**Pleryksafor** blokuje receptor **CXCR4** na komórkach **CD34+**, przerywając ich wiązanie ze **SDF-1 (CXCL12)** wytwarzanym przez podścielisko szpiku. Komórki macierzyste zostają uwolnione do krwi obwodowej i można je pobrać do **autoprzeszczepienia** u chorych na szpiczaka i chłoniaki — zwykle w skojarzeniu z **G-CSF**. **Filgrastym** to właśnie G-CSF, **romiplostym** pobudza receptor trombopoetyny, a **roksadustat** hamuje hydroksylazę prolilową, aktywując HIF.$E$,
   'Czynniki wzrostu układu krwiotwórczego', 'FARLEK-e2026-1-1822', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(151, 'FARM-06',
   'Wskaż zestaw leków powodujących retencję potasu:',
   '[{"id": "a", "text": "Peryndopryl, torasemid, spironolakton"}, {"id": "b", "text": "Spironolakton, ibuprofen, indapamid"}, {"id": "c", "text": "Hydrochlorotiazyd, Indapamid, Furosemid"}, {"id": "d", "text": "Walsartan, Peryndopryl, Eplerenon"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'd',
   $E$Wszystkie trzy leki z zestawu D osłabiają działanie **aldosteronu**: **peryndopryl** hamuje konwertazę, **walsartan** blokuje receptor **AT1**, a **eplerenon** jest antagonistą receptora **mineralokortykoidowego**. Skutkiem jest zmniejszone wydzielanie potasu w cewce zbiorczej i **hiperkaliemia** — łączenie ich wymaga kontroli kaliemii i kreatyniny. Pozostałe zestawy zawierają diuretyki **kaliuretyczne**: pętlowe (furosemid, torasemid) oraz tiazydowe i tiazydopodobne.$E$,
   'Leki moczopędne i gospodarka potasowa', 'FARLEK-e2026-1-1823', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(152, 'FARM-06',
   'Wskaż zestaw leków przeciwnadciśnieniowych, które można zastosować u kobiety 33-letniej z rozpoznanym nadciśnieniem I stopnia planującej ciążę w ciągu najbliższych 6 miesięcy:',
   '[{"id": "a", "text": "Metyldopa lub walsartan"}, {"id": "b", "text": "Metyldopa lub ramipryl"}, {"id": "c", "text": "Ramipryl lub walsartan"}, {"id": "d", "text": "Metyldopa w monoterapii"}, {"id": "e", "text": "Każdy z wymienionych leków można zastosować w powyższej sytuacji"}]'::jsonb,
   'd',
   $E$**Metyldopa** — ośrodkowy agonista **alfa2** działający jako fałszywy neuroprzekaźnik — ma najdłuższą historię bezpiecznego stosowania w ciąży i jest lekiem z wyboru. **Ramipryl** (ACEI) i **walsartan** (sartan) są w ciąży **bezwzględnie przeciwwskazane**: blokada układu RAA płodu powoduje małowodzie, hipoplazję czaszki, przykurcze i niewydolność nerek noworodka. U kobiety planującej ciążę odstawia się je z wyprzedzeniem. Alternatywami są labetalol i nifedypina.$E$,
   'Nadciśnienie tętnicze w ciąży', 'FARLEK-e2026-1-1824', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(153, 'FARM-06',
   'Wskaż zestaw leków, których jednoczesne stosowanie jest przeciwwskazane: 1. Ramipryl + bisoprolol 2. Nebiwolol + hydrochlorotiazyd 3. Ramipryl + walsartan 4. Spironolakton + eplerenon 5. Spironolakton + hydrochlorotiazyd 6. Nebiwolol + walsartan',
   '[{"id": "a", "text": "2,3,4"}, {"id": "b", "text": "2,5"}, {"id": "c", "text": "1,2,3"}, {"id": "d", "text": "3,4"}, {"id": "e", "text": "3,4,5"}]'::jsonb,
   'd',
   $E$Połączenie **ACEI z sartanem** (para 3) to podwójna blokada układu RAA — badanie ONTARGET wykazało brak korzyści przy istotnym wzroście ryzyka **hiperkaliemii**, hipotonii i pogorszenia funkcji nerek. Para 4 to zestawienie **dwóch antagonistów aldosteronu** o identycznym mechanizmie, co jedynie potęguje hiperkaliemię. Pozostałe skojarzenia są dopuszczalne, a spironolakton z tiazydem bywa wręcz korzystny, bo wzajemnie znoszą wpływ na **kaliemię**.$E$,
   'Skojarzenia leków hipotensyjnych', 'FARLEK-e2026-1-1825', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(154, 'FARM-16',
   'Wskaż zestaw leków łagodzących objawy łagodnego przerostu prostaty:',
   '[{"id": "a", "text": "Finasteryd + Testosteron"}, {"id": "b", "text": "Testosteron + Wazopresyna"}, {"id": "c", "text": "Doksazosyna + Wazopresyna"}, {"id": "d", "text": "Doksazosyna + Finasteryd"}, {"id": "e", "text": "Finasteryd + Wazopresyna"}]'::jsonb,
   'd',
   $E$**Doksazosyna** blokuje receptory **alfa1** w szyi pęcherza i zrębie gruczołu, dając rozkurcz i poprawę przepływu już po kilku dniach — uwaga na **hipotonię ortostatyczną** oraz zespół wiotkiej tęczówki podczas operacji zaćmy. **Finasteryd** hamuje **5-alfa-reduktazę typu 2**, zmniejszając stężenie **DHT** i objętość gruczołu po 3-6 miesiącach; obniża też **PSA** o około połowę. **Testosteron** jest w przeroście prostaty przeciwwskazany.$E$,
   'Łagodny rozrost prostaty', 'FARLEK-e2026-1-1826', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(155, 'FARM-06',
   'Wskaż zestaw leków stosowanych w leczeniu nadciśnienia płucnego:',
   '[{"id": "a", "text": "Sildenafil + Testosteron + Finasteryd"}, {"id": "b", "text": "Sildenafil + Bozentan + Epoprostenol"}, {"id": "c", "text": "Bozentan + Ezetymib + Eptyfibatyd"}, {"id": "d", "text": "Walsartan + Sakubitryl + Epoprostenol"}, {"id": "e", "text": "Walsartan + Finasteryd + Epoprostenol"}]'::jsonb,
   'b',
   $E$Zestaw B obejmuje trzy filary leczenia **tętniczego nadciśnienia płucnego**: **sildenafil** (inhibitor **PDE5**, podnosi cGMP), **bozentan** (antagonista receptorów **endotelinowych** ETA i ETB) oraz **epoprostenol** (analog **prostacykliny** podawany w ciągłym wlewie dożylnym przez cewnik centralny, bo jego okres półtrwania wynosi kilka minut). Ezetymib jest lekiem hipolipemizującym, **eptyfibatyd** blokuje płytkowy receptor GP IIb/IIIa, a sakubitryl hamuje neprylizynę.$E$,
   'Nadciśnienie płucne', 'FARLEK-e2026-1-1827', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(156, 'FARM-06',
   'Wskaż zdanie opisujące prawidłową terapię przeciwnadciśnieniową:',
   '[{"id": "a", "text": "W pierwszym rzucie zawsze powinien być stosowany lek działający na ośrodkowe mechanizmy regulacji, np. klonidyna"}, {"id": "b", "text": "Stosowanie diuretyku oszczędzającego potas należy rozważyć jako dodatek do inhibitora konwertazy angiotensyny w celu uzyskania lepszego efektu hipotensyjnego"}, {"id": "c", "text": "Połączenie diuretyku tiazydopodobnego oraz inhibitora konwertazy angiotensyny nie powinno być stosowane z uwagi na ryzyko ciężkiej hipokaliemii"}, {"id": "d", "text": "Połączenie diuretyku tiazydopodobnego oraz dihydropirydynowego blokera kanału wapniowego jest dopuszczalne"}, {"id": "e", "text": "W pierwszej kolejności powinny być stosowane leki działające na układ współczulny, np. poprzez połączenie alfa-blokera z beta-blokerem"}]'::jsonb,
   'd',
   $E$Diuretyk tiazydopodobny z **dihydropirydynowym antagonistą wapnia** to jedno z zalecanych skojarzeń podstawowych. Leki działające ośrodkowo (**klonidyna**) i alfa-blokery należą do **kolejnych rzutów** ze względu na sedację, nadciśnienie z odbicia i hipotonię ortostatyczną. Dodanie diuretyku oszczędzającego potas do **ACEI** grozi **hiperkaliemią**, a połączenie tiazydu z ACEI jest wręcz korzystne — inhibitor konwertazy **ogranicza** utratę potasu.$E$,
   'Zasady terapii hipotensyjnej', 'FARLEK-e2026-1-1828', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(157, 'FARM-06',
   'Stosowanie którego leku przeciwnadciśnieniowego jest niewskazane u pacjenta z przewlekłą hiperurykemią?',
   '[{"id": "a", "text": "Bisoprolol"}, {"id": "b", "text": "Nebiwolol"}, {"id": "c", "text": "Indapamid"}, {"id": "d", "text": "Walsartan"}, {"id": "e", "text": "Amlodypina"}]'::jsonb,
   'c',
   $E$**Indapamid**, jak wszystkie diuretyki tiazydowe i tiazydopodobne, konkuruje z **kwasem moczowym** o transportery anionów organicznych w cewce bliższej i dodatkowo, przez odwodnienie, nasila jego reabsorpcję. Efektem jest **hiperurykemia** i ryzyko wywołania napadu **dny**. Amlodypina i beta-blokery są pod tym względem obojętne, a wśród sartanów **losartan** wykazuje wręcz działanie **urykozuryczne** przez hamowanie URAT1 — jest więc korzystny u chorych z dną.$E$,
   'Leki moczopędne', 'FARLEK-e2026-1-1829', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(158, 'FARM-13',
   'Przyporządkuj nazwę leku przeciwdrobnoustrojowego do odpowiedniej grupy. a. klindamycyna b. ceftriakson c. klarytromycyna d. klotrimazol 1. cefalosporyny 2. grupa linkozamidów 3. makrolidy 4. azole',
   '[{"id": "a", "text": "a2, b3, a1, d4"}, {"id": "b", "text": "a3, b1, c2, d4"}, {"id": "c", "text": "a4, b1, c2, d3"}, {"id": "d", "text": "a2, b1, c3, d4"}, {"id": "e", "text": "a4, b1, c3, d2"}]'::jsonb,
   'd',
   $E$**Klindamycyna** to **linkozamid** blokujący podjednostkę **50S**, o dobrej penetracji do kości, ale obarczony największym ryzykiem rzekomobłoniastego zapalenia jelit (**C. difficile**). **Ceftriakson** jest **cefalosporyną III generacji** wydalaną głównie z żółcią (ryzyko pseudokamicy). **Klarytromycyna** to **makrolid**, również działający na 50S i silnie hamujący **CYP3A4**. **Klotrimazol** to **azol** przeciwgrzybiczy, hamujący 14-alfa-demetylazę, stosowany miejscowo.$E$,
   'Klasyfikacja antybiotyków', 'FARLEK-e2026-1-1830', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(159, 'FARM-02',
   'Antagonistą receptorów histaminowych H3, stosowanym w leczeniu zawrotów głowy i szumów usznych w przebiegu choroby Meniere''a jest:',
   '[{"id": "a", "text": "Bilastyna"}, {"id": "b", "text": "Busulfan"}, {"id": "c", "text": "Bencyklan"}, {"id": "d", "text": "Betahistyna"}, {"id": "e", "text": "Bisoprolol"}]'::jsonb,
   'd',
   $E$**Betahistyna** jest analogiem histaminy: słabym **agonistą H1** i silnym **antagonistą presynaptycznych H3**. Blokada H3 znosi hamowanie zwrotne i zwiększa uwalnianie histaminy, co rozszerza naczynia **prążka naczyniowego** ucha wewnętrznego, poprawia mikrokrążenie i obniża ciśnienie **endolimfy** w wodniaku błędnika. Przeciwwskazana jest w guzie chromochłonnym, a ostrożności wymaga w astmie i chorobie wrzodowej. **Bilastyna** to lek przeciwhistaminowy II generacji.$E$,
   'Histamina i leki histaminergiczne', 'FARLEK-e2026-1-1831', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(160, 'FARM-07',
   'Do wskazań, w których są stosowane beta-blokery, należy:',
   '[{"id": "a", "text": "Nadciśnienie tętnicze"}, {"id": "b", "text": "Choroba niedokrwienna serca"}, {"id": "c", "text": "Przewlekła niewydolność serca"}, {"id": "d", "text": "Prawidłowe A i B"}, {"id": "e", "text": "Prawidłowe A, B i C"}]'::jsonb,
   'e',
   $E$Beta-blokery obniżają ciśnienie (spadek pojemności minutowej i wydzielania **reniny**), zmniejszają zapotrzebowanie mięśnia sercowego na tlen w **chorobie niedokrwiennej** oraz — wbrew dawnym obawom — istotnie **redukują śmiertelność w przewlekłej niewydolności serca** z obniżoną frakcją wyrzutową. Udowodniono to dla **bisoprololu, karwedilolu, metoprololu o przedłużonym uwalnianiu i nebiwololu**; w HF włącza się je u stabilnego chorego, od małych dawek stopniowo zwiększanych.$E$,
   'Beta-blokery', 'FARLEK-e2026-1-1832', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(161, 'FARM-19',
   'Lek będący dawcą grup -SH ograniczających działanie toksycznych wolnych rodników, podawany w zapobieganiu zapaleniu błony śluzowej jamy ustnej i uszkodzeniu ślinianek przy radioterapii nowotworów głowy i szyi, a także w celu ochrony nerek w czasie terapii cisplatyną to:',
   '[{"id": "a", "text": "Amifostyna"}, {"id": "b", "text": "Palifermina"}, {"id": "c", "text": "Metronidazol"}, {"id": "d", "text": "N-acetylocysteina"}, {"id": "e", "text": "Deksametazon"}]'::jsonb,
   'a',
   $E$**Amifostyna** jest prolekiem: w tkankach prawidłowych **fosfataza alkaliczna** odszczepia grupę fosforanową, uwalniając wolny **tiol (WR-1065)**, który zmiata wolne rodniki i wiąże reaktywne metabolity platyny. Selektywność wynika z niskiej aktywności fosfatazy i kwaśnego pH w guzie. Wskazania to **kserostomia** po radioterapii głowy i szyi oraz **nefroprotekcja** przy cisplatynie. Ogranicza ją hipotensja i wymioty. **Palifermina** działa inaczej — jest czynnikiem wzrostu keratynocytów.$E$,
   'Leki osłaniające w chemioterapii', 'FARLEK-e2026-1-1833', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(162, 'FARM-10',
   'Celem stosowania apomorfiny w chorobie Parkinsona jest:',
   '[{"id": "a", "text": "Zniesienie działań niepożądanych lewodopy związanych z jej metabolizmem na obwodzie"}, {"id": "b", "text": "Zniesienie sztywności mięśniowej"}, {"id": "c", "text": "Zniesienie drżenia spoczynkowego"}, {"id": "d", "text": "Zniesienie objawów hipokinezy"}, {"id": "e", "text": "Zapobieganie wystąpieniu zjawiska on-off związanego ze zmianami wrażliwości komórek na lewodopę"}]'::jsonb,
   'd',
   $E$**Apomorfina** to silny agonista receptorów **D1 i D2**, podawany **podskórnie** we wstrzyknięciach lub wlewie ciągłym. Działa już po 5-10 minutach, dlatego stosuje się ją **ratunkowo** w nagłych epizodach **off** z ciężką **hipokinezą i akinezją**, w tym w akinezji porannej. Nie zapobiega jednak fluktuacjom ani nie modyfikuje metabolizmu lewodopy. Jest silnie **emetogenna** — wymaga osłony domperydonem. Mimo nazwy nie wykazuje działania opioidowego.$E$,
   'Choroba Parkinsona', 'FARLEK-e2026-1-1834', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(163, 'FARM-13',
   'Dlaczego łączenie aminoglikozydów z furosemidem jest ryzykowne?',
   '[{"id": "a", "text": "Furosemid zwiększa biodostępność aminoglikozydów"}, {"id": "b", "text": "Nasilają się działania ototoksyczne i nefrotoksyczne obu leków"}, {"id": "c", "text": "Aminoglikozydy blokują metabolizm furosemidu"}, {"id": "d", "text": "Oba leki zmniejszają poziom sodu we krwi"}, {"id": "e", "text": "Brak prawidłowej odpowiedzi"}]'::jsonb,
   'b',
   $E$**Aminoglikozydy** kumulują się w komórkach rzęsatych ucha wewnętrznego i w nabłonku cewek bliższych, powodując **ototoksyczność** (nieodwracalną, także przedsionkową) oraz **nefrotoksyczność**. **Furosemid** samodzielnie uszkadza prążek naczyniowy ucha, a dodatkowo, wywołując hipowolemię, zwiększa stężenie aminoglikozydu w surowicy. Efekty sumują się. Stąd zaleca się kontrolę stężeń leku i kreatyniny oraz dawkowanie **raz na dobę**, mniej toksyczne dla nerek.$E$,
   'Aminoglikozydy', 'FARLEK-e2026-1-1835', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(164, 'FARM-17',
   'Kwasica mleczanowa jest rzadkim, ale potencjalnie groźnym działaniem niepożądanym:',
   '[{"id": "a", "text": "Biguanidów"}, {"id": "b", "text": "Flozyn"}, {"id": "c", "text": "Pochodnych sulfonylomocznika"}, {"id": "d", "text": "Inhibitorów peptydazy dipeptydylowej 4"}, {"id": "e", "text": "Agonistów receptora peptydu glukagonopodobnego typu 1"}]'::jsonb,
   'a',
   $E$**Metformina** hamuje glukoneogenezę wątrobową oraz **kompleks I** łańcucha oddechowego, przesuwając metabolizm w stronę glikolizy beztlenowej i produkcji **mleczanu**. Kwasica mleczanowa grozi przy kumulacji leku: **eGFR poniżej 30**, niewydolności wątroby i serca, sepsie, odwodnieniu i po podaniu **kontrastu jodowego** (odstawienie na 48 godzin). Sulfonylomoczniki grożą przede wszystkim hipoglikemią, a flozyny — **euglikemiczną kwasicą ketonową**.$E$,
   'Leki przeciwcukrzycowe', 'FARLEK-e2026-1-1836', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(165, 'FARM-17',
   'Lekiem zaliczanym do grupy podwójnych agonistów receptora GIP (żołądkowy peptyd hamujący) i GLP-1, stosowanym w leczeniu cukrzycy typu 2 i otyłości, jest:',
   '[{"id": "a", "text": "Metformina"}, {"id": "b", "text": "Empagliflozyna"}, {"id": "c", "text": "Pioglitazon"}, {"id": "d", "text": "Tirzepatyd"}, {"id": "e", "text": "Gliklazyd"}]'::jsonb,
   'd',
   $E$**Tirzepatyd** jednocześnie pobudza receptory **GIP** i **GLP-1**, nasilając zależne od glukozy wydzielanie **insuliny**, hamując glukagon i opóźniając opróżnianie żołądka oraz silnie zmniejszając łaknienie. Podawany podskórnie **raz w tygodniu** obniża HbA1c i masę ciała skuteczniej niż sami agoniści GLP-1. Dominują działania żołądkowo-jelitowe: nudności, wymioty, biegunka. Przeciwwskazaniem jest rdzeniasty rak tarczycy i **zespół MEN2** w wywiadzie rodzinnym.$E$,
   'Leki inkretynowe', 'FARLEK-e2026-1-1837', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(166, 'FARM-13',
   'Zespół Hoigne jest powikłaniem mogącym wystąpić podczas stosowania:',
   '[{"id": "a", "text": "Metronidazolu"}, {"id": "b", "text": "Benzylopenicyliny prokainowej"}, {"id": "c", "text": "Benzylopenicyliny benzatynowej"}, {"id": "d", "text": "Wankomycyny"}, {"id": "e", "text": "Doksycykliny"}]'::jsonb,
   'b',
   $E$Zespół Hoigné pojawia się po przypadkowym **donaczyniowym** podaniu **penicyliny prokainowej**: mikrokryształki zawiesiny wywołują mikrozatory, a uwolniona **prokaina** działa neurotoksycznie. Chory nagle odczuwa silny lęk i **poczucie zbliżającej się śmierci**, ma omamy wzrokowe i słuchowe, tachykardię i wzrost ciśnienia. Kluczowe jest odróżnienie od **wstrząsu anafilaktycznego** — nie ma tu pokrzywki ani spadku ciśnienia, a objawy mijają w kilkadziesiąt minut.$E$,
   'Penicyliny', 'FARLEK-e2026-1-1838', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(167, 'FARM-01',
   'Antybiotyki aminoglikozydowe i beta-laktamowe niejednokrotnie bywają stosowane w skojarzonym leczeniu niektórych infekcji. Takie połączenie jest racjonalne, ponieważ antybiotyki beta-laktamowe mogą poprawiać penetrację aminoglikozydów do ich miejsca działania w komórce bakteryjnej. Opisana sytuacja jest przykładem:',
   '[{"id": "a", "text": "Interakcji farmaceutycznej"}, {"id": "b", "text": "Interakcji farmakokinetycznej"}, {"id": "c", "text": "Interakcji farmakodynamicznej"}, {"id": "d", "text": "Opisana sytuacja w ogóle nie stanowi przykładu interakcji"}, {"id": "e", "text": "Prawidłowe A i C"}]'::jsonb,
   'c',
   $E$To klasyczny **synergizm hiperaddycyjny**, czyli interakcja **farmakodynamiczna**: beta-laktam uszkadza ścianę komórkową bakterii, ułatwiając aminoglikozydowi dotarcie do **podjednostki 30S** rybosomu. Interakcja **farmakokinetyczna** dotyczyłaby wchłaniania, dystrybucji, metabolizmu lub wydalania w organizmie chorego, a **farmaceutyczna** — niezgodności poza ustrojem. Uwaga praktyczna: obu antybiotyków nie wolno mieszać w jednej strzykawce, bo beta-laktam inaktywuje aminoglikozyd.$E$,
   'Rodzaje interakcji', 'FARLEK-e2026-1-1839', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(168, 'FARM-02',
   'Zaznacz zdanie fałszywe:',
   '[{"id": "a", "text": "Cyproheptadyna jest antagonistą receptorów 5-HT2"}, {"id": "b", "text": "Buspiron, sumatryptan i flibanseryna są agonistami receptorów 5-HT1"}, {"id": "c", "text": "Ondansetron jest antagonistą receptorów 5-HT3"}, {"id": "d", "text": "W wyniku blokowania receptorów 5-HT4, cyzapryd wzmaga motorykę przewodu pokarmowego"}, {"id": "e", "text": "Brak zdania fałszywego, wszystkie zdania są prawdziwe"}]'::jsonb,
   'd',
   $E$Cyzapryd jest **agonistą**, a nie antagonistą receptorów **5-HT4**: ich pobudzenie w splocie Auerbacha zwiększa uwalnianie **acetylocholiny** i przyspiesza pasaż jelitowy. Lek wycofano z powodu blokady kanału **hERG** i **torsade de pointes**. Pozostałe zdania są prawdziwe: **cyproheptadyna** blokuje 5-HT2 (odtrutka w zespole serotoninowym), **ondansetron** — 5-HT3, a buspiron i flibanseryna pobudzają **5-HT1A**, natomiast sumatryptan 5-HT1B/1D.$E$,
   'Serotonina i receptory 5-HT', 'FARLEK-e2026-1-1840', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(169, 'FARM-13',
   'Mechanizmem oporności na sulfonamidy jest:',
   '[{"id": "a", "text": "Nadprodukcja kwasu dihydrofoliowego"}, {"id": "b", "text": "Mutacja syntetazy dihydrofolianowej"}, {"id": "c", "text": "Zmniejszenie przepuszczalności błony bakteryjnej"}, {"id": "d", "text": "Odpowiedź A i B prawidłowa"}, {"id": "e", "text": "Odpowiedź A, B i C prawidłowa"}]'::jsonb,
   'c',
   $E$Sulfonamidy są strukturalnymi analogami **PABA** i kompetycyjnie hamują **syntazę dihydropteroinianową**, blokując syntezę kwasu foliowego u bakterii. Oporność powstaje przez zmniejszoną przepuszczalność błony i **aktywne usuwanie leku**, a ponadto przez nadprodukcję **PABA** (nie kwasu dihydrofoliowego, który jest produktem szlaku) oraz mutację **syntazy dihydropteroinianowej** — a nie dihydrofolianowej, będącej innym enzymem. Dlatego prawidłowy jest wyłącznie mechanizm zmniejszonej przepuszczalności błony.$E$,
   'Sulfonamidy i oporność bakterii', 'FARLEK-e2026-1-1841', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(170, 'FARM-13',
   'Inhibitorem gyrazy stosowanym w powikłanym zakażeniu układu moczowego jest:',
   '[{"id": "a", "text": "Norfloksacyna"}, {"id": "b", "text": "Lewofloksacyna"}, {"id": "c", "text": "Enoksacyna"}, {"id": "d", "text": "Cyprofloksacyna"}, {"id": "e", "text": "Wszystkie prawidłowe"}]'::jsonb,
   'd',
   $E$**Cyprofloksacyna** to fluorochinolon o najsilniejszym w grupie działaniu na pałeczki Gram-ujemne, w tym **Pseudomonas aeruginosa**, osiągający wysokie stężenia w moczu i miąższu nerki — dlatego jest lekiem z wyboru w **powikłanym ZUM** i odmiedniczkowym zapaleniu nerek. **Norfloksacyna** działa praktycznie tylko w drogach moczowych w zakażeniach niepowikłanych. Grupa hamuje **gyrazę (topoizomerazę II)** i topoizomerazę IV; uwaga na zerwanie ścięgna Achillesa i wydłużenie QT.$E$,
   'Fluorochinolony', 'FARLEK-e2026-1-1842', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(171, 'FARM-07',
   'Lekiem antyarytmicznym klasy Ic jest:',
   '[{"id": "a", "text": "Lidokaina"}, {"id": "b", "text": "Amiodaron"}, {"id": "c", "text": "Propafenon"}, {"id": "d", "text": "Chinidyna"}, {"id": "e", "text": "Sotalol"}]'::jsonb,
   'c',
   $E$**Propafenon** należy do klasy **Ic** wg Vaughana Williamsa: bardzo silnie blokuje kanały **sodowe**, wyraźnie zwalniając przewodzenie (poszerzenie **QRS**), bez wpływu na czas trwania potencjału czynnościowego. Stosuje się go jako „tabletkę podręczną” w napadowym migotaniu przedsionków, ale wyłącznie u chorych **bez organicznej choroby serca** — po zawale leki Ic zwiększają śmiertelność (badanie CAST). Lidokaina to Ib, chinidyna Ia, a sotalol i amiodaron — klasa III.$E$,
   'Leki antyarytmiczne', 'FARLEK-e2026-1-1843', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(172, 'FARM-06',
   'Do działań niepożądanych inhibitorów konwertazy angiotensyny (ACEI) należą:',
   '[{"id": "a", "text": "Hiperkaliemia i suchy kaszel"}, {"id": "b", "text": "Hipokaliemia i tachykardia"}, {"id": "c", "text": "Bradykardia i zaparcia"}, {"id": "d", "text": "Niedosłuch i parestezje"}, {"id": "e", "text": "Retinopatia i nadciśnienie"}]'::jsonb,
   'a',
   $E$Zahamowanie konwertazy zmniejsza wytwarzanie angiotensyny II i **aldosteronu**, co ogranicza wydzielanie potasu w cewce zbiorczej — stąd **hiperkaliemia**. Ten sam enzym (kininaza II) rozkłada **bradykininę**, więc jej kumulacja w drogach oddechowych wywołuje uporczywy **suchy kaszel** u 10-15% chorych, a rzadziej **obrzęk naczynioruchowy**. Przy kaszlu zamienia się ACEI na sartan. Leki te są przeciwwskazane w ciąży i w obustronnym zwężeniu tętnic nerkowych.$E$,
   'Inhibitory konwertazy angiotensyny', 'FARLEK-e2026-1-1844', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(173, 'FARM-10',
   'Lek stosowany w ostrym rzucie stwardnienia rozsianego w celu zahamowania procesu zapalnego to:',
   '[{"id": "a", "text": "Natalizumab"}, {"id": "b", "text": "Triamcynolon"}, {"id": "c", "text": "Ocrelizumab"}, {"id": "d", "text": "Interferon Beta-1a"}, {"id": "e", "text": "Glatiramer"}]'::jsonb,
   'b',
   $E$Ostry rzut stwardnienia rozsianego przerywa się **glikokortykosteroidami** w dużych dawkach, które hamują wytwarzanie cytokin prozapalnych i uszczelniają **barierę krew-mózg**, skracając czas trwania rzutu. Standardem jest **metyloprednizolon** dożylnie przez 3-5 dni, a spośród wymienionych leków jedynym glikokortykosteroidem jest **triamcynolon**. Natalizumab, okrelizumab, interferon beta-1a i glatiramer to leki **modyfikujące przebieg** choroby — nie działają doraźnie.$E$,
   'Stwardnienie rozsiane', 'FARLEK-e2026-1-1845', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(174, 'FARM-10',
   'Leki zwiększające stężenie dopaminy w OUN poprzez zahamowanie jej rozkładu przez monoaminooksydazę typu B (MAO-B) to:',
   '[{"id": "a", "text": "Entakapon i tolkapon"}, {"id": "b", "text": "Selegilina i rasagilina"}, {"id": "c", "text": "Amantadyna i apomorfina"}, {"id": "d", "text": "Bromokryptyna i ropinirol"}, {"id": "e", "text": "Karbidopa i benserazyd"}]'::jsonb,
   'b',
   $E$**Selegilina** i **rasagilina** to selektywne, nieodwracalne inhibitory **MAO-B** — izoformy dominującej w prążkowiu i odpowiadającej za rozkład **dopaminy**. Stosuje się je w monoterapii wczesnej choroby Parkinsona oraz jako dodatek pozwalający zmniejszyć dawkę lewodopy. W dużych dawkach tracą selektywność, grożąc **przełomem tyraminowym**. Selegilina jest metabolizowana do amfetaminy (bezsenność). Entakapon hamuje **COMT**, a karbidopa — dekarboksylazę obwodową.$E$,
   'Choroba Parkinsona', 'FARLEK-e2026-1-1846', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(175, 'FARM-05',
   'W leczeniu neutropenii po chemioterapii stosuje się:',
   '[{"id": "a", "text": "Filgrastym"}, {"id": "b", "text": "Eltrombopag"}, {"id": "c", "text": "Fostamatynib"}, {"id": "d", "text": "Erytropoetynę"}, {"id": "e", "text": "Darbepoetynę"}]'::jsonb,
   'a',
   $E$**Filgrastym** to rekombinowany **G-CSF**, który pobudza proliferację i dojrzewanie prekursorów granulocytów obojętnochłonnych oraz uwalnianie ich ze szpiku. Skraca czas trwania **neutropenii** po chemioterapii i zmniejsza ryzyko gorączki neutropenicznej; **pegfilgrastym** wymaga tylko jednego wstrzyknięcia na cykl. Typowe działania niepożądane to bóle kostne i, rzadko, pęknięcie śledziony. Eltrombopag i fostamatynib leczą małopłytkowość, a erytropoetyna — niedokrwistość.$E$,
   'Czynniki wzrostu układu krwiotwórczego', 'FARLEK-e2026-1-1847', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(176, 'FARM-04',
   'Lekiem pierwszego rzutu w anafilaksji jest:',
   '[{"id": "a", "text": "Dopamina"}, {"id": "b", "text": "Prednizon"}, {"id": "c", "text": "Hydrokortyzon"}, {"id": "d", "text": "Adrenalina"}, {"id": "e", "text": "Klemastyna"}]'::jsonb,
   'd',
   $E$**Adrenalinę** podaje się natychmiast **domięśniowo** w przednio-boczną powierzchnię uda, w dawce **0,3-0,5 mg** (0,01 mg/kg u dzieci), powtarzalnej co 5-15 minut. Działa na wszystkie kluczowe mechanizmy wstrząsu: przez **alfa1** obkurcza naczynia i cofa obrzęk, przez **beta1** zwiększa kurczliwość serca, a przez **beta2** rozszerza oskrzela i hamuje degranulację mastocytów. Glikokortykosteroidy i leki przeciwhistaminowe działają zbyt wolno — pozostają leczeniem wspomagającym.$E$,
   'Leki adrenergiczne', 'FARLEK-e2026-1-1848', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(177, 'FARM-13',
   'Zespół „Czerwonego człowieka” jest charakterystycznym działaniem niepożądanym:',
   '[{"id": "a", "text": "Gentamycyny"}, {"id": "b", "text": "Wankomycyny"}, {"id": "c", "text": "Linezolidu"}, {"id": "d", "text": "Daptomycyny"}, {"id": "e", "text": "Streptomycyny"}]'::jsonb,
   'b',
   $E$Zespół czerwonego człowieka występuje po **zbyt szybkim wlewie wankomycyny**: lek bezpośrednio degranuluje mastocyty, uwalniając **histaminę** bez udziału IgE. Pojawia się rumień twarzy, szyi i tułowia, świąd oraz spadek ciśnienia. To reakcja **rzekomoanafilaktyczna**, nie alergia — wystarczy wydłużyć wlew do co najmniej **60 minut** i zastosować premedykację lekiem przeciwhistaminowym, bez konieczności odstawienia antybiotyku. Wankomycyna jest też nefro- i ototoksyczna.$E$,
   'Glikopeptydy', 'FARLEK-e2026-1-1849', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(178, 'FARM-08',
   'Wskaż lek przeciwdepresyjny będący inhibitorem wychwytu zwrotnego serotoniny i noradrenaliny (SNRI):',
   '[{"id": "a", "text": "Sertralina"}, {"id": "b", "text": "Duloksetyna"}, {"id": "c", "text": "Moklobemid"}, {"id": "d", "text": "Mirtazapina"}, {"id": "e", "text": "Fluwoksamina"}]'::jsonb,
   'b',
   $E$**Duloksetyna** hamuje transportery **SERT i NET**, zwiększając przekaźnictwo serotoninergiczne i noradrenergiczne. Poza depresją ma udokumentowaną skuteczność w **bólowej neuropatii cukrzycowej**, fibromialgii i wysiłkowym nietrzymaniu moczu, bo noradrenalina wzmacnia zstępujące hamowanie bólu. Może podnosić ciśnienie tętnicze. Sertralina i fluwoksamina to **SSRI**, moklobemid — odwracalny inhibitor **MAO-A**, a mirtazapina — antagonista alfa2 z grupy NaSSA.$E$,
   'Leki przeciwdepresyjne', 'FARLEK-e2026-1-1850', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(179, 'FARM-12',
   'Lek, który hamuje syntezę leukotrienów przez blokadę 5-lipooksygenazy:',
   '[{"id": "a", "text": "Montelukast"}, {"id": "b", "text": "Zafirlukast"}, {"id": "c", "text": "Zileuton"}, {"id": "d", "text": "Pitrakinra"}, {"id": "e", "text": "Mepolizumab"}]'::jsonb,
   'c',
   $E$**Zileuton** blokuje **5-lipooksygenazę**, czyli pierwszy enzym szlaku przemiany kwasu arachidonowego do leukotrienów, dlatego hamuje powstawanie zarówno **LTB4** (chemotaksja), jak i leukotrienów cysteinylowych **LTC4, LTD4 i LTE4**. Wymaga dawkowania cztery razy na dobę i kontroli **aminotransferaz**, a przez hamowanie **CYP1A2** podnosi stężenie teofiliny. Montelukast i zafirlukast działają niżej w szlaku — blokują receptor **CysLT1**. Mepolizumab to przeciwciało anty-IL-5.$E$,
   'Leki przeciwleukotrienowe', 'FARLEK-e2026-1-1851', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(180, 'FARM-09',
   'Wskaż zdanie prawdziwe dotyczące ketaminy:',
   '[{"id": "a", "text": "Jest agonistą receptora NMDA"}, {"id": "b", "text": "Powoduje znieczulenie dysocjacyjne"}, {"id": "c", "text": "Silnie hamuje ośrodek oddechowy"}, {"id": "d", "text": "Wydłuża czas przewodnictwa przedsionkowo-komorowego"}, {"id": "e", "text": "Nasila reakcję baroreceptorową i bradykardię"}]'::jsonb,
   'b',
   $E$Ketamina wywołuje **znieczulenie dysocjacyjne**: chory sprawia wrażenie przytomnego (otwarte oczy, oczopląs), ale jest czynnościowo odcięty od bodźców wskutek rozkojarzenia układu **limbicznego** i kory. Jest **antagonistą**, a nie agonistą **NMDA**. Nie hamuje ośrodka oddechowego, zachowuje odruchy gardłowe i rozszerza oskrzela, co czyni ją cenną w stanie astmatycznym. Hamując wychwyt zwrotny noradrenaliny, **osłabia** odruch z baroreceptorów i wywołuje tachykardię.$E$,
   'Anestetyki dożylne', 'FARLEK-e2026-1-1852', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(181, 'FARM-05',
   'Rekombinowana ludzka interleukina 11, która przyspiesza dojrzewanie megakariocytów i zwiększa liczbę płytek krwi, to:',
   '[{"id": "a", "text": "Oprelwekina"}, {"id": "b", "text": "Romiplostym"}, {"id": "c", "text": "Pleryksafor"}, {"id": "d", "text": "Eltrombopag"}, {"id": "e", "text": "Roksadustat"}]'::jsonb,
   'a',
   $E$**Oprelwekina** jest rekombinowaną **interleukiną 11** — cytokiną pobudzającą proliferację komórek macierzystych i dojrzewanie **megakariocytów**, przez co zwiększa liczbę płytek. Stosuje się ją w zapobieganiu ciężkiej **małopłytkowości** po chemioterapii mielosupresyjnej. Charakterystyczne działania niepożądane wynikają z retencji płynów: obrzęki, tachykardia, wysięk w opłucnej i niedokrwistość z rozcieńczenia. **Romiplostym** i **eltrombopag** pobudzają natomiast receptor trombopoetyny.$E$,
   'Czynniki wzrostu układu krwiotwórczego', 'FARLEK-e2026-1-1853', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(182, 'FARM-16',
   'Do inhibitorów steroidogenezy nadnerczowej należy:',
   '[{"id": "a", "text": "Metyrapon"}, {"id": "b", "text": "Trilostan"}, {"id": "c", "text": "Aminoglutetymid"}, {"id": "d", "text": "Prawidłowe A i C"}, {"id": "e", "text": "Prawidłowe A, B i C"}]'::jsonb,
   'e',
   $E$Wszystkie trzy leki blokują kolejne etapy syntezy steroidów nadnerczowych. **Metyrapon** hamuje **11-beta-hydroksylazę**, przez co rośnie stężenie 11-deoksykortyzolu — wykorzystuje się to w teście metyraponowym oceniającym rezerwę **ACTH**. **Aminoglutetymid** blokuje **desmolazę** przekształcającą cholesterol w pregnenolon, dając efekt chemicznej adrenalektomii. **Trilostan** hamuje **3-beta-dehydrogenazę hydroksysteroidową**. Podobnie działa ketokonazol w dużych dawkach.$E$,
   'Inhibitory steroidogenezy', 'FARLEK-e2026-1-1854', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(183, 'FARM-14',
   'Antagonistą receptora chemokinowego CCR5, z którym łączy się gp120 wirusa przy wniknięciu do komórek, jest:',
   '[{"id": "a", "text": "Marawirok"}, {"id": "b", "text": "Enfuwirtyd"}, {"id": "c", "text": "Emtrycytabina"}, {"id": "d", "text": "Abakawir"}, {"id": "e", "text": "Dydanozyna"}]'::jsonb,
   'a',
   $E$**Marawirok** wiąże się z **koreceptorem CCR5** komórki gospodarza i zmienia jego konformację, uniemożliwiając przyłączenie wirusowej **gp120** — jest więc inhibitorem **wejścia** wirusa. Działa wyłącznie na szczepy o tropizmie **R5**, dlatego przed leczeniem obowiązkowe jest oznaczenie tropizmu; wobec wirusów X4 jest bezużyteczny. Wymaga monitorowania czynności wątroby. **Enfuwirtyd** blokuje inny etap — fuzję błon przez **gp41**, a pozostałe leki to NRTI.$E$,
   'Leki przeciwretrowirusowe', 'FARLEK-e2026-1-1855', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(184, 'FARM-14',
   'Do swoistych inhibitorów polimerazy RNA NS5B, stosowanych w leczeniu przewlekłego WZW typu C, należy:',
   '[{"id": "a", "text": "Sofosbuwir"}, {"id": "b", "text": "Dasabuwir"}, {"id": "c", "text": "Daklataswir"}, {"id": "d", "text": "Prawidłowe A i B"}, {"id": "e", "text": "Prawidłowe A, B i C"}]'::jsonb,
   'd',
   $E$**NS5B** to zależna od RNA polimeraza RNA, kluczowy enzym replikacji HCV. **Sofosbuwir** jest jej inhibitorem **nukleotydowym** — po fosforylacji wbudowuje się w nić i działa jako terminator łańcucha, a **dasabuwir** hamuje ten sam enzym **nienukleozydowo**, allosterycznie. **Daklataswir** działa natomiast na białko **NS5A**. Sofosbuwir stanowi dziś podstawę większości schematów bezinterferonowych, skutecznych wobec wszystkich genotypów HCV.
Mnemonik końcówek: **-buwir** to NS5B, **-aswir** to NS5A, a **-prewir** to proteaza NS3/4A.$E$,
   'Leczenie WZW typu C', 'FARLEK-e2026-1-1856', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(185, 'FARM-14',
   'Do swoistych inhibitorów polimerazy RNA NS5A, stosowanych w leczeniu przewlekłego WZW typu C, należy:',
   '[{"id": "a", "text": "Elbaswir"}, {"id": "b", "text": "Dasabuwir"}, {"id": "c", "text": "Daklataswir"}, {"id": "d", "text": "Prawidłowe A i C"}, {"id": "e", "text": "Prawidłowe A, B i C"}]'::jsonb,
   'd',
   $E$**Elbaswir** i **daklataswir** hamują białko **NS5A**, niezbędne do tworzenia kompleksu replikacyjnego i składania wirionów — rozpoznajemy je po końcówce **-aswir**. **Dasabuwir** ma końcówkę **-buwir**, więc działa na polimerazę **NS5B**. Leki bezpośrednio działające przeciwwirusowo stosuje się zawsze w skojarzeniu (np. elbaswir z grazoprewirem), co pozwala uzyskać trwałą odpowiedź wirusologiczną u ponad 95% chorych. Uwaga na ryzyko **reaktywacji HBV**.$E$,
   'Leczenie WZW typu C', 'FARLEK-e2026-1-1857', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(186, 'FARM-15',
   'Mechanizm działania soraprazanu polega na:',
   '[{"id": "a", "text": "Niekompetycyjnym i nieodwracalnym blokowaniu pompy protonowej"}, {"id": "b", "text": "Kompetycyjnym i nieodwracalnym blokowaniu pompy protonowej"}, {"id": "c", "text": "Kompetycyjnym i odwracalnym blokowaniu pompy protonowej"}, {"id": "d", "text": "Kompetycyjnym blokowaniu receptorów H2"}, {"id": "e", "text": "Niekompetycyjnym blokowaniu receptorów H2"}]'::jsonb,
   'c',
   $E$**Soraprazan** należy do **P-CAB** — blokerów pompy protonowej konkurujących o miejsce wiązania **jonów potasu** w **H+/K+-ATPazie**. Wiązanie jest **kompetycyjne i odwracalne**, dzięki czemu lek działa natychmiast, niezależnie od posiłku i od wcześniejszej aktywacji pompy kwasem, oraz dobrze kontroluje wydzielanie nocne. Klasyczne **IPP** (omeprazol) są prolekami i wiążą pompę **kowalencyjnie, nieodwracalnie**. Najbardziej znanym P-CAB jest wonoprazan.$E$,
   'Leki hamujące wydzielanie kwasu solnego', 'FARLEK-e2026-1-1858', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(187, 'FARM-15',
   'Zaznacz zdanie fałszywe:',
   '[{"id": "a", "text": "Antagonistów receptorów histaminowych H2 powinno się stosować w pojedynczej dawce na noc"}, {"id": "b", "text": "Omeprazol blokuje wydzielanie kwasu solnego stymulowane pokarmem, a także wydzielanie pepsyny"}, {"id": "c", "text": "Lansoprazol hamuje aktywność pompy protonowej, nasila także procesy gojenia śluzówki żołądka"}, {"id": "d", "text": "Baklofen jest stosowany w leczeniu refluksu przełyku, ze względu na pobudzanie receptorów GABAb"}, {"id": "e", "text": "Mizoprostol jest analogiem prostaglandyny I2"}]'::jsonb,
   'e',
   $E$**Mizoprostol** jest syntetycznym analogiem **prostaglandyny E1**, a nie prostacykliny. Pobudzając receptory **EP3** komórek okładzinowych, hamuje wydzielanie kwasu, a jednocześnie zwiększa produkcję śluzu i wodorowęglanów — dlatego chroni śluzówkę przy przewlekłym stosowaniu **NLPZ**. Silnie kurczy macicę, więc jest **przeciwwskazany w ciąży**. Pozostałe zdania są prawdziwe: baklofen zmniejsza przemijające relaksacje dolnego zwieracza przełyku przez receptory **GABA-B**.$E$,
   'Leczenie choroby wrzodowej i refluksu', 'FARLEK-e2026-1-1859', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(188, 'FARM-15',
   'Który spośród wymienionych leków nie jest stosowany jako lek przeciwbakteryjny podczas biegunki:',
   '[{"id": "a", "text": "Nifuroksazyd"}, {"id": "b", "text": "Ryfaksymina"}, {"id": "c", "text": "Cyprofloksacyna"}, {"id": "d", "text": "Furazydyna"}, {"id": "e", "text": "Azytromycyna"}]'::jsonb,
   'd',
   $E$**Furazydyna (furagina)** to pochodna nitrofuranu, która po wchłonięciu jest szybko wydalana przez nerki i osiąga stężenia bakteriobójcze wyłącznie w **drogach moczowych** — stosuje się ją w zakażeniach układu moczowego, nie w biegunce. Pozostałe leki działają w jelicie: **nifuroksazyd** i **ryfaksymina** praktycznie nie wchłaniają się z przewodu pokarmowego, a **cyprofloksacyna** i **azytromycyna** są lekami z wyboru w biegunce podróżnych i w zakażeniach inwazyjnych.$E$,
   'Leczenie biegunki', 'FARLEK-e2026-1-1860', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(189, 'FARM-17',
   'Który lek wywołuje wzrost masy ciała:',
   '[{"id": "a", "text": "Liraglutyd"}, {"id": "b", "text": "Bupropion"}, {"id": "c", "text": "Metformina"}, {"id": "d", "text": "Gliklazyd"}, {"id": "e", "text": "Wszystkie z wymienionych obniżają masę ciała"}]'::jsonb,
   'd',
   $E$**Gliklazyd** to pochodna **sulfonylomocznika**: zamyka kanał **KATP** komórki beta, wymuszając wydzielanie **insuliny** niezależnie od aktualnej glikemii. Utrzymujący się hiperinsulinizm działa **anabolicznie** i sprzyja przyrostowi masy ciała, a dodatkowo grozi **hipoglikemią**, którą chorzy kompensują podjadaniem. **Metformina** jest neutralna lub nieznacznie redukuje masę, **liraglutyd** hamuje łaknienie i opróżnianie żołądka, a **bupropion** z naltreksonem stosuje się w leczeniu otyłości.$E$,
   'Leki przeciwcukrzycowe a masa ciała', 'FARLEK-e2026-1-1861', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(190, 'FARM-17',
   'Lekiem stosowanym w leczeniu otyłości uwarunkowanej genetycznie jest:',
   '[{"id": "a", "text": "Naltrekson"}, {"id": "b", "text": "Setmelanotyd"}, {"id": "c", "text": "Akarboza"}, {"id": "d", "text": "Donepezyl"}, {"id": "e", "text": "Anakinra"}]'::jsonb,
   'b',
   $E$**Setmelanotyd** jest agonistą podwzgórzowego receptora melanokortynowego **MC4R** — odtwarza sygnał sytości w szlaku **leptyna-melanokortyna**, gdy jest on przerwany przez mutację. Zarejestrowano go w rzadkich otyłościach monogenowych z niedoborem **POMC**, **PCSK1** lub **receptora leptyny** oraz w zespole Bardeta-Biedla. Podaje się go podskórnie raz na dobę. Typowe działania niepożądane to **ciemnienie skóry** (pobudzenie MC1R), nudności i reakcje w miejscu wstrzyknięcia.$E$,
   'Leczenie otyłości', 'FARLEK-e2026-1-1862', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(191, 'FARM-18',
   'Lekiem z wyboru w zatruciu benzodiazepinami jest:',
   '[{"id": "a", "text": "Nalokson"}, {"id": "b", "text": "Flumazenil"}, {"id": "c", "text": "Atropina"}, {"id": "d", "text": "N-acetylocysteina"}, {"id": "e", "text": "Fizostygmina"}]'::jsonb,
   'b',
   $E$**Flumazenil** jest kompetycyjnym **antagonistą miejsca benzodiazepinowego** receptora GABA-A: wypiera lek z receptora i znosi sedację w ciągu 1-2 minut. Jego okres półtrwania (ok. **1 godziny**) jest jednak krótszy niż większości benzodiazepin, więc sedacja może nawrócić i konieczne bywają dawki powtarzane lub wlew. Nie wolno go stosować rutynowo u osób **uzależnionych od BZD** i po zatruciu **TLPD** — grozi drgawkami. Nalokson odwraca działanie opioidów.$E$,
   'Odtrutki', 'FARLEK-e2026-1-1863', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(192, 'FARM-15',
   'Wskaż lek działający poprzez nieodwracalne hamowanie pompy protonowej w komórkach okładzinowych żołądka:',
   '[{"id": "a", "text": "Ranitydyna"}, {"id": "b", "text": "Famotydyna"}, {"id": "c", "text": "Mizoprostol"}, {"id": "d", "text": "Omeprazol"}, {"id": "e", "text": "Sukralfat"}]'::jsonb,
   'd',
   $E$**Omeprazol** jest prolekiem: w kwaśnym środowisku kanalików wydzielniczych komórki okładzinowej przekształca się w sulfenamid, który **kowalencyjnie i nieodwracalnie** wiąże grupy **-SH** pompy **H+/K+-ATPazy**. Odtworzenie wydzielania wymaga syntezy nowych pomp, co trwa 24-48 godzin — stąd długie działanie mimo krótkiego okresu półtrwania. Lek przyjmuje się **30-60 minut przed posiłkiem**. Ranitydyna i famotydyna to odwracalni antagoniści receptora **H2**.$E$,
   'Leki hamujące wydzielanie kwasu solnego', 'FARLEK-e2026-1-1864', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(193, 'FARM-17',
   'Który z wymienionych leków jest inhibitorem SGLT-2 (kotransporter sodowo-glukozowy typu 2) i stosowany w cukrzycy typu 2?',
   '[{"id": "a", "text": "Sitagliptyna"}, {"id": "b", "text": "Eksenatyd"}, {"id": "c", "text": "Kanagliflozyna"}, {"id": "d", "text": "Akarboza"}, {"id": "e", "text": "Repaglinid"}]'::jsonb,
   'c',
   $E$**Kanagliflozyna** blokuje kotransporter **SGLT-2** w cewce bliższej, hamując zwrotne wchłanianie glukozy i wymuszając **glikozurię**. Efektem jest spadek HbA1c, masy ciała i ciśnienia tętniczego, a niezależnie od glikemii — mniejsze ryzyko hospitalizacji z powodu **niewydolności serca** i wolniejsza progresja przewlekłej choroby nerek. Działania niepożądane: zakażenia grzybicze narządów płciowych, odwodnienie i **euglikemiczna kwasica ketonowa**. Sitagliptyna hamuje DPP-4.$E$,
   'Leki przeciwcukrzycowe', 'FARLEK-e2026-1-1865', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(194, 'FARM-14',
   'Wskaż lek przeciwwirusowy stosowany w leczeniu COVID-19 w postaci doustnej:',
   '[{"id": "a", "text": "Oseltamiwir"}, {"id": "b", "text": "Remdesiwir"}, {"id": "c", "text": "Nirmatrelwir/rytonawir"}, {"id": "d", "text": "Acyklowir"}, {"id": "e", "text": "Gancyklowir"}]'::jsonb,
   'c',
   $E$**Nirmatrelwir** hamuje **proteazę główną 3CL** SARS-CoV-2, uniemożliwiając cięcie poliprotein wirusowych. Sam jest szybko metabolizowany, dlatego łączy się go z małą dawką **rytonawiru** — silnego inhibitora **CYP3A4**, który pełni rolę wyłącznie farmakokinetycznego wzmacniacza. Leczenie doustne trwa **5 dni** i musi rozpocząć się do 5 dni od wystąpienia objawów. Kluczowe są liczne **interakcje** (statyny, amiodaron, DOAC). Remdesiwir podaje się dożylnie.$E$,
   'Leki przeciwwirusowe', 'FARLEK-e2026-1-1866', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(195, 'FARM-16',
   'Lek stosowany w terapii krwawień z przewodu pokarmowego poprzez aktywację receptorów wazopresynowych w mięśniach gładkich naczyń trzewnych:',
   '[{"id": "a", "text": "Wazopresyna"}, {"id": "b", "text": "Desmopresyna"}, {"id": "c", "text": "Terlipresyna"}, {"id": "d", "text": "Oksytocyna"}, {"id": "e", "text": "Bromokryptyna"}]'::jsonb,
   'c',
   $E$**Terlipresyna** jest prolekiem wazopresyny o powolnym uwalnianiu, działającym głównie przez receptory **V1** w mięśniówce naczyń **trzewnych**. Ich skurcz zmniejsza napływ krwi do krążenia wrotnego i obniża ciśnienie w **żylakach przełyku**, dlatego lek stosuje się w krwotoku z żylaków oraz w **zespole wątrobowo-nerkowym**. Pobudzenie receptorów **V2** w nerkach daje efekt antydiuretyczny i grozi **hiponatremią**. Ryzyko niedokrwienia mięśnia sercowego i jelit.$E$,
   'Analogi wazopresyny', 'FARLEK-e2026-1-1867', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(196, 'FARM-09',
   'Wskaż lek stosowany jako anestetyk wziewny o bardzo niskim współczynniku rozpuszczalności krew/gaz, zapewniający szybkie wprowadzenie i wyprowadzenie ze znieczulenia:',
   '[{"id": "a", "text": "Halotan"}, {"id": "b", "text": "Izofluran"}, {"id": "c", "text": "Propofol"}, {"id": "d", "text": "Desfluran"}, {"id": "e", "text": "Enfluran"}]'::jsonb,
   'd',
   $E$**Desfluran** ma najniższy spośród anestetyków wziewnych współczynnik rozdziału **krew/gaz (ok. 0,42)** — słabo rozpuszcza się we krwi, więc prężność pęcherzykowa szybko zrównuje się z mózgową, dając błyskawiczną indukcję i wybudzenie, korzystne w chirurgii jednego dnia i u chorych otyłych. Wadą jest **drażniący zapach** wykluczający indukcję wziewną, pobudzenie współczulne przy gwałtownym zwiększaniu stężenia i konieczność stosowania podgrzewanego parownika.$E$,
   'Anestetyki wziewne', 'FARLEK-e2026-1-1868', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(197, 'FARM-19',
   'Leki biologiczne stosowane w leczeniu zaawansowanego raka sutka i gruczolakoraka żołądka, wykazujących ekspresję receptora HER2:',
   '[{"id": "a", "text": "Trastuzumab i pertuzumab"}, {"id": "b", "text": "Bewacyzumab i cetuksymab"}, {"id": "c", "text": "Niwolumab i ipilimumab"}, {"id": "d", "text": "Imatynib i sunitynib"}, {"id": "e", "text": "Nilotynib i dazatynib"}]'::jsonb,
   'a',
   $E$**Trastuzumab** wiąże zewnątrzkomórkową domenę receptora **HER2**, hamując sygnał proliferacyjny i uruchamiając cytotoksyczność zależną od przeciwciał (**ADCC**), natomiast **pertuzumab** blokuje inną domenę i uniemożliwia **dimeryzację HER2 z HER3** — działają więc komplementarnie i podaje się je łącznie z chemioterapią. Głównym zagrożeniem jest **kardiotoksyczność**, zwłaszcza po antracyklinach, dlatego konieczna jest okresowa kontrola frakcji wyrzutowej.$E$,
   'Leki ukierunkowane molekularnie', 'FARLEK-e2026-1-1869', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(198, 'FARM-19',
   'Wskaż lek będący inhibitorem topoizomerazy I:',
   '[{"id": "a", "text": "Winblastyna"}, {"id": "b", "text": "Etopozyd"}, {"id": "c", "text": "Irynotekan"}, {"id": "d", "text": "Bleomycyna"}, {"id": "e", "text": "Cyklofosfamid"}]'::jsonb,
   'c',
   $E$**Irynotekan** jest prolekiem przekształcanym do aktywnego metabolitu **SN-38**, który stabilizuje kompleks **topoizomerazy I** z przeciętą nicią DNA i uniemożliwia jej ponowne połączenie — w fazie **S** prowadzi to do trwałych pęknięć. Stosuje się go w raku jelita grubego (schemat FOLFIRI). Charakterystyczne są **wczesna biegunka cholinergiczna** (odwracana atropiną), biegunka późna i neutropenia, nasilone przy polimorfizmie **UGT1A1**. Etopozyd hamuje topoizomerazę II.$E$,
   'Inhibitory topoizomeraz', 'FARLEK-e2026-1-1870', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(199, 'FARM-09',
   'Wskaż lek stosowany w znieczuleniu miejscowym o najkrótszym czasie działania:',
   '[{"id": "a", "text": "Bupiwakaina"}, {"id": "b", "text": "Ropiwakaina"}, {"id": "c", "text": "Lidokaina"}, {"id": "d", "text": "Prokaina"}, {"id": "e", "text": "Tetrakaina"}]'::jsonb,
   'd',
   $E$**Prokaina** to **ester** o najkrótszym czasie działania — około **45-60 minut** — ponieważ jest błyskawicznie hydrolizowana przez **esterazy osoczowe** do PABA. Słabo penetruje też tkanki, więc nie nadaje się do znieczulenia powierzchniowego. **Lidokaina** działa pośrednio długo (1-2 godziny), a **bupiwakaina, ropiwakaina i tetrakaina** nawet kilka godzin, bo są bardziej **lipofilne** i silniej wiążą się z białkami. Dodatek **adrenaliny** wydłuża blokadę i zmniejsza toksyczność ogólną.$E$,
   'Leki znieczulające miejscowo', 'FARLEK-e2026-1-1871', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[]),
(200, 'FARM-12',
   'Wskaż lek stosowany w terapii mukowiscydozy poprawiający funkcję białka CFTR:',
   '[{"id": "a", "text": "Erlotynib"}, {"id": "b", "text": "Iwakaftor"}, {"id": "c", "text": "Bosentan"}, {"id": "d", "text": "Sirolimus"}, {"id": "e", "text": "Natalizumab"}]'::jsonb,
   'b',
   $E$**Iwakaftor** jest **potencjatorem CFTR**: zwiększa prawdopodobieństwo otwarcia kanału chlorkowego, który dotarł już do błony komórkowej, dlatego działa w mutacjach zaburzających **bramkowanie**, klasycznie **G551D**. W najczęstszej mutacji **F508del** białko nie osiąga błony, więc konieczne jest dołączenie **korektorów** — tezakaftoru, eleksakaftoru lub lumakaftoru. Leczenie poprawia **FEV1**, masę ciała i obniża stężenie chlorków w pocie. Wymaga kontroli aminotransferaz.$E$,
   'Mukowiscydoza', 'FARLEK-e2026-1-1872', 'e_farm_lek_2026/1',
   'Egzamin farmakologia LEK SUM 2026 (FARLEK e2026-1)', ARRAY['lekarski']::TEXT[])
),
maxes AS (
  SELECT topic_id,
         COALESCE(MAX((regexp_match(id, topic_id || '-([0-9]+)$'))[1]::int), 0) AS mx
    FROM public.questions WHERE topic_id IN ('FARM-01', 'FARM-02', 'FARM-03', 'FARM-04', 'FARM-05', 'FARM-06', 'FARM-07', 'FARM-08', 'FARM-09', 'FARM-10', 'FARM-11', 'FARM-12', 'FARM-13', 'FARM-14', 'FARM-15', 'FARM-16', 'FARM-17', 'FARM-18', 'FARM-19') GROUP BY topic_id
)
INSERT INTO public.questions
  (id, topic_id, text, options, correct_option_id, explanation,
   subtheme_label, source_code, batch_label, source_exam, theme_label, tracks)
SELECT
  n.topic_id || '-' || LPAD((COALESCE(m.mx,0) + ROW_NUMBER() OVER (PARTITION BY n.topic_id ORDER BY n.seq))::text, 3, '0'),
  n.topic_id, n.qtext, n.opts, n.correct, n.expl,
  n.subtheme, n.srccode, n.batch, n.exam, '2026', n.tracks
FROM new_rows n LEFT JOIN maxes m ON m.topic_id = n.topic_id;

UPDATE public.topics t SET question_count = sub.cnt
  FROM (SELECT topic_id, COUNT(*) AS cnt FROM public.questions
         WHERE topic_id IN ('FARM-01', 'FARM-02', 'FARM-03', 'FARM-04', 'FARM-05', 'FARM-06', 'FARM-07', 'FARM-08', 'FARM-09', 'FARM-10', 'FARM-11', 'FARM-12', 'FARM-13', 'FARM-14', 'FARM-15', 'FARM-16', 'FARM-17', 'FARM-18', 'FARM-19') AND COALESCE(is_active,true)=true GROUP BY topic_id) sub
 WHERE t.id = sub.topic_id;
